import {AppError} from "@/shared/lib/error/AppError";
import {FolderMetaDto} from "@/shared/api/fileManager/dto";

export class FolderMeta {
    permissions: number;
    mTime: number;
    aTime: number;
    size: number;

    constructor(meta: FolderMetaDto | null | undefined) {

        if (!(typeof meta === 'object' && meta !== null && !Array.isArray(meta))) {
          throw new AppError('Meta must be an object',{received: meta});
        }

        if (meta == null) {
          throw new AppError('Некорректные метаданные директории');
        }
        if (typeof meta.permissions !== 'number' || meta.permissions < 0) {
          throw new AppError('Некорректное значение meta.permissions');
        }
        if (typeof meta.mTime !== 'number' || meta.mTime < 0) {
          throw new AppError('Некорректное значение meta.mTime');
        }
        if (typeof meta.aTime !== 'number' || meta.aTime < 0) {
          throw new AppError('Некорректное значение meta.aTime');
        }
        if (typeof meta.size !== 'number' || meta.size < 0) {
          throw new AppError('Некорректное значение meta.size');
        }

        this.permissions = meta.permissions;
        this.mTime = meta.mTime;
        this.aTime = meta.aTime;
        this.size = meta.size;
    }
}

