// src/features/upload/model/UploadFeature.ts
import type {FileManagerEventBus} from '@/shared/lib/EventBus';
import {UploadService} from './UploadService';
import type {IFileManagerBackend} from '@/shared/api/fileManager/ports';
import {IFeature} from "@/shared/lib/Feature";
import {IObservable} from "@/shared/lib/Observable";
import {LoadingStore} from "@/features/app-status/model/LoadingStore";
import {DiagnosticService} from "@/shared/lib/diagnostics/DiagnosticService";

export class UploadFeature implements IFeature {
  private service: UploadService;
  private unsubs: (() => void)[] = [];

  constructor(
    private readonly bus: FileManagerEventBus,
    backend: IFileManagerBackend,
    private navState: IObservable<string>,
    private loadingStore: LoadingStore,
    private diagnostics: DiagnosticService,
  ) {
    this.service = new UploadService(backend, this.bus, this.diagnostics);
  }

  init() {
    this.unsubs.push(
      this.bus.on('upload:drop', async (payload: FileList | { path?: string; files: FileList }) => {
        const files = payload instanceof FileList ? payload : payload.files;
        const explicitPath = payload instanceof FileList ? undefined : payload.path;
        const path = explicitPath ?? this.navState.getValue();

        try {
          this.loadingStore.startOperation();
          await this.service.upload({path, files});

          this.diagnostics.notice(
            'Загружено файлов: ' + files.length + '; Путь: \'' + explicitPath + '\'',
            { source: 'upload', userVisible: true }
          );

          this.bus.emit('nav:refresh', path);
        } catch (e) {
          console.error('Upload error:', e);
        } finally {
          this.loadingStore.endOperation();
        }

      }),
    );

    // 1. Отмена
    this.unsubs.push(
      this.bus.on('upload:cancel-all', () => {
        try {
          this.loadingStore.startOperation();
          this.service.cancelAll();
        } catch (e) {
          console.error('Upload cancelling error:', e);
        } finally {
          this.loadingStore.endOperation();
        }
      })
    );

    // 2. Повтор
    this.unsubs.push(
      this.bus.on('upload:retry', async ({fileName}) => {
        try {
          this.loadingStore.startOperation();
          await this.service.retry(fileName);
        } catch (e) {
          console.error('Upload retrying error:', e);
        } finally {
          this.loadingStore.endOperation();
        }
      })
    );
  }

  destroy() {
    this.unsubs.forEach(unsub => unsub());
  }
}
