import {BaseOpenableWC} from './BaseOpenableWC';
import styles from './scss/alert.scss';

const sheet = new CSSStyleSheet();
sheet.replaceSync(styles);

//  Показ уведомлений сделать на пару секунд, но сделать возможность просмотра статистики и истории уведомлений.
//  Сделать в виде веб-компонента.

export class AlertWC extends BaseOpenableWC {
  private content: HTMLElement | null = null;

  connectedCallback(): void {
    if (this.shadowRoot) return;

    const shadow = this.attachShadow({mode: 'open'});
    shadow.adoptedStyleSheets = [sheet];
    shadow.innerHTML = this.getTemplate();
    this.content = shadow.querySelector('.content');
  }

  private getTemplate(): string {
    return `<div class='content'></div>`;
  }

  show(content: HTMLElement, time: number): () => void {
    this.content!.innerHTML = '';
    this.content!.appendChild(content);
    this.open = true;

    let timeoutId: number | null = null;

    if (time !== 0) {
      timeoutId = window.setTimeout(() => {
        this.open = false;
      }, time);
    }

    return () => {
      if (timeoutId !== null) {
        clearTimeout(timeoutId);
      }
      this.open = false;
    };
  }
}

customElements.define('alert-wc', AlertWC);
