// src/shared/lib/EventBus.ts

import type {FMEventMap} from './fm-events';

/**
 * Как использовать (пример)
 * private cleanup?: () => void;
 * connectedCallback() {
 *   this.cleanup = bus.auto(this, 'nav:openDir', (path) => {
 *     if (path === this.folder.key) {
 *       this.classList.add('active');
 *     }
 *   });
 * }
 *
 * disconnectedCallback() {
 *   // Ничего не делаем вручную — отписка автоматическая!
 * }
 */

// Вспомогательные типы
type Handler<T = unknown> = (payload: T) => void;
type AnyHandler = (payload: unknown) => void;

/**
 * Универсальная шина событий.
 * Используется вместо твоего старого Dispatcher.
 */
export class EventBus<Events extends object> {
  // Храним обработчики: ключ — имя события, значение — Set функций
  private handlers = new Map<keyof Events, Set<AnyHandler>>();

  constructor(private debug = false) {
  }

  /**
   * Подписаться на событие
   */
  on<K extends keyof Events>(
    event: K,
    handler: Handler<Events[K]>
  ): () => void {
    if (!this.handlers.has(event)) {
      this.handlers.set(event, new Set<AnyHandler>());
    }

    // Приводим к AnyHandler — безопасно, потому что мы контролируем типы выше
    this.handlers.get(event)!.add(handler as AnyHandler);

    // Возвращаем функцию отписки
    return () => this.off(event, handler);
  }

  /**
   * Подписаться на событие только один раз
   */
  once<K extends keyof Events>(
    event: K,
    handler: Handler<Events[K]>
  ): void {
    const wrapper: Handler<Events[K]> = (payload) => {
      handler(payload);
      this.off(event, wrapper);
    };
    this.on(event, wrapper);
  }

  /**
   * Отписаться
   */
  off<K extends keyof Events>(
    event: K,
    handler: Handler<Events[K]>
  ): void {
    this.handlers.get(event)?.delete(handler as AnyHandler);
  }

  /**
   * Опубликовать событие
   *  - для событий с payload: emit('nav:openDir', '/path')
   *  - для void-событий:      emit('modal:loader:show')
   */
  emit<K extends keyof Events>(
    event: K,
    ...args: Events[K] extends void ? [] : [Events[K]]
  ): void {

    if (this.debug) console.debug('[FM BUS]', event, args);

    const handlers = this.handlers.get(event);
    if (!handlers) return;

    // Для void-событий args = [], args[0] === undefined → это ок для Handler<void>
    const payload = args[0] as Events[K];

    for (const handler of [...handlers]) {
      try {
        (handler as Handler<Events[K]>)(payload);
      } catch (err) {
        console.error(`Ошибка в обработчике события "${String(event)}":`, err);
      }
    }
  }

  /**
   * Удалить все обработчики (например, при destroy())
   */
  clear(): void {
    this.handlers.clear();
  }

  /** Для веб-компонентов */
    // === Автоматическая отписка при disconnectedCallback ===
  private static cleanupMap = new WeakMap<HTMLElement, Set<() => void>>();

  auto<K extends keyof Events>(
    component: HTMLElement & { disconnectedCallback?(): void },
    event: K,
    handler: Handler<Events[K]>
  ): () => void {
    const unsubscribe = this.on(event, handler);

    let cleanups = EventBus.cleanupMap.get(component);
    if (!cleanups) {
      cleanups = new Set<() => void>();
      EventBus.cleanupMap.set(component, cleanups);

      const originalDisconnected = component.disconnectedCallback;
      component.disconnectedCallback = function (this: HTMLElement) {
        cleanups!.forEach(fn => fn());
        cleanups!.clear();
        originalDisconnected?.call(this);
      };
    }

    cleanups.add(unsubscribe);

    return unsubscribe;
  }
}

// Конкретная шина для файлового менеджера
export type FileManagerEventBus = EventBus<FMEventMap>;
export type {FMEventMap}; // чтобы AppRuntime мог импортировать
