import styles from '@/picker/styles.scss';

/**
 * Лёгкий оверлей состояния (загрузка/ошибка), показываемый до готовности дерева.
 *
 * Переиспользует те же стили в Shadow DOM, что и основной пикер, чтобы визуально совпадать.
 * Отдельный от вью, потому что живёт в другой фазе жизненного цикла (пока данных ещё нет).
 */
export class StateOverlay {
  private readonly host: HTMLElement;
  private readonly shadow: ShadowRoot;
  private readonly messageEl: HTMLElement;

  constructor(private readonly onClose: () => void) {
    this.host = document.createElement('div');
    this.host.setAttribute('data-snippets-state', '');
    this.shadow = this.host.attachShadow({mode: 'open'});
    this.messageEl = document.createElement('div');
    this.messageEl.className = 'state';
  }

  mount(message: string): void {
    this.messageEl.textContent = message;

    const style = document.createElement('style');
    style.textContent = styles;

    const backdrop = document.createElement('div');
    backdrop.className = 'backdrop';
    backdrop.addEventListener('mousedown', (e) => {
      if (e.target === backdrop) {
        this.onClose();
      }
    });

    const modal = document.createElement('div');
    modal.className = 'modal';
    modal.style.height = 'auto';
    modal.appendChild(this.messageEl);
    backdrop.appendChild(modal);

    this.shadow.append(style, backdrop);
    document.body.appendChild(this.host);
  }

  showError(message: string): void {
    this.messageEl.className = 'state error';
    this.messageEl.textContent = message;
  }

  destroy(): void {
    this.host.remove();
  }
}
