import {NavigationService} from "./NavigationService";
import type {FileManagerEventBus} from '@/shared/lib/EventBus';
import {IFeature} from "@/shared/lib/Feature";
import type {IFileManagerBackend} from "@/shared/api/fileManager/ports";
import {FolderRegistry} from "@/entities/folder/model/FolderRegistry";
import {NavigationState} from "./NavigationState";
import {LoadingStore} from "@/features/app-status/model/LoadingStore";

export class NavigationFeature implements IFeature {
  private unsubs: (() => void)[] = [];
  private service: NavigationService;

  constructor(
    private bus: FileManagerEventBus,
    backend: IFileManagerBackend,
    registry: FolderRegistry,
    private navState: NavigationState,
    loadingStore: LoadingStore,
  ) {
    this.service = new NavigationService(backend, registry, this.navState, loadingStore);
  }

  init() {
    // 1. Слушаем запрос на открытие (например, по дабл-клику в дереве)
    this.unsubs.push(
      this.bus.on('nav:openDir', async (path: string) => {
        await this.service.navigate(path); // Вся логика внутри сервиса
      })
    );

    // === ДОБАВЛЯЕМ ПОДПИСКУ НА REFRESH ===
    this.unsubs.push(
      this.bus.on('nav:refresh', async (pathOverride?: string) => {
        // Если путь передали (например, после rename), обновляем его.
        // Если нет (null/undefined) — обновляем текущий активный путь.
        const path = pathOverride || this.navState.getValue();

        // Передаем true вторым аргументом (forceRefresh)
        await this.service.navigate(path, true);
      })
    );

    // 2. Слушаем изменение пути в сервисе и кидаем событие для остальных (Legacy listener)
    this.unsubs.push(
      this.service.state.subscribe((newPath) => {
        this.bus.emit('nav:loaded', newPath);
      })
    );
  }

  async navigate(path: string): Promise<void> {
    return await this.service.navigate(path);
  }

  destroy() {
    this.unsubs.forEach(u => u());
  }
}
