import {handleOutsideClick,} from "@/shared/lib/dom/pointer-events";
import {getPointerPosition} from "@/shared/lib/dom/GestureHelper";
import {ContextMenuItem} from "./ContextMenuItem";

import styles from './scss/context-menu.scss';

const sheet = new CSSStyleSheet();
sheet.replaceSync(styles);

export class ContextMenuWC extends HTMLElement {
  private container: HTMLElement | null = null;
  private unSubscribers: Array<() => void> = [];
  private _items: ContextMenuItem[] = [];

  connectedCallback() {
    if (this.shadowRoot) return;
    const shadow = this.attachShadow({mode: 'open'});
    shadow.adoptedStyleSheets = [sheet];
    this.container = document.createElement('ul');
    shadow.appendChild(this.container);

    /** Обработка клика вне контекстного меню (закрытие меню) */
    this.unSubscribers.push(
      handleOutsideClick(this, () => {
        this.hide();
      })
    );

    /** Обработка клика по пункту меню. */
    this.unSubscribers.push(
      this.detectMenuItemClick()
    );

    // Инициализация при подключении, если атрибут уже установлен
    const initialItems = this.getAttribute('items');
    if (initialItems) {
      this.items = initialItems;
    }
  }

  disconnectedCallback() {
    this.unSubscribers.forEach((unSubscriber: () => void) => {
      unSubscriber();
    });
  }


// ============================================

  static get observedAttributes(): string[] {
    return ['items'];
  }

  attributeChangedCallback(name: string, oldValue: string | null, newValue: string | null): void {
    if (name === 'items' && newValue !== oldValue && newValue !== null) {
      // Вызываем сеттер, который парсит, проверяет и рендерит
      this.items = newValue;
    }
  }

  get items() {
    return JSON.stringify(this._items.map(item => item['data']));
  }

  /**
   * Сеттер, который принимает JSON-строку, парсит ее, проверяет и обновляет UI.
   */
  set items(jsonString: string) {
    let parsedItems: unknown;
    try {
      parsedItems = JSON.parse(jsonString);
    } catch (e: unknown) {
      this.clear();
      throw new Error(`ContextMenuWC: Invalid JSON format for items. + ${e instanceof Error ? e.message : ''}`);
    }

    // 1. Проверка: это должен быть массив
    if (!Array.isArray(parsedItems)) {
      this.clear();
      throw new Error('Items must be an array.');
    }

    const newItems: ContextMenuItem[] = [];

    // 2. Итерируемся, используя ContextMenuItem для валидации и создания экземпляров
    for (const itemData of parsedItems) {
      try {
        // ContextMenuItem.create() выполняет всю валидацию
        const itemInstance = ContextMenuItem.create(itemData);
        newItems.push(itemInstance);
      } catch (e: unknown) {
        this.clear();
        // Пробрасываем ошибку валидации
        throw new Error(`ContextMenuWC: Failed to validate or create ContextMenuItem: ${e instanceof Error ? e.message : 'Unknown error'}`);
      }
    }

    // Если все успешно, обновляем внутреннее состояние и перерисовываем
    this._items = newItems;
    this.setItems(this._items);
  }

// ============================================


  protected detectMenuItemClick(): () => void {
    const menuItemClickListener = (event: MouseEvent) => {
      const target = event.target as HTMLElement;
      if (!(target instanceof HTMLLIElement)) {
        return;
      }
      // Разделители, summary, disabled-пункты — неактивны
      if (target.classList.contains('separator') || target.classList.contains('summary') || target.classList.contains('disabled')) {
        return;
      }
      this.dispatchEvent(
        new CustomEvent('contextmenu:action',
          {
            detail: {
              action: target.dataset.action,
              event: event,
            },
            bubbles: true,
            composed: true,
          }
        ),
      );

      this.hide();
    };

    this.container!.addEventListener('pointerup', menuItemClickListener);
    return () => {
      this.container!.removeEventListener('pointerup', menuItemClickListener);
    };
  }

  /**
   * Принимает массив ContextMenuItem и использует их метод render().
   * @param items - Массив валидных экземпляров ContextMenuItem.
   */
  protected setItems(items: ContextMenuItem[]) {
    const newItems: HTMLLIElement[] = items.map((item: ContextMenuItem) => item.render());
    this.container!.replaceChildren(...newItems);
  }

  protected updatePosition({x, y}: { x: number; y: number }) {
    // Получаем размеры контекстного меню
    const menuWidth = this.offsetWidth;
    const menuHeight = this.offsetHeight;

    // Получаем размеры окна браузера и текущую прокрутку
    const windowWidth = window.innerWidth;
    const windowHeight = window.innerHeight;
    const scrollX = window.scrollX || window.pageXOffset;
    const scrollY = window.scrollY || window.pageYOffset;

    // Корректируем позицию по горизонтали, если меню выходит за правый край
    if (x + menuWidth > windowWidth + scrollX) {
      x = windowWidth + scrollX - menuWidth - 5; // 5px - отступ от края
    } else if (x < scrollX) {
      x = scrollX + 5; // 5px - отступ от левого края
    }

    // Корректируем позицию по вертикали, если меню выходит за нижний край
    if (y + menuHeight > windowHeight + scrollY) {
      y = windowHeight + scrollY - menuHeight - 5; // 5px - отступ от края
    } else if (y < scrollY) {
      y = scrollY + 5; // 5px - отступ от верхнего края
    }

    // Устанавливаем новые координаты относительно видимой области
    this.setPosition({x, y});
  }

  public setPosition({x, y}: { x: number; y: number }) {
    this.style.left = `${x}px`;
    this.style.top = `${y}px`;
  }

  public show(event: PointerEvent) {
    this.classList.add('active');
    this.updatePosition(getPointerPosition(event));
  }

  protected hide() {
    this.clear();
    this.classList.remove('active');
  }

  protected clear() {
    this._items = [];
    this.setItems([]);
  }

}

customElements.define('context-menu-wc', ContextMenuWC);
