// src/features/context-menu/model/ContextMenuService.ts
import {MENU_CONFIG, type MenuItem} from '../lib/menu-config';
import {AppError} from "@/shared/lib/error/AppError";
import {SelectionState} from "@/features/selection/model/SelectionStore";
import {IObservable} from "@/shared/lib/Observable";

export class ContextMenuService { // TODO сервисы не должны знать про шину событий???????
  constructor(private selectionState: IObservable<SelectionState>) {
  }

  getMenuItems(): MenuItem[] {
    switch (this.selectionState.getValue().type) {
      case 'empty':
        return MENU_CONFIG.empty();

      case 'single-file':
        return MENU_CONFIG.singleFile();

      case 'multiple-files':
        return MENU_CONFIG.multipleFiles();

      case 'single-folder':
        return MENU_CONFIG.singleFolder();

      case 'multiple-folders':
        return MENU_CONFIG.multipleFolders();

      case 'mixed':
        return MENU_CONFIG.mixed();

      default:
        throw new AppError(
          `ContextMenuService cannot get menu items for selection type "${this.selectionState.getValue().type}"`
        );
    }
  }
}
