// src/features/selection/model/SelectionStore.ts
import {Observable} from "@/shared/lib/Observable";
import {DirectorySelectionDetail} from "@/shared/ui/directory-content-desktop/DirectoryContentWC";
import {AppError} from "@/shared/lib/error/AppError";

// 1. Тип выделения (должен быть импортирован или определен здесь)
export type SelectionType =
  'empty' |
  'single-folder' |
  'multiple-folders' |
  'single-file' |
  'multiple-files' |
  'mixed';

// Тип T для нашего Observable
export type SelectionState = {
  type: SelectionType;
  count: number;        // Общее количество выделенных элементов
  folders: Set<string>; // Набор ключей папок
  files: Set<string>;   // Набор ключей файлов
};

/**
 * Хранилище, отвечающее за состояние выделения (Selection).
 * Наследует функциональность подписки/уведомления от Observable.
 */
export class SelectionStore extends Observable<SelectionState> {
  constructor() {
    // Инициализируем родительский класс
    super({
      folders: new Set(),
      files: new Set(),
      count: 0,
      type: 'empty'
    });
  }

  /**
   * Обновляет выделение на основе набора элементов, полученного от UI-компонента.
   * @param selectionSet - Набор объектов { type: 'file' | 'folder', key: string }
   */
  public setSelection(selectionSet: DirectorySelectionDetail) {
    const newFiles = new Set<string>();
    const newFolders = new Set<string>();

    // 1. Разделяем ключи на файлы и папки
    selectionSet.forEach(item => {
      // Защита от 'empty' или других неожиданных типов, которые WC может бросить
      if (item.type === 'file') {
        newFiles.add(item.key);
      } else if (item.type === 'folder') {
        newFolders.add(item.key);
      } else {
        throw new AppError('Unknown item type of: "' + item.key + '"');
      }
    });

    const folderCount = newFolders.size;
    const fileCount = newFiles.size;
    const newCount = folderCount + fileCount;
    let newType: SelectionType = 'empty';

    // 2. Определяем точный SelectionType
    if (newCount === 0) {
      newType = 'empty';
    } else if (folderCount > 0 && fileCount > 0) {
      newType = 'mixed'; // Файлы И папки
    } else if (folderCount > 0) {
      // Выделены только папки
      newType = folderCount === 1 ? 'single-folder' : 'multiple-folders';
    } else if (fileCount > 0) {
      // Выделены только файлы
      newType = fileCount === 1 ? 'single-file' : 'multiple-files';
    } else {
      // Недостижимое состояние при правильной логике, но для TS-компилятора
      newType = 'empty';
    }

    const newState: SelectionState = {
      folders: newFolders,
      files: newFiles,
      count: newCount,
      type: newType
    };

    // 3. Обновляем состояние и уведомляем подписчиков
    this.setState(newState);
  }
  /**
   * Очищает выделение.
   */
  public clear() {
    this.setState({
      folders: new Set(),
      files: new Set(),
      count: 0,
      type: 'empty'
    });
  }
}
