// src/widgets/file-manager/FileManagerWidget.ts

import { Container, DI_TOKENS, getFeatureTokens } from '@/app/di';
import { IFeature } from '@/shared/lib/Feature';
import { FileManagerLayout } from './ui/FileManagerLayout';
import { NavigationFeature } from '@/features/navigation';
import { NavigationState } from '@/features/navigation/model/NavigationState';
import { ViewModeStore } from '@/features/directory-content/model/ViewModeStore';
import { LogVisibilityStore } from '@/features/log/model/LogVisibilityStore';
import { MenuBarItem } from '@/shared/ui/menu/MenuBarWC';
import { MappedObservable, Unsubscriber } from '@/shared/lib/Observable';
import { ICONS } from '@/shared/ui/icons';
import type { FileManagerEventBus } from '@/shared/lib/EventBus';

/**
 * FileManagerWidget — оркестратор фич.
 *
 * Теперь НЕ создаёт зависимости сам, а получает готовый DI-контейнер.
 * Ответственность:
 * - Инициализация всех фич
 * - Конфигурация меню
 * - Запуск приложения
 * - Уничтожение при закрытии
 */
export class FileManagerWidget {
  private features: IFeature[] = [];

  // Кешируем часто используемые зависимости для удобства
  private readonly layout: FileManagerLayout;
  private readonly bus: FileManagerEventBus;
  private readonly navState: NavigationState;
  private readonly viewModeStore: ViewModeStore;
  private readonly logVisibilityStore: LogVisibilityStore;

  constructor(private readonly container: Container) {
    // Получаем основные зависимости из контейнера
    this.layout = container.get(DI_TOKENS.LAYOUT);
    this.bus = container.get(DI_TOKENS.BUS);
    this.navState = container.get(DI_TOKENS.NAV_STATE);
    this.viewModeStore = container.get(DI_TOKENS.VIEW_MODE_STORE);
    this.logVisibilityStore = container.get(DI_TOKENS.LOG_VISIBILITY_STORE);
  }

  /**
   * Инициализирует все фичи и запускает приложение
   */
  async init(): Promise<void> {
    // 1. Получаем все фичи из контейнера
    this.features = this.resolveFeatures();

    // 2. Настраиваем меню
    this.layout.menu.setItems(this.getMenuItems());

    // 3. Инициализируем все фичи параллельно
    await Promise.all(this.features.map(f => f.init()));

    // 4. Запускаем первую навигацию
    await this.start();
  }

  /**
   * Получает все фичи из DI-контейнера
   */
  private resolveFeatures(): IFeature[] {
    const tokens = getFeatureTokens();
    const features: IFeature[] = [];

    for (const token of tokens) {
      try {
        const feature = this.container.get<IFeature>(token);
        features.push(feature);
      } catch (e) {
        // Некоторые фичи могут быть опциональными (например, uploadProgress)
        console.warn(`[FileManagerWidget] Фича "${token}" не найдена:`, e);
      }
    }

    return features;
  }

  /**
   * Запускает первую загрузку данных
   */
  private async start(): Promise<void> {
    const navFeature = this.container.get<NavigationFeature>(DI_TOKENS.FEATURE_NAVIGATION);
    await navFeature.navigate(this.navState.getValue());
  }

  /**
   * Конфигурация меню.
   * Вынесено отдельно, чтобы можно было переопределить в наследниках.
   */
  protected getMenuItems(): MenuBarItem[] {
    return [
      {
        id: 'refresh',
        icon: ICONS.REFRESH,
        action: () => this.bus.emit('nav:refresh', this.navState.getValue()),
      },
      {
        id: 'create-folder',
        icon: ICONS.FOLDER_PLUS,
        action: () => this.bus.emit('create:folder:start'),
      },
      {
        id: 'upload',
        icon: ICONS.UPLOAD,
        action: () => this.bus.emit('upload:request'),
      },
      {
        id: 'view-mode-toggle',
        label: new MappedObservable(this.viewModeStore, (mode) =>
          mode === 'grid' ? 'Список' : 'Плитка'
        ),
        icon: new MappedObservable(this.viewModeStore, (mode) =>
          mode === 'grid' ? ICONS.LIST : ICONS.GRID
        ),
        action: () => this.viewModeStore.toggle(),
      },
      {
        id: 'log',
        label: 'Лог',
        action: () => this.bus.emit('log:toggle'),
        isActive: {
          subscribe: (callback): Unsubscriber =>
            this.logVisibilityStore.subscribe(state => callback(state.visible)),
          getValue: () => this.logVisibilityStore.getValue().visible,
        },
      },
    ];
  }

  /**
   * Уничтожает виджет и все его зависимости
   */
  destroy(): void {
    // Уничтожаем все фичи
    this.features.forEach(f => f.destroy());
    this.features = [];

    // Уничтожаем layout (удаляет DOM)
    this.layout.destroy();

    // Очищаем контейнер
    this.container.clear();
  }
}
