import type {FileManagerEventBus} from '@/shared/lib/EventBus';
import type {DropzoneWC} from '@/shared/ui/dropzone/DropzoneWC';
import {FileManagerLayout} from "@/widgets/file-manager/ui/FileManagerLayout";
import {IObservable} from "@/shared/lib/Observable";
import {SelectionState} from "@/features/selection/model/SelectionStore";
import {IFeature} from "@/shared/lib/Feature";

export class DropZoneFeature  implements IFeature{
  private readonly overlay: DropzoneWC;
  private pathOverride?: string;
  private unsubs: (() => void)[] = [];

  constructor(
    private readonly bus: FileManagerEventBus,
    private readonly view: FileManagerLayout,
    private selectionState: IObservable<SelectionState>,
    private navState: IObservable<string> // Текущий путь
  ) {
    this.overlay = this.view.dropZone;
  }

  init() {
    // показать оверлей по upload:request (контекстное меню / кнопка)
    this.unsubs.push(
      this.bus.on('upload:request', () => {
        this.show();
      }),
    );

    // 2. Подписка на изменение пути
    this.unsubs.push(
      this.navState.subscribe((currentPath) => {
        this.pathOverride = currentPath;
      })
    );

    // реакция на drop / выбор файлов
    this.overlay.addEventListener('dropzone:files', (e: Event) => {
      const files = (e as CustomEvent<FileList>).detail;
      const path = this.pathOverride;

      this.bus.emit('upload:drop', {path, files});
      this.hide();
      this.pathOverride = undefined;
    });
  }

  destroy() {
    this.unsubs.forEach((u) => u());
  }

  private show() {
    this.overlay.style.display = 'flex';
  }

  private hide() {
    this.overlay.style.display = 'none';
  }
}
