import {HttpClient} from '@/api/HttpClient';
import {HttpSnippetBackend, type ISnippetBackend} from '@/api/SnippetBackend';
import type {SnippetPickerConfig} from '@/config/PickerConfig';
import {SnippetPickerView} from '@/picker/SnippetPickerView';
import {StateOverlay} from '@/picker/StateOverlay';

/** Управление жизненным циклом одного открытого пикера. */
export interface SnippetPickerRuntime {
  /** Открыть окно: загрузить дерево и показать пикер. Повторный вызов при открытом — no-op. */
  open(): Promise<void>;
  /** Закрыть окно и освободить ресурсы. */
  close(): void;
}

/**
 * Рантайм пикера сниппетов: связывает загрузку дерева (бэкенд), отображение (вью) и коллбэки
 * интеграции. Аналог `AppRuntime` в filemanager-core, но радикально проще — сниппеты read-only.
 */
class SnippetPicker implements SnippetPickerRuntime {
  private readonly backend: ISnippetBackend;
  private view: SnippetPickerView | null = null;
  private state: StateOverlay | null = null;
  private opened = false;

  constructor(private readonly config: SnippetPickerConfig) {
    this.backend = config.backend ?? new HttpSnippetBackend(
      new HttpClient({baseUrl: config.snippetsUrl, headers: config.headers}),
    );
  }

  async open(): Promise<void> {
    if (this.opened) {
      return;
    }
    this.opened = true;

    this.state = new StateOverlay(() => this.close());
    this.state.mount('Загрузка сниппетов…');

    try {
      const tree = await this.backend.fetchTree();

      // Пока грузили — окно могли закрыть.
      if (!this.opened) {
        return;
      }

      this.state?.destroy();
      this.state = null;

      this.view = new SnippetPickerView(
        tree.groups,
        this.config.title ?? 'Сниппеты',
        {
          onInsert: (snippet) => {
            this.config.onSelect(snippet.html);
            this.close();
          },
          onClose: () => this.close(),
        },
      );
      this.view.mount();
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Не удалось загрузить сниппеты';
      this.state?.showError(message);
    }
  }

  close(): void {
    if (!this.opened) {
      return;
    }
    this.opened = false;

    this.view?.destroy();
    this.view = null;
    this.state?.destroy();
    this.state = null;

    this.config.onClose?.();
  }
}

/**
 * Фабрика пикера сниппетов — единственная публичная точка входа ядра.
 *
 * @param config коннектор, заголовки и коллбэки вставки/закрытия
 * @returns рантайм с методами {@link SnippetPickerRuntime.open}/{@link SnippetPickerRuntime.close}
 */
export function createSnippetPicker(config: SnippetPickerConfig): SnippetPickerRuntime {
  return new SnippetPicker(config);
}
