// src/shared/api/fileManager/mappers.ts
import type {DirDto, FileDto} from './dto';
import { FolderEntity } from '@/entities/folder/model/FolderEntity';
import { FileEntity } from '@/entities/file/model/FileEntity';

/**
 * Маппинг ответа "директория" с бэка в доменную сущность.
 * Внутри FolderEntity уже есть проверка, валидация и рекурсивная сборка дерева.
 */
export function mapDirDtoToFolderEntity(dto: DirDto): FolderEntity {
  return new FolderEntity(dto); // если сейчас конструктор ждёт DirDataFromServer —
  // можно либо сделать type alias, либо постепенно заменить тип.
}

/**
 * Маппинг файла. Нужен, если где-то бэк будет возвращать одиночные FileDto (например, upload, rename).
 */
export function mapFileDtoToFileEntity(dto: FileDto): FileEntity {
  return new FileEntity(dto);
}
