import type {FileManagerEventBus} from '@/shared/lib/EventBus';
import {SelectionState} from "@/features/selection/model/SelectionStore";
import {IObservable} from "@/shared/lib/Observable";
import {IFeature} from "@/shared/lib/Feature";
import {FooterWC} from "@/shared/ui/footer/FooterWC";

export class FooterFeature implements IFeature {
  private unsubs: (() => void)[] = [];

  constructor(
    private readonly bus: FileManagerEventBus,
    private footer: FooterWC,
    private selectionState: IObservable<SelectionState>,
    private navState: IObservable<string>,
  ) {
  }

  init() {
    // Подписка на изменение пути
    this.unsubs.push(
      this.navState.subscribe((currentPath) => {
        this.footer.setLeftContent(currentPath);
      })
    );

    this.unsubs.push(
      this.selectionState.subscribe((state) => {
        const count = state.count;
        if (count > 0) {
          this.footer.setLeftContent(`Выделено объектов: ${count}`);
        } else {
          this.footer.setLeftContent('');
        }
      })
    );

  }

  destroy() {
    this.unsubs.forEach(unsub => unsub());
  }

}
