// src/shared/ui/upload-minibar/UploadMinibarWC.ts

import styles from './scss/upload-minibar.scss';

const sheet = new CSSStyleSheet();
sheet.replaceSync(styles);

/**
 * Мини-бар прогресса загрузки (nprogress-style).
 * Тонкая полоска в верхней части экрана, показывающая общий прогресс.
 *
 * Особенности:
 * - Автоматическое плавное скрытие после завершения
 * - Сглаживание анимации через RAF
 * - Минимальная видимая ширина (5%) для UX
 * - Индикация ошибок (красный цвет)
 *
 * @example
 * ```html
 * <upload-minibar></upload-minibar>
 * ```
 *
 * ```ts
 * const minibar = document.querySelector('upload-minibar');
 * minibar.start();
 * minibar.setProgress(50);
 * minibar.finish(); // Плавно завершает и скрывает
 * ```
 */
export class UploadMinibarWC extends HTMLElement {
  private bar!: HTMLDivElement;
  private barInner!: HTMLDivElement;

  // Состояние анимации
  private displayedProgress = 0;
  private targetProgress = 0;
  private rafId: number | null = null;

  // Таймер авто-скрытия
  private hideTimeoutId: number | null = null;

  // Настройки
  private static readonly SMOOTHING = 0.15;        // Коэффициент сглаживания (0-1)
  private static readonly EPSILON = 0.5;           // Точность сравнения
  private static readonly MIN_VISUAL_PERCENT = 5;  // Минимальная видимая ширина
  private static readonly HIDE_DELAY = 400;        // Задержка перед скрытием (мс)

  connectedCallback() {
    if (this.shadowRoot) return;

    const shadow = this.attachShadow({ mode: 'open' });
    shadow.adoptedStyleSheets = [sheet];

    this.bar = document.createElement('div');
    this.bar.className = 'minibar';

    this.barInner = document.createElement('div');
    this.barInner.className = 'minibar-inner';

    this.bar.appendChild(this.barInner);
    shadow.appendChild(this.bar);
  }

  disconnectedCallback() {
    this.stopAnimation();
    this.clearHideTimeout();
  }

  // === Public API ===

  /**
   * Начинает показ прогресс-бара.
   * Сбрасывает предыдущее состояние и показывает бар.
   */
  public start(): void {
    this.clearHideTimeout();
    this.displayedProgress = 0;
    this.targetProgress = 0;
    this.updateBarUI(0);

    this.bar.classList.remove('has-error');
    this.bar.classList.add('visible');
  }

  /**
   * Устанавливает целевой прогресс (0-100).
   * Анимация догоняет это значение плавно.
   */
  public setProgress(progress: number): void {
    this.targetProgress = Math.max(0, Math.min(100, progress));
    this.startAnimation();
  }

  /**
   * Завершает загрузку: догоняет до 100% и плавно скрывает.
   */
  public finish(): void {
    this.targetProgress = 100;
    this.startAnimation();

    // После завершения анимации — скрываем с задержкой
    this.scheduleHide();
  }

  /**
   * Принудительно скрывает бар без анимации.
   */
  public hide(): void {
    this.stopAnimation();
    this.clearHideTimeout();
    this.bar.classList.remove('visible');
    this.displayedProgress = 0;
    this.targetProgress = 0;
    this.updateBarUI(0);
  }

  /**
   * Устанавливает состояние ошибки (красный цвет).
   */
  public setError(hasError: boolean): void {
    if (hasError) {
      this.bar.classList.add('has-error');
    } else {
      this.bar.classList.remove('has-error');
    }
  }

  // === Animation ===

  private startAnimation(): void {
    if (this.rafId !== null) return;
    this.rafId = requestAnimationFrame(this.animateBar);
  }

  private stopAnimation(): void {
    if (this.rafId !== null) {
      cancelAnimationFrame(this.rafId);
      this.rafId = null;
    }
  }

  private animateBar = (): void => {
    const diff = this.targetProgress - this.displayedProgress;

    if (Math.abs(diff) < UploadMinibarWC.EPSILON) {
      // Достигли цели
      this.displayedProgress = this.targetProgress;
      this.updateBarUI(this.displayedProgress);
      this.rafId = null;
      return;
    }

    // Плавное приближение
    this.displayedProgress += diff * UploadMinibarWC.SMOOTHING;
    this.updateBarUI(this.displayedProgress);

    this.rafId = requestAnimationFrame(this.animateBar);
  };

  private updateBarUI(progress: number): void {
    // Минимальная видимая ширина для UX (чтобы было видно, что что-то происходит)
    const visual = progress > 0 && progress < 100
      ? Math.max(progress, UploadMinibarWC.MIN_VISUAL_PERCENT)
      : progress;

    this.barInner.style.transform = `scaleX(${visual / 100})`;
  }

  // === Auto-hide ===

  private scheduleHide(): void {
    this.clearHideTimeout();

    this.hideTimeoutId = window.setTimeout(() => {
      this.bar.classList.remove('visible');
      this.hideTimeoutId = null;
    }, UploadMinibarWC.HIDE_DELAY);
  }

  private clearHideTimeout(): void {
    if (this.hideTimeoutId !== null) {
      clearTimeout(this.hideTimeoutId);
      this.hideTimeoutId = null;
    }
  }
}

customElements.define('upload-minibar', UploadMinibarWC);
