// src/shared/ui/upload-progress/UploadProgressPanel.ts

import { UploadStatus } from "@/features/upload/model/UploadStatus";
import styles from './scss/upload-progress.scss';

const sheet = new CSSStyleSheet();
sheet.replaceSync(styles);

/**
 * Состояние анимации для одного файла
 */
interface FileAnimationState {
  displayed: number;  // Текущее отображаемое значение
  target: number;     // Целевое значение
  percentEl: HTMLElement;
  rowEl: HTMLElement;
  status: UploadStatus['status'];
}

/**
 * Панель прогресса загрузки файлов.
 *
 * Особенности:
 * - Единый RAF-цикл для всех анимаций (total + per-file)
 * - Сворачивание в мини-иконку
 * - Авто-скрытие после завершения с debounce
 * - Кнопки отмены и повтора
 *
 * События:
 * - `cancel-all` — отменить все загрузки
 * - `retry-file` — повторить загрузку файла (detail: { fileName })
 */
export class UploadProgressWC extends HTMLElement {
  private readonly fileListContainer: HTMLElement;
  private readonly totalProgressLabel: HTMLElement;

  private container: HTMLElement;
  private readonly miniProgressLabel: HTMLElement;

  // Кнопки управления
  private readonly btnClose: HTMLButtonElement;
  private readonly btnCancel: HTMLButtonElement;

  // === Единое состояние анимации ===
  private fileStates: Map<string, FileAnimationState> = new Map();
  private displayedTotal = 0;
  private targetTotal = 0;
  private rafId: number | null = null;

  // Флаги состояния
  private hasActiveUploads = false;
  private hasErrors = false;

  // Авто-скрытие
  private hideTimeoutId: number | null = null;
  private static readonly HIDE_DELAY = 2000; // мс после завершения

  // Настройки анимации
  private static readonly SMOOTHING = 0.12;
  private static readonly EPSILON = 0.5;

  constructor() {
    super();

    this.container = document.createElement('div');
    this.container.className = 'upload-container';

    this.miniProgressLabel = document.createElement('div');
    this.miniProgressLabel.className = 'total-progress-circle';

    this.fileListContainer = document.createElement('div');
    this.totalProgressLabel = document.createElement('span');

    // Кнопки
    this.btnClose = document.createElement('button');
    this.btnClose.textContent = '✕';
    this.btnClose.className = 'up-btn-close';
    this.btnClose.title = 'Закрыть окно';

    this.btnCancel = document.createElement('button');
    this.btnCancel.textContent = '⏹ Отмена';
    this.btnCancel.className = 'up-btn-cancel';
    this.btnCancel.title = 'Прервать все загрузки';
  }

  connectedCallback() {
    if (this.shadowRoot) return;

    const shadow = this.attachShadow({ mode: 'open' });
    shadow.adoptedStyleSheets = [sheet];

    // Header
    const header = document.createElement('div');
    header.className = 'upload-header';

    const titleArea = document.createElement('div');
    titleArea.className = 'upload-title';
    titleArea.textContent = 'Загрузка ';
    titleArea.appendChild(this.totalProgressLabel);

    const controlsArea = document.createElement('div');
    controlsArea.className = 'upload-controls';
    controlsArea.appendChild(this.btnCancel);
    controlsArea.appendChild(this.btnClose);

    header.appendChild(titleArea);
    header.appendChild(controlsArea);

    // File list
    this.fileListContainer.className = 'upload-file-list';

    this.container.appendChild(header);
    this.container.appendChild(this.fileListContainer);
    this.container.appendChild(this.miniProgressLabel);

    shadow.appendChild(this.container);

    this.setupEventListeners();
  }

  disconnectedCallback() {
    this.stopAnimation();
    this.clearHideTimeout();
  }

  private setupEventListeners(): void {
    // Клик по свёрнутой панели — разворачивает
    this.container.onclick = () => {
      if (this.hasAttribute('minimized')) {
        this.expand();
      }
    };

    // Кнопка закрытия
    this.btnClose.onclick = (e) => {
      e.stopPropagation();
      this.handleCloseAction();
    };

    // Кнопка отмены всех загрузок
    this.btnCancel.onclick = (e) => {
      e.stopPropagation();
      this.dispatchEvent(new CustomEvent('cancel-all', {
        bubbles: true,
        composed: true
      }));
    };
  }

  private handleCloseAction(): void {
    if (this.hasActiveUploads) {
      this.minimize();
    } else {
      this.hide();
    }
  }

  // === Public API ===

  public minimize(): void {
    this.setAttribute('minimized', '');
  }

  public expand(): void {
    this.removeAttribute('minimized');
  }

  /**
   * Начинает показ панели с новым списком файлов.
   */
  public start(files: FileList | File[]): void {
    this.clearHideTimeout();
    this.show();
    this.expand();

    // Сброс состояния
    this.displayedTotal = 0;
    this.targetTotal = 0;
    this.fileStates.clear();
    this.fileListContainer.innerHTML = '';
    this.hasErrors = false;
    this.container.classList.remove('has-error');

    // Показываем кнопку отмены
    this.btnCancel.style.display = 'inline-block';

    // Создаём UI для каждого файла
    Array.from(files).forEach(file => {
      const row = document.createElement('div');
      row.className = 'upload-file-item';

      const nameEl = document.createElement('span');
      nameEl.className = 'file-name';
      nameEl.textContent = file.name;
      nameEl.title = file.name;

      const statusEl = document.createElement('span');
      statusEl.className = 'file-status';
      statusEl.textContent = '0%';

      row.appendChild(nameEl);
      row.appendChild(statusEl);
      this.fileListContainer.appendChild(row);

      // Инициализируем состояние анимации
      this.fileStates.set(file.name, {
        displayed: 0,
        target: 0,
        percentEl: statusEl,
        rowEl: row,
        status: 'pending'
      });
    });

    this.updateTotalUI(0);
  }

  /**
   * Обновляет статусы загрузки файлов.
   * Вызывается при каждом изменении прогресса.
   */
  public update(statuses: UploadStatus[]): void {
    if (!statuses.length) return;

    this.clearHideTimeout();

    let hasError = false;
    let activeCount = 0;
    let totalProgress = 0;

    statuses.forEach(status => {
      const state = this.fileStates.get(status.fileName);
      if (!state) return;

      // Обновляем целевой прогресс для анимации
      state.target = status.progress;
      state.status = status.status;

      // Считаем статистику
      totalProgress += status.progress;

      if (status.status === 'failed') {
        hasError = true;
      }

      if (status.status === 'uploading' || status.status === 'pending') {
        activeCount++;
      }
    });

    // Обновляем флаги
    this.hasActiveUploads = activeCount > 0;
    this.hasErrors = hasError;

    // Обновляем UI состояния ошибки
    if (hasError) {
      this.container.classList.add('has-error');
    } else {
      this.container.classList.remove('has-error');
    }

    // Показываем/скрываем кнопку отмены
    this.btnCancel.style.display = this.hasActiveUploads ? 'inline-block' : 'none';

    // Обновляем целевой total
    this.targetTotal = statuses.length > 0 ? totalProgress / statuses.length : 0;

    // Запускаем единый цикл анимации
    this.startAnimation();
  }

  /**
   * Завершает загрузку и запускает авто-скрытие.
   */
  public finish(): void {
    this.targetTotal = 100;

    // Устанавливаем всем файлам target = 100 для завершённых
    this.fileStates.forEach(state => {
      if (state.status === 'completed' || state.status === 'uploading') {
        state.target = 100;
      }
    });

    this.btnCancel.style.display = 'none';
    this.startAnimation();

    // Запускаем авто-скрытие
    this.scheduleHide();
  }

  public show(): void {
    this.clearHideTimeout();
    this.setAttribute('open', '');
    this.removeAttribute('minimized');
  }

  public hide(): void {
    this.stopAnimation();
    this.clearHideTimeout();
    this.removeAttribute('open');
    this.removeAttribute('minimized');
  }

  // === Единый цикл анимации ===

  private startAnimation(): void {
    if (this.rafId !== null) return;
    this.rafId = requestAnimationFrame(this.animatePanel);
  }

  private stopAnimation(): void {
    if (this.rafId !== null) {
      cancelAnimationFrame(this.rafId);
      this.rafId = null;
    }
  }

  private animatePanel = (): void => {
    let hasPending = false;
    const SMOOTHING = UploadProgressWC.SMOOTHING;
    const EPSILON = UploadProgressWC.EPSILON;

    // === Анимация Total ===
    const totalDiff = this.targetTotal - this.displayedTotal;
    if (Math.abs(totalDiff) > EPSILON) {
      this.displayedTotal += totalDiff * SMOOTHING;
      hasPending = true;
    } else {
      this.displayedTotal = this.targetTotal;
    }
    this.updateTotalUI(this.displayedTotal);

    // === Анимация Per-File ===
    this.fileStates.forEach((state, fileName) => {
      const diff = state.target - state.displayed;

      if (Math.abs(diff) > EPSILON) {
        state.displayed += diff * SMOOTHING;
        hasPending = true;
      } else {
        state.displayed = state.target;
      }

      this.updateFileUI(fileName, state);
    });

    // Продолжаем анимацию, если есть незавершённые
    if (hasPending) {
      this.rafId = requestAnimationFrame(this.animatePanel);
    } else {
      this.rafId = null;
    }
  };

  // === UI Updates ===

  private updateTotalUI(progress: number): void {
    const rounded = Math.round(progress);
    this.totalProgressLabel.textContent = `${rounded}%`;
    this.miniProgressLabel.textContent = `${rounded}%`;
  }

  private updateFileUI(fileName: string, state: FileAnimationState): void {
    const { percentEl, status, displayed } = state;

    // Очищаем содержимое только если статус изменился на failed/completed
    // или если это первый рендер для этого статуса
    const currentStatus = percentEl.dataset.status;

    if (status === 'failed' && currentStatus !== 'failed') {
      percentEl.innerHTML = '';
      percentEl.style.color = 'var(--color-error, #d32f2f)';
      percentEl.dataset.status = 'failed';

      const errorText = document.createElement('span');
      errorText.textContent = 'Ошибка ';

      const retryBtn = document.createElement('button');
      retryBtn.textContent = '↻';
      retryBtn.className = 'up-btn-retry';
      retryBtn.title = 'Повторить';
      retryBtn.onclick = (e) => {
        e.stopPropagation();
        this.dispatchEvent(new CustomEvent('retry-file', {
          detail: { fileName },
          bubbles: true,
          composed: true
        }));
      };

      percentEl.appendChild(errorText);
      percentEl.appendChild(retryBtn);

    } else if (status === 'completed' && currentStatus !== 'completed') {
      percentEl.innerHTML = '';
      percentEl.textContent = '✓';
      percentEl.style.color = 'var(--color-success, #388e3c)';
      percentEl.dataset.status = 'completed';

    } else if (status !== 'failed' && status !== 'completed') {
      // Pending или Uploading — показываем анимированный процент
      if (currentStatus === 'failed' || currentStatus === 'completed') {
        // Сброс после retry
        percentEl.innerHTML = '';
        percentEl.style.color = '';
      }
      percentEl.dataset.status = status;
      percentEl.textContent = `${Math.round(displayed)}%`;
    }
  }

  // === Auto-hide ===

  private scheduleHide(): void {
    this.clearHideTimeout();

    // Не скрываем автоматически, если есть ошибки
    if (this.hasErrors) return;

    this.hideTimeoutId = window.setTimeout(() => {
      this.minimize();
      this.hideTimeoutId = null;
    }, UploadProgressWC.HIDE_DELAY);
  }

  private clearHideTimeout(): void {
    if (this.hideTimeoutId !== null) {
      clearTimeout(this.hideTimeoutId);
      this.hideTimeoutId = null;
    }
  }
}

customElements.define('upload-progress-wc', UploadProgressWC);
