import {IFileManagerBackend} from "@/shared/api/fileManager/ports";
import {FolderRegistry} from "@/entities/folder/model/FolderRegistry";
import {mapDirDtoToFolderEntity} from "@/shared/api/fileManager/mappers";
import {AppError} from "@/shared/lib/error/AppError";
import {NavigationState} from "./NavigationState";
import {LoadingStore} from "@/features/app-status/model/LoadingStore";

export class NavigationService {
  constructor(
    private backend: IFileManagerBackend,
    private registry: FolderRegistry,
    public state: NavigationState,
    private readonly loadingStore: LoadingStore,
  ) {
  }

  /**
   * Главный метод: Перейти в папку
   */
  async navigate(path: string, forceRefresh: boolean = false): Promise<void> {
    // 1. Проверяем кэш
    const cachedFolder = this.registry.getFolderByPath(path);

    // Если папка есть, данные в ней есть (не пустая заглушка) и мы не форсируем обновление,
    // тьо просто меняем путь — запроса не будет!
    if (cachedFolder && cachedFolder.updateCounter > 0 && !forceRefresh) {
      this.state.setPath(path);
      return;
    }

    // 2. Иначе — идем на сервер
    try {
      this.loadingStore.startOperation(); // Инкремент счетчика

      const response = await this.backend.list({path});
      const folderEntity = mapDirDtoToFolderEntity(response.item);

      // 3. Кладем в Entity (Registry сам смержит данные)
      this.registry.upsertFolder(path, folderEntity);

      // 4. Меняем путь
      this.state.setPath(path);
    } catch (e) {
      console.error(e); // TODO - что тут с обработкой и какие ловит ошибки?
      throw new AppError('Ошибка навигации');
    } finally {
      this.loadingStore.endOperation(); // Декремент счетчика
    }
  }
}
