// shared/lib/diagnostics/DiagnosticStore.ts
import { Observable } from '@/shared/lib/Observable';
import { DiagnosticEvent } from './DiagnosticEvent';

/**
 * DiagnosticStore — журнал событий
 * Это твой “посмотреть, что происходило раньше”.
 * 🔹 Это идеальный источник данных для:
 *    - LogWC
 *    - “История действий”
 *    - Debug-панели
 */
export class DiagnosticStore extends Observable<DiagnosticEvent[]> {
  constructor() {
    super([]);
  }

  add(event: DiagnosticEvent) {
    this.setState([...this.state, event]);
  }

  clear() {
    this.setState([]);
  }

  getByLevel(level: string) {
    return this.state.filter(e => e.level === level);
  }
}
