import type {SnippetDto, SnippetGroupDto} from '@/api/dto';
import styles from '@/picker/styles.scss';

/** Коллбэки, которыми вью сообщает рантайму о действиях пользователя. */
export interface SnippetPickerViewCallbacks {
  /** Пользователь выбрал сниппет для вставки (двойной клик / кнопка «Вставить»). */
  onInsert: (snippet: SnippetDto) => void;
  /** Пользователь закрыл окно (крестик, Esc, backdrop, «Отмена»). */
  onClose: () => void;
}

/** Синтетический id вкладки «Все категории». */
const ALL_GROUP = '�all';

/**
 * DOM-представление пикера сниппетов в изолированном Shadow DOM.
 *
 * Держит собственное локальное состояние (активная группа, поисковый запрос, выбранный сниппет)
 * и перерисовывает только затронутые панели. Никакой доменной логики — только отображение и
 * пользовательский ввод; загрузку дерева и вставку выполняет рантайм {@link SnippetPicker}.
 */
export class SnippetPickerView {
  private readonly host: HTMLElement;
  private readonly shadow: ShadowRoot;

  private activeGroupId: string = ALL_GROUP;
  private query = '';
  private selected: SnippetDto | null = null;

  private listEl!: HTMLElement;
  private previewEl!: HTMLElement;
  private insertBtn!: HTMLButtonElement;
  private groupsEl!: HTMLElement;

  private readonly onKeyDown = (e: KeyboardEvent): void => {
    if (e.key === 'Escape') {
      this.callbacks.onClose();
    }
  };

  constructor(
    private readonly groups: SnippetGroupDto[],
    private readonly title: string,
    private readonly callbacks: SnippetPickerViewCallbacks,
  ) {
    this.host = document.createElement('div');
    this.host.setAttribute('data-snippets-picker', '');
    this.shadow = this.host.attachShadow({mode: 'open'});
  }

  /** Монтирует окно в документ и навешивает глобальные обработчики. */
  mount(): void {
    const style = document.createElement('style');
    style.textContent = styles;
    this.shadow.append(style, this.buildLayout());

    document.body.appendChild(this.host);
    document.addEventListener('keydown', this.onKeyDown);
  }

  /** Снимает окно и обработчики. */
  destroy(): void {
    document.removeEventListener('keydown', this.onKeyDown);
    this.host.remove();
  }

  private buildLayout(): HTMLElement {
    const backdrop = el('div', {class: 'backdrop'});
    backdrop.addEventListener('mousedown', (e) => {
      if (e.target === backdrop) {
        this.callbacks.onClose();
      }
    });

    const closeBtn = el('button', {class: 'close', type: 'button', title: 'Закрыть', text: '×'});
    closeBtn.addEventListener('click', () => this.callbacks.onClose());

    const header = el('div', {class: 'header'}, [
      el('h2', {text: this.title}),
      closeBtn,
    ]);

    const search = el('input', {type: 'search', placeholder: 'Поиск сниппета…'}) as HTMLInputElement;
    search.addEventListener('input', () => {
      this.query = search.value.trim().toLowerCase();
      this.renderList();
    });

    this.groupsEl = el('div', {class: 'groups'});
    this.listEl = el('div', {class: 'list'});
    this.previewEl = el('div', {class: 'preview-body placeholder'});

    const preview = el('div', {class: 'preview'}, [
      el('div', {class: 'preview-title', text: 'Превью'}),
      this.previewEl,
    ]);

    const body = el('div', {class: 'body'}, [this.groupsEl, this.listEl, preview]);

    const cancelBtn = el('button', {class: 'btn', type: 'button', text: 'Отмена'});
    cancelBtn.addEventListener('click', () => this.callbacks.onClose());

    this.insertBtn = el('button', {class: 'btn primary', type: 'button', text: 'Вставить'}) as HTMLButtonElement;
    this.insertBtn.disabled = true;
    this.insertBtn.addEventListener('click', () => {
      if (this.selected) {
        this.callbacks.onInsert(this.selected);
      }
    });

    const footer = el('div', {class: 'footer'}, [cancelBtn, this.insertBtn]);

    const modal = el('div', {class: 'modal'}, [
      header,
      el('div', {class: 'search'}, [search]),
      body,
      footer,
    ]);

    backdrop.appendChild(modal);

    this.renderGroups();
    this.renderList();
    this.renderPreview();

    return backdrop;
  }

  private renderGroups(): void {
    this.groupsEl.replaceChildren();

    const total = this.groups.reduce((sum, g) => sum + g.items.length, 0);
    this.groupsEl.appendChild(this.groupRow(ALL_GROUP, 'Все', total));

    for (const group of this.groups) {
      const label = group.label !== '' ? group.label : 'Без категории';
      this.groupsEl.appendChild(this.groupRow(group.id, label, group.items.length));
    }
  }

  private groupRow(id: string, label: string, count: number): HTMLElement {
    const row = el('div', {
      class: `group-item${id === this.activeGroupId ? ' active' : ''}`,
    }, [
      el('span', {text: label}),
      el('span', {class: 'count', text: String(count)}),
    ]);
    row.addEventListener('click', () => {
      this.activeGroupId = id;
      this.renderGroups();
      this.renderList();
    });
    return row;
  }

  private renderList(): void {
    this.listEl.replaceChildren();

    const items = this.visibleSnippets();
    if (items.length === 0) {
      this.listEl.appendChild(el('div', {class: 'empty', text: 'Ничего не найдено'}));
      return;
    }

    for (const snippet of items) {
      const card = el('div', {
        class: `snippet${this.selected?.id === snippet.id ? ' active' : ''}`,
      }, [el('div', {class: 'title', text: snippet.title})]);

      if (snippet.keywords.length > 0) {
        card.appendChild(el('div', {class: 'kw', text: snippet.keywords.join(', ')}));
      }

      card.addEventListener('click', () => this.select(snippet));
      card.addEventListener('dblclick', () => this.callbacks.onInsert(snippet));

      this.listEl.appendChild(card);
    }
  }

  private renderPreview(): void {
    if (!this.selected) {
      this.previewEl.className = 'preview-body placeholder';
      this.previewEl.textContent = 'Выберите сниппет для просмотра';
      return;
    }

    this.previewEl.className = 'preview-body';
    // Тело сниппета — доверенный контент, созданный редактором в админке (то же, что вставляется
    // в контент), поэтому рендерим как HTML для наглядного превью.
    this.previewEl.innerHTML = this.selected.preview ?? this.selected.html;
  }

  private select(snippet: SnippetDto): void {
    this.selected = snippet;
    this.insertBtn.disabled = false;
    this.renderList();
    this.renderPreview();
  }

  private visibleSnippets(): SnippetDto[] {
    const source = this.activeGroupId === ALL_GROUP
      ? this.groups.flatMap((g) => g.items)
      : (this.groups.find((g) => g.id === this.activeGroupId)?.items ?? []);

    if (this.query === '') {
      return source;
    }

    return source.filter((s) =>
      s.title.toLowerCase().includes(this.query)
      || s.keywords.some((k) => k.toLowerCase().includes(this.query)),
    );
  }
}

/** Свойства, поддерживаемые хелпером {@link el}. */
interface ElProps {
  class?: string;
  text?: string;
  type?: string;
  placeholder?: string;
  title?: string;
}

/** Компактный конструктор DOM-элементов (без внешних зависимостей). */
function el(tag: string, props: ElProps = {}, children: Node[] = []): HTMLElement {
  const node = document.createElement(tag);
  if (props.class !== undefined) node.className = props.class;
  if (props.text !== undefined) node.textContent = props.text;
  if (props.type !== undefined) node.setAttribute('type', props.type);
  if (props.placeholder !== undefined) node.setAttribute('placeholder', props.placeholder);
  if (props.title !== undefined) node.setAttribute('title', props.title);
  node.append(...children);
  return node;
}
