/** Конфиг http-клиента ядра сниппетов. */
export interface HttpClientConfig {
  /** Полный URL эндпоинта дерева сниппетов. */
  baseUrl: string;
  /** Доп. заголовки (например X-Requested-With). */
  headers?: Record<string, string>;
}

/**
 * Минимальный http-клиент (только чтение дерева сниппетов).
 *
 * Осознанно узкий: сниппеты read-only с точки зрения фронта — управление ими живёт в админке
 * Yii, здесь нужен только GET. Полноценный CRUD-клиент (как в filemanager-core) избыточен.
 */
export class HttpClient {
  constructor(private readonly config: HttpClientConfig) {
  }

  async get<T>(init?: RequestInit): Promise<T> {
    const res = await fetch(this.config.baseUrl, {
      ...init,
      method: 'GET',
      headers: {
        ...this.config.headers,
        ...(init?.headers ?? {}),
      },
    });

    if (!res.ok) {
      throw new Error(`Snippets: HTTP ${res.status} ${res.statusText}`);
    }

    return res.json() as Promise<T>;
  }
}
