import type {FileManagerEventBus} from '@/shared/lib/EventBus';
import {DeleteService} from "./DeleteService";
import type {IFileManagerBackend} from "@/shared/api/fileManager/ports";
import {ModalService} from "@/features/modal/model/ModalService";
import {SelectionState} from "@/features/selection/model/SelectionStore";
import {IObservable} from "@/shared/lib/Observable";
import {IFeature} from "@/shared/lib/Feature";
import {LoadingStore} from "@/features/app-status/model/LoadingStore";
import {DiagnosticService} from "@/shared/lib/diagnostics/DiagnosticService";

export class DeleteFeature implements IFeature {
  private service: DeleteService;
  private unsubs: (() => void)[] = [];

  constructor(
    private readonly bus: FileManagerEventBus,
    private modalService: ModalService,
    backend: IFileManagerBackend,
    // Мы инжектим SelectionStore, но он реализует IObservable<SelectionState>
    private selectionState: IObservable<SelectionState>,
    private navState: IObservable<string>,
    private readonly loadingStore: LoadingStore,
    private diagnostics: DiagnosticService,
  ) {
    this.service = new DeleteService(backend, this.diagnostics);
  }

  init() {
    this.unsubs.push(
      // Слушаем клик по кнопке (UI -> Feature)
      this.bus.on('delete:start', async () => {
        // Берем актуальное состояние, чтобы знать, что удалять
        const selection: SelectionState = this.selectionState.getValue();
        if (selection.count > 0) {
          try {
            this.loadingStore.startOperation(); // Инкремент счетчика
            const selectedFiles = selection.files;
            const selectedFolders = selection.folders;
            const selected = [...selectedFiles, ...selectedFolders];
            const confirmed = await this.modalService.openDialog(`Удалить ${selection.count} элементов?`);
            if (confirmed) {
              await this.service.deleteFiles(Array.from(selected));
              this.bus.emit('delete:complete');
              this.bus.emit('nav:refresh', this.navState.getValue());
            }
          } finally {
            this.loadingStore.endOperation(); // Декремент счетчика
          }
        }
      })
    );
  }

  destroy() {
    this.unsubs.forEach(unsub => unsub());
  }

}
