type EventCallback = (event: Event | TouchEvent) => void;

// TODO см. GestureHelper.ts

/**
 * Обрабатывает событие `contextmenu` или `long-tap` для сенсорных устройств.
 * @param { HTMLElement } element - HTML-элемент, на котором вы хотите обнаружить событие `contextmenu` или двойной тап.
 * @param { () => void } callback - Функция, выполняемая при обнаружении события `contextmenu` или `long-tap` по элементу.
 */
export function detectContextMenuAndLongTap(element: HTMLElement, callback: EventCallback): () => void {
  let timer: number | null = null;
  const longPressDuration = 500; // Длительность long-tap в миллисекундах

  // Обработчик contextmenu
  const handleContextMenu = (event: Event) => {
    event.preventDefault();
    callback(event);
  };

  // Обработчики для long-tap (на основе touch событий)
  const handleTouchStart = (event: TouchEvent) => {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }

    timer = window.setTimeout(() => {
      callback(event);
      timer = null;
    }, longPressDuration);
  };

  const handleTouchMove = () => {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
  };

  const handleTouchEnd = () => {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
  };

  // Подписываемся на события
  element.addEventListener('contextmenu', handleContextMenu);
  element.addEventListener('touchstart', handleTouchStart);
  element.addEventListener('touchmove', handleTouchMove);
  element.addEventListener('touchend', handleTouchEnd);
  element.addEventListener('touchcancel', handleTouchEnd);

  // Возвращаем функцию для отписки от событий
  return () => {
    element.removeEventListener('contextmenu', handleContextMenu);
    element.removeEventListener('touchstart', handleTouchStart);
    element.removeEventListener('touchmove', handleTouchMove);
    element.removeEventListener('touchend', handleTouchEnd);
    element.removeEventListener('touchcancel', handleTouchEnd);

    if (timer !== null) {
      clearTimeout(timer);
    }
  };
}

/**
 * Обнаруживает двойное нажатие на сенсорном экране или двойной клик мышью.
 * @param { HTMLElement } element - HTML-элемент, на котором вы хотите обнаружить двойное нажатие.
 * @param { () => void } callback - Функция, выполняемая при обнаружении двойного нажатия.
 * @param { number } maxInterval - Максимально допустимое время (в миллисекундах) между двумя нажатиями, чтобы оно считалось двойным нажатием. По умолчанию — 300 мс.
 *
 * Логика:
 * Переменная `lastTapTime` используется для хранения временной метки последнего нажатия.
 * Когда происходит событие `touchstart`, текущее время (`Date.now()`) сравнивается с `lastTapTime`.
 * Если разница между текущим временем и `lastTapTime` меньше или равна `maxInterval`, обнаруживается двойное нажатие и выполняется `callback`.
 * После обнаружения двойного нажатия `lastTapTime` сбрасывается до `null`, чтобы предотвратить множественные срабатывания.
 * Функция возвращает функцию очистки, которая удаляет слушатель событий touchstart. Это полезно для предотвращения утечек памяти или непреднамеренного поведения, когда элемент больше не нужен.
 * NOTE: Если элемент имеет стандартное поведение при касании (например, прокрутка или масштабирование), вам может потребоваться вызвать event.preventDefault() в обработчике touchstart, чтобы предотвратить конфликты.

 * Пример использования:
 * ```ts
 * const button = document.getElementById("myButton");
 *     if (button) {
 *         const cleanup = detectDoubleTap(button, () => {
 *             console.log("Double tap detected!");
 *         });
 *
 *         // При желании можно позже вызвать `cleanup()`, чтобы удалить слушателя событий.
 *     }
 * ```
 */
export function detectDoubleTapAndDoubleClick(element: HTMLElement, callback: () => void, maxInterval: number = 300): () => void {
  let lastTapTime: number | null = null;

  const handleTap = () => {
    const currentTime = Date.now();

    if (lastTapTime !== null && currentTime - lastTapTime <= maxInterval) {
      // Double tap detected
      callback();
      lastTapTime = null; // Reset to avoid triggering multiple double taps
    } else {
      // Record the time of the first tap
      lastTapTime = currentTime;
    }
  };

  // Touch events
  element.addEventListener("touchstart", handleTap);

  // Mouse events
  element.addEventListener("mousedown", handleTap);

  // Cleanup function
  return () => {
    element.removeEventListener("touchstart", handleTap);
    element.removeEventListener("mousedown", handleTap);
  };
}

/**
 * Обработка клика вне переданного элемента. Добавляет в документ слушатели `mouseup` и `touchend`.
 * @param { HTMLElement } el - Элемент, клики вне которого отслеживаем.
 * @param { () => void } callback - Функция обратного вызова, вызываемая при клике вне переданного элемента.
 * @returns { () => void } - Функция обратного вызова, удаляющая добавленные слушатели `mouseup` и `touchend`.
 */
export function handleOutsideClick(el: HTMLElement, callback: () => void): () => void {
  const handleClickOutside = (event: MouseEvent | TouchEvent) => {
    if (el && !el.contains(event.target as Node)) {
      callback();
    }
  };

  document.addEventListener('mouseup', handleClickOutside);
  document.addEventListener('touchend', handleClickOutside);

  return () => {
    document.removeEventListener('mouseup', handleClickOutside);
    document.removeEventListener('touchend', handleClickOutside);
  };

}

/**
 * Получает точную позицию клика мыши или тапа на сенсорном устройстве.
 * @param {Event | TouchEvent} event - Событие мыши или сенсорного устройства.
 * @returns {{ x: number; y: number; }} - Объект с координатами {x, y}.
 * Пример использования:
 * ```ts
 *     document.addEventListener('mousedown', (event) => {
 *         const position = getTouchPosition(event);
 *         console.log('Mouse click position:', position);
 *     });
 *
 *     document.addEventListener('touchstart', (event) => {
 *         const position = getTouchPosition(event);
 *         console.log('Touch start position:', position);
 *     });
 * ```
 */
export function getTouchPosition(event: Event | TouchEvent): { x: number; y: number; } {
  let x = 0;
  let y = 0;

  if ('touches' in event) {
    // Обработка сенсорных событий
    if (event.touches.length > 0) {
      const touch = event.touches[0]; // Первое касание
      x = touch.pageX;
      y = touch.pageY;
    } else if ((event as TouchEvent).changedTouches.length > 0) {
      // Если touches пустой (например, при touchend), используем changedTouches
      const touch = (event as TouchEvent).changedTouches[0];
      x = touch.pageX;
      y = touch.pageY;
    }
  } else {
    // Обработка событий мыши
    const mouseEvent = event as MouseEvent;
    if (mouseEvent.pageX || mouseEvent.pageY) {
      x = mouseEvent.pageX;
      y = mouseEvent.pageY;
    } else if (mouseEvent.clientX || mouseEvent.clientY) {
      x = mouseEvent.clientX + document.body.scrollLeft +
        document.documentElement.scrollLeft;
      y = mouseEvent.clientY + document.body.scrollTop +
        document.documentElement.scrollTop;
    }
  }

  return {x, y};
}

type KeyEventHandler = (event: KeyboardEvent) => void;

/**
 * Универсальная функция для обнаружения нажатия клавиши.
 *
 * Эта функция будет принимать `callback`, который будет вызываться при нажатии или отпускании клавиши.
 * Мы также можем добавить возможность фильтрации событий по конкретным клавишам.
 * Пример использования:
 * ```ts
 * const cleanup = detectKeyPress(
 *     document,
 *     (event) => {console.log(`Нажата клавиша: ${event.key}`);},
 *     ['Enter', 'Escape'] // Отслеживаем только клавиши Enter и Escape
 * );
 * Чтобы прекратить отслеживание, можно вызвать cleanup();
 * ```
 *
 * @param target - Элемент, на котором нужно отслеживать события клавиш (по умолчанию document).
 * @param callback - Функция обратного вызова, которая будет вызвана при нажатии клавиши.
 * @param keyFilter - Опциональный фильтр для отслеживания только определённых клавиш.
 */
export function detectKeyPress(target: EventTarget = document, callback: KeyEventHandler, keyFilter?: string | string[]): () => void {
  const handleKeyDown = (event: KeyboardEvent): void => {
    // Если задан фильтр по клавишам, проверяем, соответствует ли нажатая клавиша фильтру
    if (keyFilter) {
      const keys = Array.isArray(keyFilter) ? keyFilter : [keyFilter];
      if (!keys.includes(event.key)) {
        return; // Пропускаем событие, если клавиша не соответствует фильтру
      }
    }
    // Вызываем callback с событием
    callback(event);
  };

  // Добавляем слушатель события 'keydown'
  target.addEventListener('keydown', handleKeyDown as EventListener);

  // Возвращаем функцию для удаления слушателя (если нужно)
  return () => {
    target.removeEventListener('keydown', handleKeyDown as EventListener);
  };
}









