import { Observable } from "@/shared/lib/Observable";

export type LoadingState = {
  /** Счетчик активных асинхронных операций */
  activeOperations: number;
  /** Флаг, который равен true, если activeOperations > 0 */
  isLoading: boolean;
};

/**
 * Хранилище, управляющее глобальным состоянием загрузки/активности.
 * Использует счетчик для обработки конкурентных операций.
 * TODO - А зачем пихать это во все фичи? Есть ли смысл чтобы количество взаимодействий с севером считал, например "httpClient.ts"? Мимо него всё равно никто на сервер не лезет
 */
export class LoadingStore extends Observable<LoadingState> {
  constructor() {
    super({ activeOperations: 0, isLoading: false });
  }

  /** Вызывается при старте любой асинхронной операции. */
  public startOperation(): void {
    const count = this.state.activeOperations + 1;
    this.setState({
      activeOperations: count,
      isLoading: true, // Всегда true, если count > 0
    });
  }

  /** Вызывается при завершении (успех/ошибка) асинхронной операции. */
  public endOperation(): void {
    // Убеждаемся, что счетчик не уходит в минус
    const count = Math.max(0, this.state.activeOperations - 1);
    this.setState({
      activeOperations: count,
      isLoading: count > 0,
    });
  }

  /** Сброс всех активных операций (например, при ошибке соединения) */
  public clear(): void {
    this.setState({ activeOperations: 0, isLoading: false });
  }
}
