import type { DeleteResult } from './DeleteResult';
import {DeleteResponseDto} from "@/shared/api/fileManager/dto";

export function mapDeleteResponse(
  dto: DeleteResponseDto
): DeleteResult {
  return {
    deleted: dto.results
      .filter(r => r.ok)
      .map(r => r.path),

    failed: dto.results
      .filter(r => !r.ok)
      .map(r => ({
        path: r.path,
        message: r.message,
      })),
  };
}
