// src/app/di/setup.ts

import { Container } from './Container';
import { DI_TOKENS } from './tokens';

// === Инфраструктура ===
import { EventBus, type FileManagerEventBus, type FMEventMap } from '@/shared/lib/EventBus';
import type { IFileManagerBackend } from '@/shared/api/fileManager/ports';
import type { AppConfig } from '@/app/AppConfig';

// === Stores ===
import { FolderRegistry } from '@/entities/folder/model/FolderRegistry';
import { NavigationState } from '@/features/navigation/model/NavigationState';
import { SelectionStore } from '@/features/selection/model/SelectionStore';
import { ViewModeStore } from '@/features/directory-content/model/ViewModeStore';
import { LoadingStore } from '@/features/app-status/model/LoadingStore';
import { LogVisibilityStore } from '@/features/log/model/LogVisibilityStore';

// === Services ===
import { ModalService } from '@/features/modal/model/ModalService';
import { DiagnosticService } from '@/shared/lib/diagnostics/DiagnosticService';
import { DiagnosticStore } from '@/shared/lib/diagnostics/DiagnosticStore';

// === UI ===
import { FileManagerLayout } from '@/widgets/file-manager/ui/FileManagerLayout';

// === Features ===
import { NavigationFeature } from '@/features/navigation';
import { ToastFeature } from '@/features/toast/ToastFeature';
import { GlobalSpinnerFeature } from '@/features/app-status/model/GlobalSpinnerFeature';
import { LogFeature } from '@/features/log';
import { DirectoryContentFeature } from '@/features/directory-content';
import { RefreshFeature } from '@/features/refresh/model/RefreshFeature';
import { FileTreeFeature } from '@/features/file-tree';
import { DeleteFeature } from '@/features/delete';
import { MoveFeature } from '@/features/move';
import { RenameFeature } from '@/features/rename';
import { PropertiesFeature } from '@/features/properties';
import { ContextMenuFeature } from '@/features/context-menu';
import { DropZoneFeature } from '@/features/drop-zone/model/DropZoneFeature';
import { FooterFeature } from '@/features/footer';
import { ClipboardFeature } from '@/features/clipboard';
import { CreateFeature } from '@/features/create';
import { UploadFeature } from '@/features/upload';
import { UploadProgressFeature } from '@/features/upload/model/UploadProgressFeature';

/**
 * Параметры для настройки DI-контейнера.
 * Это то, что приходит извне (от createApp или AppRuntime).
 */
export interface ContainerParams {
  config: AppConfig;
  backend: IFileManagerBackend;
}

/**
 * Настраивает DI-контейнер, регистрируя все зависимости.
 *
 * Порядок регистрации важен только для понимания кода:
 * 1. Инфраструктура (bus, backend, config)
 * 2. Stores (состояния)
 * 3. Services
 * 4. UI (layout)
 * 5. Features
 *
 * Реальное создание происходит при первом вызове get() (lazy).
 */
export function setupContainer(params: ContainerParams): Container {
  const container = new Container();

  // =========================================
  // 1. ИНФРАСТРУКТУРА
  // =========================================

  container.instance(DI_TOKENS.CONFIG, params.config);
  container.instance(DI_TOKENS.BACKEND, params.backend);

  container.singleton(DI_TOKENS.BUS, () =>
    new EventBus<FMEventMap>()
  );

  // =========================================
  // 2. STORES (состояния)
  // =========================================

  container.singleton(DI_TOKENS.FOLDER_REGISTRY, () =>
    new FolderRegistry()
  );

  container.singleton(DI_TOKENS.NAV_STATE, (c) =>
    new NavigationState(c.get<AppConfig>(DI_TOKENS.CONFIG).fmDefaultPath)
  );

  container.singleton(DI_TOKENS.SELECTION_STORE, () =>
    new SelectionStore()
  );

  container.singleton(DI_TOKENS.VIEW_MODE_STORE, () =>
    new ViewModeStore()
  );

  container.singleton(DI_TOKENS.LOADING_STORE, () =>
    new LoadingStore()
  );

  container.singleton(DI_TOKENS.LOG_VISIBILITY_STORE, () =>
    new LogVisibilityStore()
  );

  container.singleton(DI_TOKENS.DIAGNOSTIC_STORE, () =>
    new DiagnosticStore()
  );

  // =========================================
  // 3. SERVICES
  // =========================================

  container.singleton(DI_TOKENS.DIAGNOSTIC_SERVICE, (c) =>
    new DiagnosticService(
      c.get(DI_TOKENS.DIAGNOSTIC_STORE),
      c.get(DI_TOKENS.BUS)
    )
  );

  container.singleton(DI_TOKENS.MODAL_SERVICE, (c) =>
    new ModalService(
      c.get(DI_TOKENS.LAYOUT),
      c.get(DI_TOKENS.BUS)
    )
  );

  // =========================================
  // 4. UI (Layout)
  // =========================================

  container.singleton(DI_TOKENS.LAYOUT, () =>
    new FileManagerLayout()
  );

  // =========================================
  // 5. FEATURES
  // =========================================

  container.singleton(DI_TOKENS.FEATURE_NAVIGATION, (c) =>
    new NavigationFeature(
      c.get(DI_TOKENS.BUS),
      c.get(DI_TOKENS.BACKEND),
      c.get(DI_TOKENS.FOLDER_REGISTRY),
      c.get(DI_TOKENS.NAV_STATE),
      c.get(DI_TOKENS.LOADING_STORE),
    )
  );

  container.singleton(DI_TOKENS.FEATURE_TOAST, (c) => {
    const layout = c.get<FileManagerLayout>(DI_TOKENS.LAYOUT);
    return new ToastFeature(
      c.get(DI_TOKENS.BUS),
      layout.toast
    );
  });

  container.singleton(DI_TOKENS.FEATURE_SPINNER, (c) => {
    const layout = c.get<FileManagerLayout>(DI_TOKENS.LAYOUT);
    return new GlobalSpinnerFeature(
      layout.loader,
      c.get(DI_TOKENS.LOADING_STORE)
    );
  });

  container.singleton(DI_TOKENS.FEATURE_LOG, (c) => {
    const layout = c.get<FileManagerLayout>(DI_TOKENS.LAYOUT);
    return new LogFeature(
      c.get(DI_TOKENS.BUS),
      layout.log,
      c.get(DI_TOKENS.DIAGNOSTIC_STORE),
      c.get(DI_TOKENS.LOG_VISIBILITY_STORE),
    );
  });

  container.singleton(DI_TOKENS.FEATURE_CONTENT, (c) => {
    const layout = c.get<FileManagerLayout>(DI_TOKENS.LAYOUT);
    return new DirectoryContentFeature(
      c.get(DI_TOKENS.BUS),
      layout.content,
      c.get(DI_TOKENS.FOLDER_REGISTRY),
      c.get(DI_TOKENS.NAV_STATE),
      c.get(DI_TOKENS.SELECTION_STORE),
      c.get(DI_TOKENS.VIEW_MODE_STORE),
    );
  });

  container.singleton(DI_TOKENS.FEATURE_REFRESH, (c) =>
    new RefreshFeature(
      c.get(DI_TOKENS.BUS),
      c.get(DI_TOKENS.NAV_STATE),
    )
  );

  container.singleton(DI_TOKENS.FEATURE_TREE, (c) => {
    const layout = c.get<FileManagerLayout>(DI_TOKENS.LAYOUT);
    return new FileTreeFeature(
      c.get(DI_TOKENS.BUS),
      layout.tree,
      c.get(DI_TOKENS.FOLDER_REGISTRY),
      c.get(DI_TOKENS.NAV_STATE),
    );
  });

  container.singleton(DI_TOKENS.FEATURE_DELETE, (c) =>
    new DeleteFeature(
      c.get(DI_TOKENS.BUS),
      c.get(DI_TOKENS.MODAL_SERVICE),
      c.get(DI_TOKENS.BACKEND),
      c.get(DI_TOKENS.SELECTION_STORE),
      c.get(DI_TOKENS.NAV_STATE),
      c.get(DI_TOKENS.LOADING_STORE),
      c.get(DI_TOKENS.DIAGNOSTIC_SERVICE),
    )
  );

  container.singleton(DI_TOKENS.FEATURE_MOVE, (c) =>
    new MoveFeature(
      c.get(DI_TOKENS.BUS),
      c.get(DI_TOKENS.MODAL_SERVICE),
      c.get(DI_TOKENS.BACKEND),
      c.get(DI_TOKENS.SELECTION_STORE),
    )
  );

  container.singleton(DI_TOKENS.FEATURE_RENAME, (c) =>
    new RenameFeature(
      c.get(DI_TOKENS.BUS),
      c.get(DI_TOKENS.MODAL_SERVICE),
      c.get(DI_TOKENS.BACKEND),
      c.get(DI_TOKENS.SELECTION_STORE),
      c.get(DI_TOKENS.FOLDER_REGISTRY),
      c.get(DI_TOKENS.NAV_STATE),
    )
  );

  container.singleton(DI_TOKENS.FEATURE_PROPERTIES, (c) =>
    new PropertiesFeature(
      c.get(DI_TOKENS.BUS),
      c.get(DI_TOKENS.MODAL_SERVICE),
      c.get(DI_TOKENS.SELECTION_STORE),
      c.get(DI_TOKENS.FOLDER_REGISTRY),
      c.get(DI_TOKENS.NAV_STATE),
      c.get(DI_TOKENS.BACKEND),
    )
  );

  container.singleton(DI_TOKENS.FEATURE_CONTEXT_MENU, (c) => {
    const layout = c.get<FileManagerLayout>(DI_TOKENS.LAYOUT);
    return new ContextMenuFeature(
      c.get(DI_TOKENS.BUS),
      c.get(DI_TOKENS.SELECTION_STORE),
      layout.contextMenu,
    );
  });

  container.singleton(DI_TOKENS.FEATURE_DROP_ZONE, (c) =>
    new DropZoneFeature(
      c.get(DI_TOKENS.BUS),
      c.get(DI_TOKENS.LAYOUT),
      c.get(DI_TOKENS.SELECTION_STORE),
      c.get(DI_TOKENS.NAV_STATE),
    )
  );

  container.singleton(DI_TOKENS.FEATURE_FOOTER, (c) => {
    const layout = c.get<FileManagerLayout>(DI_TOKENS.LAYOUT);
    return new FooterFeature(
      c.get(DI_TOKENS.BUS),
      layout.footer,
      c.get(DI_TOKENS.SELECTION_STORE),
      c.get(DI_TOKENS.NAV_STATE),
    );
  });

  container.singleton(DI_TOKENS.FEATURE_CLIPBOARD, (c) =>
    new ClipboardFeature(
      c.get(DI_TOKENS.BUS),
      c.get(DI_TOKENS.MODAL_SERVICE),
    )
  );

  container.singleton(DI_TOKENS.FEATURE_CREATE, (c) =>
    new CreateFeature(
      c.get(DI_TOKENS.BUS),
      c.get(DI_TOKENS.MODAL_SERVICE),
      c.get(DI_TOKENS.BACKEND),
      c.get(DI_TOKENS.NAV_STATE),
      c.get(DI_TOKENS.DIAGNOSTIC_SERVICE),
    )
  );

  container.singleton(DI_TOKENS.FEATURE_UPLOAD, (c) =>
    new UploadFeature(
      c.get(DI_TOKENS.BUS),
      c.get(DI_TOKENS.BACKEND),
      c.get(DI_TOKENS.NAV_STATE),
      c.get(DI_TOKENS.LOADING_STORE),
      c.get(DI_TOKENS.DIAGNOSTIC_SERVICE),
    )
  );

  container.singleton(DI_TOKENS.FEATURE_UPLOAD_PROGRESS, (c) => {
    const layout = c.get<FileManagerLayout>(DI_TOKENS.LAYOUT);
    return new UploadProgressFeature(
      c.get(DI_TOKENS.BUS),
      layout.uploadProgress,
      layout.uploadMiniBar,
    );
  });

  return container;
}

/**
 * Возвращает список всех токенов фич для итерации.
 */
export function getFeatureTokens(): string[] {
  return [
    DI_TOKENS.FEATURE_NAVIGATION,
    DI_TOKENS.FEATURE_TOAST,
    DI_TOKENS.FEATURE_SPINNER,
    DI_TOKENS.FEATURE_LOG,
    DI_TOKENS.FEATURE_CONTENT,
    DI_TOKENS.FEATURE_REFRESH,
    DI_TOKENS.FEATURE_TREE,
    DI_TOKENS.FEATURE_DELETE,
    DI_TOKENS.FEATURE_MOVE,
    DI_TOKENS.FEATURE_RENAME,
    DI_TOKENS.FEATURE_PROPERTIES,
    DI_TOKENS.FEATURE_CONTEXT_MENU,
    DI_TOKENS.FEATURE_DROP_ZONE,
    DI_TOKENS.FEATURE_FOOTER,
    DI_TOKENS.FEATURE_CLIPBOARD,
    DI_TOKENS.FEATURE_CREATE,
    DI_TOKENS.FEATURE_UPLOAD,
    DI_TOKENS.FEATURE_UPLOAD_PROGRESS,
  ];
}
