import styles from './scss/footer.scss';

const sheet = new CSSStyleSheet();
sheet.replaceSync(styles);

export class FooterWC extends HTMLElement {
  private leftSide!: HTMLElement;
  private rightSide!: HTMLElement;

  connectedCallback() {
    if (this.shadowRoot) return;
    const shadow = this.attachShadow({mode: 'open'});
    shadow.adoptedStyleSheets = [sheet];

    this.leftSide = document.createElement('div');
    this.rightSide = document.createElement('div');

    shadow.appendChild(this.leftSide);
    shadow.appendChild(this.rightSide);
  }

  disconnectedCallback() {
  }

  setLeftContent(txt: string) {
    this.leftSide.textContent = txt;
  }

  setRightContent(txt: string) {
    this.rightSide.textContent = txt;
  }
}

customElements.define('footer-wc', FooterWC);
