// src/features/app-status/model/GlobalSpinnerFeature.ts
import { LoadingStore } from "@/features/app-status/model/LoadingStore";
import { SpinnerWC } from "@/shared/ui/spinner/SpinnerWC";
import { IFeature } from "@/shared/lib/Feature";

export class GlobalSpinnerFeature implements IFeature {
  private unsub?: () => void;

  constructor(
    private spinnerUI: SpinnerWC,
    private loadingStore: LoadingStore
  ) {}

  init() {
    this.unsub = this.loadingStore.subscribe(state => {
      // SpinnerWC управляется через style.display (см. SpinnerWC.ts )
      // Или можно добавить метод show()/hide() в сам веб-компонент, но пока так:
      this.spinnerUI.style.display = state.isLoading ? 'flex' : 'none';
    });
  }

  destroy() {
    this.unsub?.();
  }
}
