// src/shared/lib/ModalService.ts
import type {FileManagerEventBus} from '@/shared/lib/EventBus';
import {FileManagerLayout} from "@/widgets/file-manager/ui/FileManagerLayout";

export class ModalService { // TODO - Можно еще добавить функционал сворачивания модального окна?
  private unsubs: (() => void)[] = [];

  // Счетчик для лоадера (Ref counting)
  private loaderCounter = 0;

  private modalCloseHandler = this.modalCloseRequest.bind(this);

  constructor(
    private view: FileManagerLayout,
    private bus: FileManagerEventBus,
  ) {
    this.init();
  }

  init() {

    const unsubAlert = this.bus.on('modal:alert:show', (message: string) => this.openAlert(message));

    this.view.modal.addEventListener('fm-modal-close-request', this.modalCloseHandler);
    this.unsubs.push(
      unsubAlert,
      () => {
        this.view.modal.removeEventListener('fm-modal-close-request', this.modalCloseHandler);
      });
  }

  /**
   * Клик по крестику закрытия модального окна.
   * На уровне приложения это интерпретируем как "закрыть ФМ целиком".
   */
  modalCloseRequest() {
    this.bus.emit('fm:close', {source: 'modal'});
  }

  public close() {
    this.view.modal.closeModal();
  }

  // =========================================================
  // Логика Диалогов
  // =========================================================

  async openDialog(prompt: string): Promise<boolean> {
    return this.withLoader(
      () => this.view.dialog.openDialog(prompt),
      {closeDialog: true}
    );
  }

  async openInputDialog(prompt: string): Promise<string> {
    return this.withLoader(
      () => this.view.dialog.openInputDialog(prompt)
    );
  }

  async openRenameDialog(prompt: string, fileName: string): Promise<string> {
    return this.withLoader(
      () => this.view.dialog.openRenameDialog(prompt, fileName)
    );
  }

  async openInfoDialog(element: HTMLElement): Promise<void> {
    return this.withLoader(
      () => this.view.dialog.openInfoDialog(element)
    );
  }

  private async withLoader<T>(fn: () => Promise<T>, options?: { closeDialog?: boolean }): Promise<T> {
    const unlock = this.addLoader();
    try {
      return await fn();
    } finally {
      unlock();
      if (options?.closeDialog) {
        this.view.dialog.closeDialog();
      }
    }
  }

  // =========================================================
  // Alerts
  // =========================================================

  public openAlert(message: string | HTMLElement, time: number = 5000) {
    if (typeof message === 'string') {
      const div = document.createElement('div');
      div.textContent = message;
      this.view.alert.show(div, time);
    } else {
      this.view.alert.show(message, time);
    }
  }

  // =========================================================
  // Логика Лоадера (Ref Counting)
  // =========================================================

  public addLoader(): () => void {
    this.loaderCounter++;
    if (this.loaderCounter === 1) {
      this.view.loader.style.display = 'flex';
    }
    return () => this.removeLoader();
  }

  private removeLoader() {
    this.loaderCounter = Math.max(0, this.loaderCounter - 1);
    if (this.loaderCounter === 0) {
      this.view.loader.style.display = 'none';
    }
  }

  /** Принудительное закрытие лоадера (сбрасывает счетчик в 0) */
  public forceHideLoader(): void {
    this.loaderCounter = 0;
    this.view.loader.style.display = 'none';
  }

  destroy() {
    this.unsubs.forEach(unsub => unsub());
  }
}
