// src/features/log/model/LogFeature.ts
/**
 * LogFeature — это UI
 * он не должен уметь писать события
 * только читать журнал
 * */
import {IFeature} from "@/shared/lib/Feature";
import {DiagnosticStore} from "@/shared/lib/diagnostics/DiagnosticStore";
import {LogWC} from "@/shared/ui/log/LogWC";
import {DiagnosticEvent} from "@/shared/lib/diagnostics/DiagnosticEvent";
import {LogVisibilityStore} from "@/features/log/model/LogVisibilityStore";
import {FileManagerEventBus} from "@/shared/lib/EventBus";

/** Отвечает за показ того что собрал `shared/lib/diagnostics/DiagnosticStore.ts` */
export class LogFeature implements IFeature {
  private unsubs: (() => void)[] = [];

  constructor(
    private bus: FileManagerEventBus,
    private logWC: LogWC,
    private diagnosticStore: DiagnosticStore,
    private store: LogVisibilityStore
  ) {
  }

  init() {
    // Подписываемся на изменения в DiagnosticStore
    this.unsubs.push(
      this.diagnosticStore.subscribe((state: DiagnosticEvent[]) => {
        // DiagnosticStore.ts хранит массив DiagnosticEvent
        this.logWC.logs = state;
      })
    );

    // 1. Реакция на toggle
    this.unsubs.push(
      this.bus.on("log:toggle", () => {
        this.store.toggle();
      })
    );

    // 2. Реакция на состояние
    this.unsubs.push(
      this.store.subscribe(({visible}) => {
        if (visible) {
          this.logWC.show();
        } else {
          this.logWC.hide();
        }
      })
    );

    // Если хочешь синхронизировать состояние при старте (чтобы лог сразу был в нужном состоянии):
    const { visible } = this.store.getValue();
    visible ? this.logWC.show() : this.logWC.hide();

  }

  destroy() {
    this.unsubs.forEach(u => u());
  }
}
