// TODO А можно сделать обработку ошибок с человекопонятными алертами, а не только в консоли

/**
 * Базовая ошибка приложения.
 * Все ошибки фронтенда должны наследоваться от неё.
 */
export class AppError extends Error {
  public readonly data: any;

  /** Для `shared/lib/diagnostics`
   * Использование в boundary-слое (feature / runtime):
   * ```
   * catch (e) {
   *   if (e instanceof AppError) {
   *     diagnostics.emit(e.level, e.message, { details: e });
   *   }
   * }
   * ```
   */
  level: 'error' | 'warning' | 'notice' = 'error';
  userVisible = true;
  source?: string;

  constructor(
    public message: string,
    data?: any,
  ) {
    super(message);
    // Важно для правильного прототипа и корректного stack trace в devtools
    this.name = 'AppError';
    Object.setPrototypeOf(this, AppError.prototype);
    this.data = data;
    this.logToConsole();
    this.showUserFriendlyAlert();
  }

  private logToConsole(): void {
    const timestamp = new Date().toISOString();

    console.groupCollapsed(
      `%c🚨 AppError: ${this.message}`,
      'color: #ff5555; font-weight: bold;'
    );
    console.log('%cВремя:', 'color: #999', timestamp);

    console.log('%cСообщение:', 'color: #ffaa00', this.message);

    if (this.data !== undefined && this.data !== null) {
      console.log('%cДанные ошибки:', 'color: #55aa55; font-weight: bold');
      console.log(this.data);
    } else {
      console.log('%cДанные ошибки: отсутствуют', 'color: #999');
    }

    console.groupEnd();
  }

  private showUserFriendlyAlert(): void {
    const userMessage =
      typeof this.data?.message === 'string' && this.data.message
        ? this.data.message
        : this.message;
    alert(`😔 Произошла ошибка:\n\n${userMessage}`);
  }

}
