import {AppError} from "@/shared/lib/error/AppError";
import {FileMetaDto} from "@/shared/api/fileManager/dto";

export class FileMeta {
  isWritable: boolean;
  isReadable: boolean;
  isExecutable: boolean;
  permissions: number;
  mTime: number;
  aTime: number;
  size: number;
  dimensions: Dimensions | null;

  constructor(meta: FileMetaDto | null) {

    if (!meta) {
      throw new AppError('Некорректные метаданные файла: meta is null', {meta});
    }

    if (typeof meta.isWritable !== "boolean" || typeof meta.isReadable !== "boolean" || typeof meta.isExecutable !== "boolean") {
      throw new AppError('Некорректные метаданные файла', {meta: meta});
    }

    if (typeof meta.permissions !== 'number' || typeof meta.mTime !== 'number' || typeof meta.aTime !== 'number' || typeof meta.size !== 'number') {
      throw new AppError('Некорректные метаданные файла', {meta: meta});
    }

    if (meta.mTime <= 0 || meta.aTime <= 0 || meta.size < 0 || meta.permissions <= 0) {
      throw new AppError('Некорректные метаданные файла', {meta: meta});
    }

    this.isWritable = meta.isWritable;
    this.isReadable = meta.isReadable;
    this.isExecutable = meta.isExecutable;
    this.permissions = meta.permissions;
    this.mTime = meta.mTime;
    this.aTime = meta.aTime;
    this.size = meta.size;

    // if (meta.dimensions && typeof meta.dimensions.height === 'number' && typeof meta.dimensions.width === 'number') {
    if (meta.dimensions) {
      this.dimensions = new Dimensions(meta.dimensions.height, meta.dimensions.width);
    } else {
      this.dimensions = null;
    }

  }
}

class Dimensions {
  public width: number = 0;
  public height: number = 0;

  constructor(width: number, height: number) {
    if (width <= 0 || height <= 0) {
      throw new AppError('Некорректные метаданные файла');
    }
    this.width = width;
    this.height = height;
  }
}
