import {isMenuAction} from "@/features/context-menu/lib/menu-config";
import {AppError} from "@/shared/lib/error/AppError";
import type {FileManagerEventBus} from "@/shared/lib/EventBus";
export class ActionExecutor {
  constructor(
    private readonly bus: FileManagerEventBus,
  ){}

  async execute(action: string) {

    if (!isMenuAction(action)) {
      throw new AppError(`ActionExecutor: Получено недопустимое действие меню: ${action}`)
    }

    try {
      switch (action) {
        case 'cut': this.bus.emit('clipboard:cut', ); break;
        case 'copy': this.bus.emit('clipboard:copy', ); break;
        case 'paste': this.bus.emit('clipboard:paste', ); break;
        case 'move-to': this.bus.emit('clipboard:move-to', ); break;
        case "none": break;

        case 'create-file': this.bus.emit('create:file:start'); break;
        case 'create-folder': this.bus.emit('create:folder:start'); break;

        case 'delete': this.bus.emit('delete:start' ); break;

        case 'download': this.bus.emit('download:start'); break;
        case 'download-zip': this.bus.emit('download-zip:start'); break;

        case 'preview': this.bus.emit('preview'); break;
        case 'open': this.bus.emit('open'); break;
        case 'open-with': this.bus.emit('open-with'); break;

        case 'properties': this.bus.emit('properties'); break; // TODO если Selection непустой
        case 'refresh': this.bus.emit('nav:refresh', ''); break;
        case 'rename': this.bus.emit('rename:start'); break;
        case 'upload': this.bus.emit('upload:request'); break;

        default:
          console.log('Действие пока не реализовано:', action); break;
      }
    } catch (err) {
      if (err instanceof AppError) {
        this.bus.emit('modal:alert:show', 'Ошибка: ' + err.message)
      } else {
        alert('Ошибка: ' + err);
        this.bus.emit('modal:alert:show', 'Ошибка: ' + err)
      }
    } finally {
      // bus.emit('modal:loader:force-hide', ); Надо ли здесь?
    }
  }
}
