// src/features/navigation/model/NavigationState.ts
import {Observable} from "@/shared/lib/Observable";

// Простое состояние для текущего пути.
// Наследуем базовую функциональность Observable<string>
export class NavigationState extends Observable<string> {

  /**
   * @param currentPath - Текущий путь, для открытия в файловом менеджере.
   * Полный путь до текущей директории, включая публичный корень `AppConfig.fmDefaultPath`.
   * При инициации равен публичному корню, в процессе меняется на путь текущей директории.
   */
  constructor(public currentPath: string) {
    super(currentPath);
  }

  setPath(path: string) {
    // Используем защищенный метод родителя
    this.setState(path);
    this.currentPath = path;
    this.listeners.forEach(l => l(path));
  }

  subscribe(cb: (path: string) => void) {
    this.listeners.add(cb);
    cb(this.currentPath);
    return () => this.listeners.delete(cb);
  }
}
