// src/shared/ui/toast/ToastWC.ts

import styles from './scss/toast.scss';

const sheet = new CSSStyleSheet();
sheet.replaceSync(styles);

export interface ToastItem {
  id: string;
  message: string;
  level: 'error' | 'warning' | 'notice';
}

interface ToastTimer {
  timeoutId?: number;
  startedAt: number;
  remaining: number;
}

export class ToastWC extends HTMLElement {
  private container!: HTMLElement;
  private timers = new Map<HTMLElement, ToastTimer>();

  connectedCallback() {
    if (this.shadowRoot) return;
    const shadow = this.attachShadow({mode: 'open'});
    shadow.adoptedStyleSheets = [sheet];

    this.container = document.createElement('div');
    this.container.className = 'toast-container';
    shadow.appendChild(this.container);
  }

  showToast(toast: ToastItem, duration = 5000) {
    const el = document.createElement('div');
    el.className = `toast toast-${toast.level}`;
    el.dataset.id = toast.id;

    const icon = {
      error: '🛇',
      warning: '⚠',
      notice: 'ℹ',
    }[toast.level];

    el.innerHTML = `
      <span class="toast-icon">${icon}</span>
      <span class="toast-message">${toast.message}</span>
      <button class="toast-close">×</button>
    `;

    const close = () => this.closeToast(el);

    el.querySelector('.toast-close')!.addEventListener('click', close);

    this.container.appendChild(el);

    if (duration > 0) {
      this.startTimer(el, duration);
      this.bindPauseOnHover(el);
    }
  }

  private startTimer(el: HTMLElement, duration: number) {
    const timer: ToastTimer = {
      startedAt: Date.now(),
      remaining: duration,
    };

    timer.timeoutId = window.setTimeout(() => {
      this.closeToast(el);
    }, duration);

    this.timers.set(el, timer);
  }

  private pauseTimer(el: HTMLElement) {
    const timer = this.timers.get(el);
    if (!timer || timer.timeoutId == null) return;

    window.clearTimeout(timer.timeoutId);
    timer.timeoutId = undefined;
    timer.remaining -= Date.now() - timer.startedAt;
  }

  private resumeTimer(el: HTMLElement) {
    const timer = this.timers.get(el);
    if (!timer || timer.remaining <= 0) return;

    timer.startedAt = Date.now();
    timer.timeoutId = window.setTimeout(() => {
      this.closeToast(el);
    }, timer.remaining);
  }

  private bindPauseOnHover(el: HTMLElement) {
    el.addEventListener('mouseenter', () => this.pauseTimer(el));
    el.addEventListener('mouseleave', () => this.resumeTimer(el));
  }

  private closeToast(el: HTMLElement) {
    el.classList.add('hide');
    this.timers.delete(el);

    setTimeout(() => {
      el.remove();
    }, 300);
  }
}

customElements.define('fm-toast', ToastWC);
