// src/shared/ui/resizable-modal/ResizableModalWC.ts

import {ResizeDirection, ResizeStrategy} from '@/shared/ui/modal/ResizeStrategy';

import styles from './scss/modal.scss';

const sheet = new CSSStyleSheet();
sheet.replaceSync(styles);

const STORAGE_KEY = 'fm-modal-size-settings';

export class ResizableModalWC extends HTMLElement {
  // Elements
  private modal: HTMLElement | null = null;
  private overlayInner: HTMLElement | null = null;
  private overlayGlobal: HTMLElement | null = null;
  private header: HTMLElement | null = null;
  public menuBar: HTMLElement | null = null;
  private contentContainer: HTMLElement | null = null;

  // State
  private startRect = {top: 0, left: 0, width: 0, height: 0};
  private startPointer = {x: 0, y: 0};
  private rafId: number | null = null; // ID для requestAnimationFrame

  connectedCallback(): void {
    if (this.shadowRoot) return;

    const shadow = this.attachShadow({mode: 'open'});
    shadow.adoptedStyleSheets = [sheet];
    shadow.innerHTML = this.getTemplate();

    this.modal = shadow.getElementById('modal');
    this.overlayInner = shadow.getElementById('overlay-inner');
    this.overlayGlobal = shadow.getElementById('overlay-global');
    this.header = shadow.querySelector('.header');
    this.menuBar = shadow.querySelector('.menu-bar');
    this.contentContainer = shadow.querySelector('.content');

    this.initInteractions();
    this.initCloseHandlers();
  }

  disconnectedCallback(): void {
    // Pointer events с setPointerCapture автоматически очищаются браузером при pointerup,
    // но явное удаление слушателей - хорошая практика, если элемент удаляется во время перетаскивания.
    document.body.style.overflow = '';
    document.body.style.touchAction = '';
  }

  /**
   * Инициализация событий Pointer API
   */
  private initInteractions(): void {
    if (!this.modal || !this.header || !this.shadowRoot) return;

    // 1. Dragging (Перетаскивание за заголовок)
    this.header.addEventListener('pointerdown', (e) => {
      // Игнорируем клики по кнопкам внутри хедера (например, закрыть)
      if ((e.target as HTMLElement).closest('button')) return;
      this.startDrag(e);
    });

    // 2. Resizing (Ресайз за маркеры)
    const resizers = this.shadowRoot.querySelectorAll('[data-resize]');
    resizers.forEach((resizer) => {
      resizer.addEventListener('pointerdown', (e) => {
        const direction = (e.currentTarget as HTMLElement).dataset.resize as ResizeDirection;
        this.startResize(e as PointerEvent, direction);
      });
    });

    // Кнопка закрытия
    this.shadowRoot.querySelector('.close-button')?.addEventListener('click', () => {
      this.closeModal();
    });
  }

  // ===================================================================================
  // DRAG LOGIC
  // ===================================================================================

  private startDrag(e: PointerEvent): void {
    if (!this.modal) return;

    e.preventDefault(); // Предотвращаем выделение текста и скролл на тач-устройствах
    const target = e.currentTarget as HTMLElement;

    // Захват курсора: все события pointermove теперь идут сюда
    target.setPointerCapture(e.pointerId);

    this.startPointer = {x: e.clientX, y: e.clientY};
    this.startRect = {
      left: this.modal.offsetLeft,
      top: this.modal.offsetTop,
      width: this.modal.offsetWidth,
      height: this.modal.offsetHeight
    };

    const onPointerMove = (ev: PointerEvent) => {
      if (this.rafId) cancelAnimationFrame(this.rafId);

      this.rafId = requestAnimationFrame(() => {
        const dx = ev.clientX - this.startPointer.x;
        const dy = ev.clientY - this.startPointer.y;

        // Ограничение области просмотра (viewport)
        let newLeft = this.startRect.left + dx;
        let newTop = this.startRect.top + dy;

        // Простая проверка границ экрана
        newLeft = Math.max(0, Math.min(newLeft, window.innerWidth - this.startRect.width));
        newTop = Math.max(0, Math.min(newTop, window.innerHeight - this.startRect.height));

        this.modal!.style.left = `${newLeft}px`;
        this.modal!.style.top = `${newTop}px`;
      });
    };

    const onPointerUp = (ev: PointerEvent) => {
      target.releasePointerCapture(ev.pointerId);
      target.removeEventListener('pointermove', onPointerMove as EventListener);
      target.removeEventListener('pointerup', onPointerUp as EventListener);
      if (this.rafId) cancelAnimationFrame(this.rafId);
    };

    target.addEventListener('pointermove', onPointerMove as EventListener);
    target.addEventListener('pointerup', onPointerUp as EventListener);
  }

  // ===================================================================================
  // RESIZE LOGIC
  // ===================================================================================

  private startResize(e: PointerEvent, direction: ResizeDirection): void {
    if (!this.modal) return;

    e.preventDefault();
    e.stopPropagation(); // Чтобы не триггернуть Drag на родителе

    const target = e.currentTarget as HTMLElement;
    target.setPointerCapture(e.pointerId);

    this.startPointer = {x: e.clientX, y: e.clientY};
    this.startRect = {
      left: this.modal.offsetLeft,
      top: this.modal.offsetTop,
      width: this.modal.offsetWidth,
      height: this.modal.offsetHeight
    };

    // Получаем лимиты CSS
    const computedStyle = getComputedStyle(this.modal);
    const limits = {
      minWidth: parseFloat(computedStyle.minWidth) || 200,
      minHeight: parseFloat(computedStyle.minHeight) || 150,
      maxWidth: window.innerWidth,
      maxHeight: window.innerHeight
    };

    const onPointerMove = (ev: PointerEvent) => {
      if (this.rafId) cancelAnimationFrame(this.rafId);

      this.rafId = requestAnimationFrame(() => {
        const dx = ev.clientX - this.startPointer.x;
        const dy = ev.clientY - this.startPointer.y;

        const newRect = ResizeStrategy.calculate(direction, this.startRect, dx, dy, limits);

        this.modal!.style.width = `${newRect.width}px`;
        this.modal!.style.height = `${newRect.height}px`;
        this.modal!.style.left = `${newRect.left}px`;
        this.modal!.style.top = `${newRect.top}px`;
      });
    };

    const onPointerUp = (ev: PointerEvent) => {
      target.releasePointerCapture(ev.pointerId);
      target.removeEventListener('pointermove', onPointerMove as EventListener);
      target.removeEventListener('pointerup', onPointerUp as EventListener);
      if (this.rafId) cancelAnimationFrame(this.rafId);

      this.saveState();// Сохраняем размеры в LocalStorage после окончания ресайза
    };

    target.addEventListener('pointermove', onPointerMove as EventListener);
    target.addEventListener('pointerup', onPointerUp as EventListener);

  }

  // ===================================================================================
  // STATE MANAGEMENT
  // ===================================================================================

  private saveState() {
    if (!this.modal) return;
    const settings = {
      width: this.modal.style.width,
      height: this.modal.style.height
    };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(settings));
  }

  private restoreState() {
    if (!this.modal) return;

    const saved = localStorage.getItem(STORAGE_KEY);

    if (saved) {
      try {
        const {width, height} = JSON.parse(saved);
        // Восстанавливаем сохраненные пиксели (или проценты, если вдруг сохранили их)
        if (width) this.modal.style.width = width;
        if (height) this.modal.style.height = height;
      } catch (e) {
        console.warn('Failed to parse modal settings', e);
      }
    } else {
      // [ВАЖНО] Дефолтное состояние при ПЕРВОМ открытии
      this.modal.style.width = '50vw';
      this.modal.style.height = '80vh';
    }
  }

  // ===================================================================================
  // PUBLIC API
  // ===================================================================================

  public setContent(element: HTMLElement): void {
    if (this.contentContainer) {
      this.contentContainer.replaceChildren(element);
    }
  }

  public appendOverlayInner(element: HTMLElement) {
    element.slot = 'overlays';
    this.appendChild(element);
  }

  public openModal(): void {

    this.restoreState();

    this.setAttribute('open', '');
    document.body.style.overflow = 'hidden'; // Блокировка скролла body
    document.body.style.touchAction = 'none'; // Для мобильных устройств

    // Центруем после того, как overlayGlobal появился
    requestAnimationFrame(() => {
      this.centerModal();
    });

    this.dispatchEvent(new CustomEvent('fm-modal-open', {
      bubbles: true,
      composed: true,
    }));
  }

  private centerModal(): void {
    if (!this.modal) return;

    // Берём реальные размеры окна и модалки
    const rect = this.modal.getBoundingClientRect();

    const width = rect.width || this.modal.offsetWidth;
    const height = rect.height || this.modal.offsetHeight;

    const left = Math.max(0, (window.innerWidth - width) / 2);
    const top = Math.max(0, (window.innerHeight - height) / 2);

    this.modal.style.left = `${left}px`;
    this.modal.style.top = `${top}px`;
  }

  public closeModal(): void {
    this.removeAttribute('open');
    document.body.style.overflow = '';
    document.body.style.touchAction = '';
    this.dispatchEvent(new CustomEvent('fm-modal-closed', {
      bubbles: true,
      composed: true,
    }));
  }

  // ===================================================================================
  // DOM
  // ===================================================================================
  private initCloseHandlers() {
    const closeButton = this.shadowRoot?.querySelector('.close-button');

    const fireCloseRequest = () => {
      this.dispatchEvent(new CustomEvent('fm-modal-close-request', {
        bubbles: true,
        composed: true, // чтобы всплывало за пределы shadowRoot
      }));
    };

    this.overlayGlobal?.addEventListener('click', (e) => {
      // Закрываем только если кликнули именно по фону, а не по модалке внутри
      if (e.target === this.overlayGlobal) {
        fireCloseRequest();
      }
    });

    closeButton?.addEventListener('click', (e) => {
      e.stopPropagation();
      fireCloseRequest();
    });

    document.addEventListener('keydown', (e: KeyboardEvent) => {
      if (e.key === 'Escape' && this.hasAttribute('open')) {
        fireCloseRequest();
      }
    });
  }

  // ===================================================================================
  // TEMPLATE
  // ===================================================================================

  private getTemplate(): string {
    // Используем data-resize вместо классов для чистоты логики
    return `
      <div id="overlay-global">
        <div id="modal">

          <div id="overlay-inner">
              <slot name="overlays"></slot>
          </div>

          <div class="header">
            <span class="title">File Manager</span>
            <button class="close-button">&times;</button>
          </div>

          <div class="menu-bar"><slot name="menu-bar"></slot></div>
          <div class="content"><slot></slot></div>
          <div class="footer"><slot name="footer"></slot></div>

          <div class="resizer top-left" data-resize="top-left"></div>
          <div class="resizer top-middle" data-resize="top-middle"></div>
          <div class="resizer top-right" data-resize="top-right"></div>
          <div class="resizer right-middle" data-resize="right-middle"></div>
          <div class="resizer bottom-right" data-resize="bottom-right"></div>
          <div class="resizer bottom-middle" data-resize="bottom-middle"></div>
          <div class="resizer bottom-left" data-resize="bottom-left"></div>
          <div class="resizer left-middle" data-resize="left-middle"></div>
        </div>
      </div>
    `;
  }

  // ===================================================================================
  // Чтобы не забыть, позже вынести всю логику определения мобильного браузера на уровень всего приложения
  // ===================================================================================

  /** Проверка на мобильный браузер */
  private isMobileDevice(): boolean {
    return window.innerWidth <= 768 || /Mobi|Android/i.test(navigator.userAgent);
  }

}

customElements.define('resizable-modal', ResizableModalWC);
