import {IFileManagerBackend} from "@/shared/api/fileManager/ports";
import {FileManagerEventBus} from "@/shared/lib/EventBus";
import {AppError} from "@/shared/lib/error/AppError";
import {UploadStatus} from "./UploadStatus";
import {LoadingStore} from "@/features/app-status/model/LoadingStore";
import {FileAnalysisService} from "@/entities/file/lib/FileAnalysisService";
import {DiagnosticService} from "@/shared/lib/diagnostics/DiagnosticService";

type UploadParams = {
  path: string;
  files: FileList | File[];
  concurrent?: number;
};
//######################################
// TODO При всём при этом посмотреть пакет `ckeditor5-upload` как там устроена загрузка файлов
// TODO - сделать возможность принудительного прерывания процесса загрузки
// TODO - Если ошибка в загрузке одного файла, то предлагать повторить попытку загрузки этого файла
//######################################
export class UploadService {
  private uploadStatus: UploadStatus[] = [];
  // Очередь хранит индекс и файл
  private uploadQueue: { file: File; index: number }[] = [];
  // Сохраняем оригинальные файлы по имени для RETRY
  private filesMap = new Map<string, File>();
  // Контроллеры для отмены активных запросов
  private abortControllers = new Map<string, AbortController>();

  private currentUploads = 0;
  private currentPath = ''; // Запоминаем путь загрузки

  private analyzer ;

  constructor(
    private readonly backend: IFileManagerBackend,
    private readonly bus: FileManagerEventBus,
    private diagnostics: DiagnosticService,
    private readonly maxConcurrentUploads: number = 3,
  ) {
    this.analyzer = new FileAnalysisService(this.diagnostics);
  }

  /**
   * Универсальный метод загрузки файлов.
   */
  public async upload({path, files, concurrent}: UploadParams): Promise<UploadStatus[]> {

    // ВАЖНО: Вместо полной очистки, удаляем только те файлы,
    // которые не находятся в процессе или не были загружены.
    // Если нужно начать "чистую" загрузку, вызывайте метод сброса отдельно.
    const fileArray = Array.from(files);
    if (!fileArray.length) throw new AppError('Empty FileList');

    this.currentPath = path;

    // === 1. ЭТАП ВАЛИДАЦИИ ===
    // Проверяем все файлы параллельно
    const analysisResults = await Promise.all(
      fileArray.map(file => this.analyzer.validateFile(file))
    );

    // Ищем ошибки
    const invalidFiles = analysisResults.filter(res => !res.isValid);
    if (invalidFiles.length > 0) {
      // Формируем сообщение об ошибке
      const errorMsg = invalidFiles
        .map(f => `• ${f.fileName} (Определен как: ${f.detectedMime}, Расширение: ${f.originalMime})`)
        .join('\n');

      // Выбрасываем ошибку, которую поймает UI и покажет Alert
      // throw new AppError(`Обнаружено несоответствие типов файлов:\n${errorMsg}\n\nЗагрузка прервана.`);
    }
    // ==========================

    const max = concurrent ?? this.maxConcurrentUploads;

    // Инициализируем статусы
    this.uploadStatus = fileArray.map((f) => ({
      fileName: f.name,
      progress: 0,
      status: 'pending' as const,
    }));

    // Сохраняем файлы в Map для возможности Retry
    this.filesMap.clear(); // TODO Мешает несколько раз возобновлять загрузку???
    fileArray.forEach(f => this.filesMap.set(f.name, f));

    // Очищаем контроллеры отмены
    this.abortControllers.forEach(ctrl => ctrl.abort());
    this.abortControllers.clear();

    // Эмитим старт загрузки
    const fakeList = Object.assign(fileArray, {item: (i: number) => fileArray[i] || null}) as FileList;
    this.bus.emit('upload:start', fakeList);

    // Создаем Promise для ожидания завершения всей загрузки
    return new Promise<UploadStatus[]>((resolve, reject) => {
      // Сбрасываем очередь
      this.uploadQueue = fileArray.map((file, index) => ({file, index}));
      this.currentUploads = 0;

      // Создаем обработчик для завершения загрузки
      const handleComplete = () => {
        const allCompleted = this.uploadStatus.every(s =>
          s.status === 'completed' || s.status === 'failed'
        );

        if (allCompleted) {
          this.bus.emit('upload:complete-full');
          resolve([...this.uploadStatus]); // Возвращаем копию статусов
        }
      };

      const handleError = (error: Error) => {
        reject(error);
      };

      // Обработчик для каждого завершенного файла
      const onFileComplete = (index: number, error?: Error) => {
        if (error) {
          this.updateStatus(index, {
            status: 'failed',
            error: error.message
          });
          // Если это критическая ошибка, которая должна прервать все загрузки
          if (error.message.includes('fatal') || error.message.includes('network')) {
            handleError(error);
            return;
          }
        }

        this.currentUploads--;

        // Проверяем, все ли файлы обработаны
        if (this.uploadQueue.length === 0 && this.currentUploads === 0) {
          handleComplete();
        } else {
          this.processQueue(onFileComplete);
        }
      };

      // Стартуем очередь
      this.processQueue(onFileComplete);
    });
  }

  private processQueue(onFileComplete?: (index: number, error?: Error) => void) {
    // Если очередь пуста и нет активных загрузок — всё
    if (this.uploadQueue.length === 0 && this.currentUploads === 0) {
      this.bus.emit('upload:complete-full');
      return;
    }

    while (this.currentUploads < this.maxConcurrentUploads && this.uploadQueue.length > 0) {
      const item = this.uploadQueue.shift();
      if (!item) break;

      this.currentUploads++;
      this.uploadOne(item.file, this.currentPath, item.index)
        .then(() => {
          onFileComplete?.(item.index);
        })
        .catch((error: Error) => {
          onFileComplete?.(item.index, error);
        });
    }
  }

  private async uploadOne(file: File, path: string, index: number): Promise<void> {
    this.updateStatus(index, {status: 'uploading', progress: 0});

    // Создаем контроллер отмены
    const controller = new AbortController();
    this.abortControllers.set(file.name, controller);

    try {
      await this.backend.upload({
        path,
        file,
        onProgress: (progress: number) => {
          this.updateStatus(index, {progress});
        },
        signal: controller.signal // Передаем сигнал
      });

      this.updateStatus(index, {progress: 100, status: 'completed'});
      this.bus.emit('upload:complete', `${path}/${file.name}`);
      this.bus.emit('nav:refresh', path); // Обновляем папку при успехе

    } catch (e: any) {
      if (e.message === 'Aborted') {
        // Обработка отмены (уже обработано в cancelAll, но на всякий случай)
        this.updateStatus(index, {status: 'failed', error: 'Отменено'});
      } else {
        this.updateStatus(index, {
          status: 'failed',
          error: e?.message ?? 'Upload failed',
        });
        this.bus.emit('upload:error', {fileName: file.name, error: e?.message});
        throw e; // Прокидываем ошибку дальше
      }
    } finally {
      this.abortControllers.delete(file.name);
    }
  }

// Метод для повтора конкретного файла
  public async retry(fileName: string) {
    const file = this.filesMap.get(fileName);
    if (!file) {
      console.error(`Файл ${fileName} не найден в карте загрузок.`);
      return;
    }

    // Проверяем, нет ли уже этого файла в очереди, чтобы избежать дублей
    const isAlreadyInQueue = this.uploadQueue.some(t => t.file.name === fileName);
    if (isAlreadyInQueue) return;

    // Находим индекс в массиве статусов
    const index = this.uploadStatus.findIndex(s => s.fileName === fileName);
    if (index === -1) return;

    // Сбрасываем статус
    this.updateStatus(index, {status: 'pending', progress: 0, error: undefined});

    // Добавляем в очередь (в начало, чтобы быстрее пошло)
    this.uploadQueue.unshift({file, index});

    // Если счетчик операций был сброшен (все завершились), поднимаем снова
    // if (this.currentUploads === 0 && this.uploadQueue.length === 1) {
    //
    // }

    this.processQueue();
  }

// Метод отмены всего
  public cancelAll() {
    // 1. Очищаем очередь ожидания
    this.uploadQueue = [];

    // 2. Прерываем активные запросы
    this.abortControllers.forEach(ctrl => ctrl.abort());
    this.abortControllers.clear();

    // Сбрасываем счетчик активных потоков
    this.currentUploads = 0;

    // 3. Обновляем статусы 'pending' и 'uploading' на 'failed' (Canceled)
    this.uploadStatus = this.uploadStatus.map(s =>
      (s.status === 'uploading' || s.status === 'pending')
        ? {...s, status: 'failed' as const, error: 'Cancelled'}
        : s
    );

    // 4. Одно событие на весь UI
    this.bus.emit('upload:progress-full', this.uploadStatus);
    this.bus.emit('upload:complete-full'); // Сигнал завершения сессии
  }

  private updateStatus(index: number, updates: Partial<UploadStatus>): void {
    this.uploadStatus[index] = {...this.uploadStatus[index], ...updates};
    this.bus.emit('upload:progress-full', this.uploadStatus);
    this.onProgressChange(this.uploadStatus);
  }

  public onProgressChange(status: UploadStatus[]): void {
    // можно переопределить извне
  }
}
