// src/features/directory-content/model/DirectoryContentFeature.ts
import { ViewModeStore } from "./ViewModeStore";
import type {FileManagerEventBus} from '@/shared/lib/EventBus';
import {
  DirectoryContentWC,
  DirectoryContextMenuDetail,
  DirectoryItemDetail,
  DirectorySelectionDetail,
} from '@/shared/ui/directory-content-desktop/DirectoryContentWC';
import {DndArea} from '@/shared/ui/dnd/DndArea';
import {ViewMode} from "./directory-content.events";
import {FolderRegistry} from "@/entities/folder/model/FolderRegistry";
import {NavigationState} from "@/features/navigation/model/NavigationState";
import {SelectionStore} from "@/features/selection/model/SelectionStore";
import {IFeature} from "@/shared/lib/Feature";

export class DirectoryContentFeature  implements IFeature{
  private unsubs: (() => void)[] = [];

  private dndArea?: DndArea;

  constructor(
    private readonly bus: FileManagerEventBus,
    private readonly panel: DirectoryContentWC,
    private registry: FolderRegistry,
    private navState: NavigationState,
    private selectionStore: SelectionStore, // Внедряем конкретный Store, так как мы его ИЗМЕНЯЕМ
    private viewModeStore: ViewModeStore, // Внедряем Store
  ) {
  }

  init() {

    // ПОДПИСКА НА РЕЖИМ ВИДА
    // Как только Store меняется -> обновляем атрибут в Web Component
    this.unsubs.push(
      this.viewModeStore.subscribe((mode) => {
        this.panel.setViewMode(mode);
      })
    );

    // 1. Если сменился путь...
    this.unsubs.push(
      this.navState.subscribe((currentPath) => {
        this.render(currentPath);
      })
    );

    // 2. Если обновились данные в кэше (например, Upload добавил файл)...
    this.unsubs.push(
      this.registry.subscribe(() => {
        // Перерисовываем текущий путь, так как данные могли измениться
        this.render(this.navState.getValue());
      })
    );

    // 2. Подписка на DOM-событие: Перехват выделения из WC
    // (обработчики — поля-стрелки: одна и та же ссылка для add/removeEventListener)
    this.panel.addEventListener('selection-change', this.handleSelectionFromWC as EventListener);

    // Убедимся, что удаляем именно эту подписку при destroy
    this.unsubs.push(() => {
      this.panel.removeEventListener('selection-change', this.handleSelectionFromWC as EventListener);
    });

    // Также DirectoryContentWC должен быть подписан на selectionStore,
    // чтобы визуально подсвечивать элементы
    this.unsubs.push(
      this.selectionStore.subscribe(state => {
        // Обновляем визуальное выделение в компоненте DirectoryContentWC
        // this.ui.setHighlighted(state.files, state.folders);
      })
    );

    /////////////////////////////////////////////

    this.panel.addEventListener('item-dblclick', this.onItemDblClick as EventListener);
    this.panel.addEventListener('selection-change', this.onSelectionChange as EventListener);
    this.panel.addEventListener('content-contextmenu', this.onContextMenu as EventListener);

    this.unsubs.push(() => {
      this.panel.removeEventListener('item-dblclick', this.onItemDblClick as EventListener);
      this.panel.removeEventListener('selection-change', this.onSelectionChange as EventListener);
      this.panel.removeEventListener('content-contextmenu', this.onContextMenu as EventListener);
    });

    // Подключаем DnD к панели
    this.dndArea = new DndArea({
      host: this.panel, // или метод getContentElement(), если захочешь
      onDropFiles: (files) => {
        // Вариант 1: всегда текущая директория
        this.bus.emit('upload:drop', {files});

        // если захочешь дроп именно на папку под курсором,
        // здесь же можно вычислить path по event.target
      },
    });

  }

  private render(path: string) {
    const folder = this.registry.getFolderByPath(path);
    if (folder) {
      this.panel.setContent(folder);
    }
  }

  /** Обновляем содержимое панели при загрузке директории */
  // onDirLoaded(path: string) {
  //   const folder = this.state.getFolderDataByPath(path);
  //   this.panel.setContent(folder);
  // };

  /** Мост: двойной клик по элементу → nav:openDir или directory-content:file:dblclick */
  onItemDblClick = (e: Event): void => {
    const ev = e as CustomEvent<DirectoryItemDetail>;
    const {type, key} = ev.detail;

    if (!key) return;

    if (type === 'folder') {
      this.bus.emit('nav:openDir', key);
    } else if (type === 'file') {
      const file = this.registry.getFileEntity(key);
      if (file) {
        this.bus.emit('directory-content:file:dblclick', file);
      }
    }
  };

  /** Мост: изменение выделения → selection:change */
  onSelectionChange = (e: Event): void => {
    const ev = e as CustomEvent<DirectorySelectionDetail>;
    const selection = ev.detail;
    this.bus.emit('selection:change', selection);
  };

  // !!! Новый метод, который заменяет onSelectionChange(e) !!!
  /** * Обработчик DOM-события 'selection-change' от DirectoryContentWC.
   * Переводит данные выделения из DOM-модели в центральный Store.
   */
  private handleSelectionFromWC = (e: Event): void => {
    // Тип DirectorySelectionDetail уже Set<DirectoryItemDetail>
    const ev = e as CustomEvent<DirectorySelectionDetail>;
    const selectionSet = ev.detail;

    // Обновляем центральное хранилище, передавая ему Set напрямую.
    // Это автоматически уведомит все другие фичи (DeleteFeature, ClipboardFeature и т.д.).
    this.selectionStore.setSelection(selectionSet);
  };

  /** Мост: контекстное меню по элементу → contextmenu:open */
  onContextMenu = (e: Event): void => {

    const ev = e as CustomEvent<DirectoryContextMenuDetail>;
    const {type, key, event} = ev.detail;

    this.bus.emit('contextmenu:open', {
      event,
      target: {type, key, path: key}, // если нужно отдельно path — можно завести
      scope: 'content',
    });
  };

  destroy() {
    this.dndArea?.destroy();
    this.unsubs.forEach(unsub => unsub());
  }
}
