// src/shared/api/fileManager/httpBackend.ts

import {
  AnalyzeRequest,
  CreateDirRequest,
  DeleteRequest,
  GetConfigResponse,
  IFileManagerBackend,
  ListRequest,
  ListResponse,
  MoveRequest,
  MoveResponse,
  RenameRequest,
  RenameResponse,
  UploadRequest,
  UploadResponse,
} from './ports';
import {HttpClient} from '../httpClient';
import {DeleteResponseDto, FileAnalysisDto, FileDto} from "@/shared/api/fileManager/dto";

/** Конкретный адаптер, который реализует интерфейс и ходит на REST-API: */
export class HttpFileManagerBackend implements IFileManagerBackend {
  constructor(private readonly http: HttpClient) {
  }

  list(req: ListRequest): Promise<ListResponse> {
    return this.http.post<ListResponse>('/list', req);
  }

  createDir(req: CreateDirRequest): Promise<FileDto> {
    return this.http.post<FileDto>('/mkdir', req);
  }

  rename(req: RenameRequest): Promise<RenameResponse> {
    return this.http.post<RenameResponse>('/rename', req);
  }

  move(req: MoveRequest): Promise<MoveResponse> {
    return this.http.post<MoveResponse>('/move', req);
  }

  delete(req: DeleteRequest): Promise<DeleteResponseDto> {
    return this.http.post<DeleteResponseDto>('/delete', req);
  }

  async upload(req: UploadRequest): Promise<UploadResponse> {
    const formData = new FormData();
    formData.append('path', req.path);
    formData.append('file', req.file, req.file.name);
    return this.http.upload('/upload', formData, {
      onProgress: req.onProgress, // Если у вас там другая сигнатура адаптера, поправьте
      signal: req.signal
    });
  }

  analyze(req: AnalyzeRequest): Promise<FileAnalysisDto> {
    // Предполагаем, что на бэке есть эндпоинт /analyze
    return this.http.post<FileAnalysisDto>('/analyze', req);
  }

  getConfig(): Promise<GetConfigResponse> {
    return this.http.post<GetConfigResponse>('/config', {});
  }
}
