// src/shared/ui/tree/TreeWC.ts

import { FolderEntity } from "@/entities/folder/model/FolderEntity";
import styles from './scss/tree.scss';

const sheet = new CSSStyleSheet();
sheet.replaceSync(styles);

// Типы событий, которые ожидает Feature (оставляем совместимыми с тем, что было)
export type DirClickDetail = {
  key: string;
  path: string | null;
};

export type DirContextMenuDetail = {
  key: string;
  path: string | null;
  event: PointerEvent;
};

export class TreeWC extends HTMLElement {
  private currentPath: string | null = null;
  private folder: FolderEntity | null = null;
  private rootContainer: HTMLElement | null = null;

  constructor() {
    super();
  }

  connectedCallback() {
    if (this.shadowRoot) return;
    const shadow = this.attachShadow({ mode: 'open' });
    shadow.adoptedStyleSheets = [sheet];

    // Создаем контейнер, куда будем рендерить дерево
    this.rootContainer = document.createElement('div');
    this.rootContainer.id = 'tree-root';
    shadow.appendChild(this.rootContainer);

    // --- ДЕЛЕГИРОВАНИЕ СОБЫТИЙ ---
    // Вешаем слушатели один раз на контейнер/хост
    this.rootContainer.addEventListener('click', this.handleContainerClick);
    this.rootContainer.addEventListener('contextmenu', this.handleContainerContextMenu);
  }

  disconnectedCallback() {
    if (this.rootContainer) {
      this.rootContainer.removeEventListener('click', this.handleContainerClick);
      this.rootContainer.removeEventListener('contextmenu', this.handleContainerContextMenu);
    }
  }

  /**
   * Публичный метод: Установка данных и перерисовка
   */
  setTreeData(folder: FolderEntity) {
    this.folder = folder;
    this.render();

    // Если путь был задан ранее, восстанавливаем подсветку
    if (this.currentPath) {
      this.highlightPath(this.currentPath);
    }
  }

  /**
   * Публичный метод: Подсветка активной директории
   */
  highlightPath(path: string | null) {
    this.currentPath = path;

    if (!this.shadowRoot) return;

    // 1. Снимаем старое выделение
    const prevSelected = this.shadowRoot.querySelector('.tree-label.selected');
    if (prevSelected) {
      prevSelected.classList.remove('selected');
    }

    if (!path) return;

    // 2. Ищем элемент по атрибуту data-key
    // Экранируем кавычки в селекторе, если в путях могут быть спецсимволы
    const targetLabel = this.shadowRoot.querySelector(`.tree-label[data-key="${CSS.escape(path)}"]`);

    if (targetLabel) {
      targetLabel.classList.add('selected');
      // Опционально: скролл к элементу
      targetLabel.scrollIntoView({ block: 'nearest', inline: 'nearest' });
    }
  }

  /**
   * Основной метод рендеринга
   */
  private render() {
    if (!this.rootContainer || !this.folder) return;

    this.rootContainer.innerHTML = '';

    // Создаем фрагмент для оптимизации вставки в DOM
    const fragment = document.createDocumentFragment();

    // Рендерим корневую папку (isRoot = true)
    const rootNode = this.createNode(this.folder, true);
    fragment.appendChild(rootNode);

    this.rootContainer.appendChild(fragment);
  }

  /**
   * Рекурсивное создание DOM-элементов
   */
  private createNode(folder: FolderEntity, isRoot: boolean): HTMLElement {
    // 1. Контейнер узла
    const nodeContainer = document.createElement('div');
    nodeContainer.classList.add('tree-node');

    // 2. Лейбл (само название папки)
    const label = document.createElement('div');
    label.classList.add('tree-label');

    // Сохраняем данные в dataset для делегирования событий
    label.dataset.key = folder.key;
    label.dataset.path = folder.path; // path родителя, или полный путь, зависит от вашей логики FolderEntity

    // Логика названия для корня vs обычных папок
    label.textContent = isRoot
      ? `${folder.path}/${folder.name}`.replace('//', '/') // Простой фикс двойных слешей
      : folder.name;

    // Иконку (треугольник раскрытия) можно добавить сюда же

    nodeContainer.appendChild(label);

    // 3. Рекурсия для детей
    if (folder.folders && folder.folders.size > 0) {
      const childrenContainer = document.createElement('div');
      childrenContainer.classList.add('tree-children');

      folder.folders.forEach((childFolder) => {
        const childNode = this.createNode(childFolder, false);
        childrenContainer.appendChild(childNode);
      });

      nodeContainer.appendChild(childrenContainer);
    }

    return nodeContainer;
  }

  // --- ОБРАБОТЧИКИ СОБЫТИЙ (Delegation) ---

  private handleContainerClick = (e: MouseEvent) => {
    // 1. Пытаемся найти ближайший .tree-label
    const target = (e.target as HTMLElement).closest('.tree-label') as HTMLElement;

    if (target) {
      // Клик по папке
      e.stopPropagation();
      const key = target.dataset.key;
      const path = target.dataset.path;

      if (key) {
        this.dispatchEvent(new CustomEvent<DirClickDetail>('dir-click', {
          detail: { key, path: path ?? null },
          bubbles: true,
          composed: true
        }));
      }
    } else {
      // Клик по "пустому" месту внутри дерева
      // (если нужно снять выделение или закрыть контекстное меню)
      this.dispatchEvent(new CustomEvent('tree-click', {
        bubbles: true,
        composed: true
      }));
    }
  };

  private handleContainerContextMenu = (e: MouseEvent) => {
    // Запрещаем стандартное меню браузера везде внутри дерева
    e.preventDefault();

    const target = (e.target as HTMLElement).closest('.tree-label') as HTMLElement;

    if (target) {
      const key = target.dataset.key;
      const path = target.dataset.path;

      if (key) {
        this.dispatchEvent(new CustomEvent<DirContextMenuDetail>('dir-contextmenu', {
          detail: {
            key,
            path: path ?? null,
            event: e as PointerEvent // Кастуем, так как MouseEvent совместим
          },
          bubbles: true,
          composed: true
        }));
      }
    } else {
      // Контекстное меню на пустом месте (опционально)
      this.dispatchEvent(new CustomEvent('tree-rmc', {
        bubbles: true,
        composed: true
      }));
    }
  };
}

customElements.define('tree-wc', TreeWC);
