// src/features/context-menu/model/ContextMenuFeature.ts

import type {FileManagerEventBus} from '@/shared/lib/EventBus';
import {ContextMenuService} from './ContextMenuService';
import {ActionExecutor} from './ActionExecutor';
import {IObservable} from "@/shared/lib/Observable";
import {SelectionState} from "@/features/selection/model/SelectionStore";
import {IFeature} from "@/shared/lib/Feature";
import {isMenuAction} from "@/features/context-menu/lib/menu-config";
import {ContextMenuWC} from "@/shared/ui/context-menu/ContextMenuWC";

export class ContextMenuFeature implements IFeature {
  private service: ContextMenuService;
  private executor: ActionExecutor;
  private unsubs: (() => void)[] = [];

  private onItemClick = this.itemClickListener.bind(this);

  constructor(
    private readonly bus: FileManagerEventBus,
    selectionState: IObservable<SelectionState>,
    private contextMenu: ContextMenuWC,
  ) {
    this.service = new ContextMenuService(selectionState);
    this.executor = new ActionExecutor(this.bus);
  }

  init() {
    this.unsubs.push(
      // Слушаем запрос от UI (FileTree или DirContent)
      this.bus.on('contextmenu:open', ({event, target, scope}: {
        event: PointerEvent;
        target?: { type: 'folder' | 'file' | 'empty'; key?: string; path?: string };
        scope?: 'tree' | 'content' | 'global';
      }) => {
        this.contextMenu.items = JSON.stringify(this.service.getMenuItems());
        this.contextMenu.show(event);
      }),
    );

    // Клик по пункту
    this.contextMenu.addEventListener('contextmenu:action', this.onItemClick as EventListener);
    this.unsubs.push(() => {
      this.contextMenu.removeEventListener('contextmenu:action', this.onItemClick as EventListener);
    });

  }

  async itemClickListener(e: Event) {
    const ev = e as CustomEvent;
    const {action, event} = ev.detail;
    if (!action || !isMenuAction(action)) {
      console.error(`ActionExecutor: Получено недопустимое действие меню: ${action}`);
      return;
    }
    await this.executor.execute(action);
  }

  protected setSummary(): HTMLLIElement {
    const el = document.createElement('li');
    el.classList.add('summary');
    el.textContent = 'TODO';
    return el
  }


  destroy() {
    this.unsubs.forEach(unsub => unsub());
  }
}
