// src/features/refresh/model/RefreshFeature.ts
import {IFeature} from "@/shared/lib/Feature";
import {FileManagerEventBus} from "@/shared/lib/EventBus";
import {NavigationState} from "@/features/navigation/model/NavigationState";

export class RefreshFeature implements IFeature {
  private keyHandler = this.handleKeyPress.bind(this);

  constructor(
    private bus: FileManagerEventBus,
    private navState: NavigationState,
  ) {
  }

  init() {
    document.addEventListener('keydown', this.keyHandler);
  }

  handleKeyPress(event: KeyboardEvent) {
    // F5 key code is 116
    if (event.key === 'F5' || event.keyCode === 116) {
      event.preventDefault();
      this.bus.emit('nav:refresh', this.navState.getValue());
    }
  }

  destroy() {
    document.removeEventListener('keydown', this.keyHandler);
  }
}
