// src/app/AppRuntime.ts

import { Container, DI_TOKENS, setupContainer } from '@/app/di';
import { FileManagerWidget } from '@/widgets/file-manager/FileManagerWidget';
import type { FileManagerEventBus } from '@/shared/lib/EventBus';
import type { AppConfig } from '@/app/AppConfig';
import type { IFileManagerBackend } from '@/shared/api/fileManager/ports';
import type { FileEntity } from '@/entities/file/model/FileEntity';
import type { DiagnosticService } from '@/shared/lib/diagnostics/DiagnosticService';

export interface AppRuntimeDeps {
  backend: IFileManagerBackend;
}

/**
 * Универсальный runtime файлового менеджера.
 *
 * Теперь использует DI-контейнер для управления зависимостями.
 * Ответственность:
 * - Создание и настройка DI-контейнера
 * - Lifecycle приложения (open/destroy)
 * - Обработка глобальных событий (close, select)
 * - Error boundary
 *
 * @example
 * ```ts
 * const fm = new AppRuntime(config, { backend });
 * await fm.open();
 *
 * // При необходимости закрытия:
 * fm.close('external');
 * ```
 */
export class AppRuntime {
  private readonly container: Container;
  private readonly widget: FileManagerWidget;
  private readonly bus: FileManagerEventBus;
  private readonly diagnostics: DiagnosticService;

  private unsubClose?: () => void;
  private unsubDblClick?: () => void;

  /** Защита от повторного destroy(): его вызывают и обработчик 'fm:close', и внешний владелец (адаптер). */
  private destroyed = false;

  /**
   * Обработчики глобального error boundary — стабильные ссылки (поля-стрелки),
   * чтобы removeEventListener в destroy() снимал именно их.
   */
  private readonly handleUnhandledRejection = (e: PromiseRejectionEvent): void => {
    this.diagnostics.error(
      'Необработанная ошибка приложения',
      { details: e.reason, source: 'runtime' }
    );
  };

  private readonly handleError = (e: ErrorEvent): void => {
    this.diagnostics.error(
      'Критическая ошибка приложения',
      { details: e.error, source: 'runtime' }
    );
  };

  constructor(
    private readonly config: AppConfig,
    deps: AppRuntimeDeps
  ) {
    // 1. Создаём и настраиваем DI-контейнер
    this.container = setupContainer({
      config,
      backend: deps.backend,
    });

    // 2. Получаем ключевые зависимости
    this.bus = this.container.get(DI_TOKENS.BUS);
    this.diagnostics = this.container.get(DI_TOKENS.DIAGNOSTIC_SERVICE);

    // 3. Создаём виджет, передавая контейнер
    this.widget = new FileManagerWidget(this.container);

    // 4. Настраиваем глобальные обработчики
    this.setupEventHandlers();
    this.setupGlobalErrorBoundary();
  }

  /**
   * Настройка обработчиков событий
   */
  private setupEventHandlers(): void {
    // Подписка на глобальное событие закрытия (!!! единственная точка уничтожения ФМ !!!)
    this.unsubClose = this.bus.on('fm:close', (payload) => {
      this.config.onClose?.(payload);
      this.destroy();
    });

    // Мост "двойной клик по файлу → внешний onSelect"
    if (typeof this.config.onSelect === 'function') {
      this.unsubDblClick = this.bus.on('directory-content:file:dblclick', (file: FileEntity) => {
        this.config.onSelect?.([file]); // Вставляем один файл (или массив из одного)
      });
    }
  }

  /**
   * Глобальный обработчик ошибок
   */
  private setupGlobalErrorBoundary(): void {
    window.addEventListener('unhandledrejection', this.handleUnhandledRejection);
    window.addEventListener('error', this.handleError);
  }

  /**
   * Открывает файловый менеджер
   */
  async open(): Promise<void> {
    await this.widget.init();
  }

  /**
   * Публичный запрос на закрытие ФМ — для внешних владельцев (например, CKEditor-адаптера).
   * Эмитит 'fm:close', то есть проходит ту же единственную точку уничтожения, что крестик,
   * Esc и overlay: сработают config.onClose и destroy(). Лезть в приватную шину снаружи не нужно.
   */
  close(source: string = 'external'): void {
    this.bus.emit('fm:close', { source });
  }

  /**
   * Уничтожает runtime и все его зависимости. Идемпотентен: повторный вызов — no-op
   * (destroy() вызывают и обработчик 'fm:close', и внешний владелец, например CKEditor-адаптер).
   */
  destroy(): void {
    if (this.destroyed) {
      return;
    }
    this.destroyed = true;

    // Снимаем глобальный error boundary — иначе каждое новое открытие ФМ копит listeners
    // на window и удерживает уничтоженные runtime в памяти.
    window.removeEventListener('unhandledrejection', this.handleUnhandledRejection);
    window.removeEventListener('error', this.handleError);

    // Отписываемся от событий
    this.unsubClose?.();
    this.unsubClose = undefined;

    this.unsubDblClick?.();
    this.unsubDblClick = undefined;

    // Уничтожаем виджет (он уничтожит фичи и layout)
    this.widget.destroy();

    // Очищаем шину
    this.bus.clear();
  }

  /**
   * Публичный доступ к контейнеру (для тестов и расширений)
   */
  getContainer(): Container {
    return this.container;
  }
}
