import { Observable } from "@/shared/lib/Observable";

export type ViewMode = 'grid' | 'list';

const STORAGE_KEY = 'fm-view-mode';

export class ViewModeStore extends Observable<ViewMode> {
  constructor() {
    // 1. Пытаемся восстановить из LocalStorage
    const savedMode = localStorage.getItem(STORAGE_KEY) as ViewMode;
    const initialMode: ViewMode = (savedMode === 'list' || savedMode === 'grid')
      ? savedMode
      : 'grid';

    super(initialMode);
  }

  public setMode(mode: ViewMode) {
    if (this.getValue() !== mode) {
      this.setState(mode);
      localStorage.setItem(STORAGE_KEY, mode);
    }
  }

  public toggle() {
    const newMode = this.getValue() === 'grid' ? 'list' : 'grid';
    this.setMode(newMode);
  }
}
