import {BaseOpenableWC} from './BaseOpenableWC';

import styles from './scss/dialog.scss';

const sheet = new CSSStyleSheet();
sheet.replaceSync(styles);

export class DialogWC extends BaseOpenableWC {
  private content: HTMLElement | null = null;
  private acceptButton: HTMLElement | null = null;
  private cancelButton: HTMLElement | null = null;

  connectedCallback(): void {

    if (this.shadowRoot) return;

    const shadow = this.attachShadow({mode: 'open'});
    shadow.adoptedStyleSheets = [sheet];
    shadow.innerHTML = this.getTemplate();

    this.content = shadow.querySelector('.content');
    this.acceptButton = shadow.querySelector('.accept');
    this.cancelButton = shadow.querySelector('.cancel');

    if (this.acceptButton) {
      this.acceptButton.addEventListener('click', () => this.handleAccept());
    }

    if (this.cancelButton) {
      this.cancelButton.addEventListener('click', () => this.handleCancel());
    }

  }

  disconnectedCallback(): void {
  }

  private getTemplate(): string {
    return `
<div class='content'>DEMO</div>
<div class="buttons">
    <button class="accept">✔</button>
    <button class="cancel">🛇</button>
</div>
    `;
  }

  private handleAccept(): void {
    this.dispatchEvent(new CustomEvent('accept'));
    this.closeDialog();
  }

  private handleCancel(): void {
    this.dispatchEvent(new CustomEvent('cancel'));
    this.closeDialog();
  }

  public closeDialog(): void {
    this.open = false;
  }

  public openDialog(prompt: string = ''): Promise<boolean> {
    const div = document.createElement('div');
    div.textContent = prompt;
    this.setContentAndOpen(div);

    return this.waitForDecision(
      () => true,
      () => false
    );
  }

  public openInputDialog(prompt: string): Promise<string> {
    const label = document.createElement('div');
    label.textContent = prompt;

    const input = document.createElement('input');
    input.type = 'text';
    input.id = 'newVal';

    this.setContentAndOpen(label, input);
    input.focus();

    return this.waitForDecision(
      () => input.value,
      () => {
        // можно бросить ошибку или вернуть пустую строку/null — на твой вкус
        return ''; // throw new Error('Dialog cancelled');
      }
    );
  }
  public openRenameDialog(prompt: string, fileName: string): Promise<string> {
    const label = document.createElement('div');
    label.textContent = prompt;

    const input = document.createElement('input');
    input.type = 'text';
    input.id = 'newVal';
    input.value = fileName;

    // --- Автоматическая ширина input в зависимости от содержимого ---
    // 1. Вычисляем ширину: длина имени + запас (например, 5 символов).
    // 2. Ограничиваем минимум (чтобы не был слишком узким для коротких имен).
    // 3. Максимум ограничивается CSS-ом самого диалога (max-width: 90% [cite: 928]).
    const widthInChars = Math.max(25, fileName.length + 5);
    input.style.width = `${widthInChars}ch`;
    input.style.maxWidth = 'calc(100% - 6px)'; // Страховка, чтобы не вылезал за пределы контейнера

    this.setContentAndOpen(label, input);

    // выделение части без расширения
    const dotIndex = fileName.lastIndexOf('.');
    const baseName = dotIndex !== -1 ? fileName.slice(0, dotIndex) : fileName;

    input.focus();
    input.setSelectionRange(0, baseName.length);

    return this.waitForDecision(
      () => input.value,
      () => {
        return ''; // throw new Error('Dialog cancelled');
      }
    );
  }

  public openInfoDialog(element: HTMLElement): Promise<void> {
    this.setContentAndOpen(element);

    return this.waitForDecision(
      () => {},
      () => {}
    );
  }

  public setContent(content: HTMLElement): void {
    this.content?.appendChild(content);
  }

  private waitForDecision<T>(
    onAccept: () => T,
    onCancel: () => T | Promise<T>
  ): Promise<T> {
    return new Promise<T>((resolve) => {
      const acceptHandler = () => {
        cleanup();
        resolve(onAccept());
      };

      const cancelHandler = async () => {
        cleanup();
        resolve(await onCancel());
      };

      const cleanup = () => {
        this.removeEventListener('accept', acceptHandler);
        this.removeEventListener('cancel', cancelHandler);
        this.closeDialog();
      };

      this.addEventListener('accept', acceptHandler, {once: true});
      this.addEventListener('cancel', cancelHandler, {once: true});
    });
  }

  private setContentAndOpen(...nodes: HTMLElement[]): void {
    this.content?.replaceChildren(...nodes);
    this.open = true;
  }

}

customElements.define('dialog-wc', DialogWC);
