// src/shared/ui/log/LogWC.ts
import {DiagnosticEvent} from '@/shared/lib/diagnostics/DiagnosticEvent';

import styles from './scss/log.scss';

const sheet = new CSSStyleSheet();
sheet.replaceSync(styles);

export class LogWC extends HTMLElement {
  private listElement!: HTMLUListElement;
  private emptyElement!: HTMLDivElement;

  connectedCallback() {
    if (this.shadowRoot) return;
    const shadow = this.attachShadow({mode: 'open'});
    shadow.adoptedStyleSheets = [sheet];

    this.emptyElement = document.createElement('div');
    this.emptyElement.className = 'empty';
    this.emptyElement.textContent = 'Лог пуст';

    this.listElement = document.createElement('ul');

    shadow.append(
      this.emptyElement,
      this.listElement
    );

    this.updateEmptyState();
  }

  public set logs(events: DiagnosticEvent[]) {
    this.listElement.innerHTML = '';
    events.forEach(event => {
      const li = document.createElement('li');
      li.className = event.level;
      const time = new Date(event.timestamp).toLocaleString('ru-RU');
      li.innerHTML = `<span class="timestamp">[${time}]</span> [${event.source}] ${event.message}`;
      this.listElement.appendChild(li);
    });
    this.updateEmptyState();
  }

  private updateEmptyState() {
    const isEmpty = this.listElement.children.length === 0;
    this.emptyElement.style.display = isEmpty ? 'block' : 'none';
  }

  show() {
    this.classList.add('active');
  }

  hide() {
    this.classList.remove('active');
  }
}

customElements.define('fm-log', LogWC);
