// src/app/di/Container.ts

/**
 * Простой DI-контейнер без внешних зависимостей.
 *
 * Поддерживает:
 * - Регистрацию singleton и transient зависимостей
 * - Lazy-инициализацию (создание при первом запросе)
 * - Типобезопасный доступ к зависимостям
 *
 * @example
 * ```ts
 * const container = new Container();
 * container.singleton('bus', () => new EventBus());
 * container.singleton('navState', () => new NavigationState('/files'));
 *
 * const bus = container.get('bus');
 * ```
 */

type Factory<T> = (container: Container) => T;

interface Registration<T = unknown> {
  factory: Factory<T>;
  singleton: boolean;
  instance?: T;
}

export class Container {
  private registrations = new Map<string, Registration>();

  /**
   * Регистрирует singleton - создаётся один раз при первом запросе
   */
  singleton<T>(token: string, factory: Factory<T>): this {
    this.registrations.set(token, {
      factory,
      singleton: true,
    });
    return this;
  }

  /**
   * Регистрирует transient - создаётся при каждом запросе
   */
  transient<T>(token: string, factory: Factory<T>): this {
    this.registrations.set(token, {
      factory,
      singleton: false,
    });
    return this;
  }

  /**
   * Регистрирует уже созданный экземпляр
   */
  instance<T>(token: string, instance: T): this {
    this.registrations.set(token, {
      factory: () => instance,
      singleton: true,
      instance,
    });
    return this;
  }

  /**
   * Получает зависимость по токену
   */
  get<T>(token: string): T {
    const registration = this.registrations.get(token);

    if (!registration) {
      throw new Error(`[DI] Зависимость "${token}" не зарегистрирована`);
    }

    if (registration.singleton) {
      if (!registration.instance) {
        registration.instance = registration.factory(this);
      }
      return registration.instance as T;
    }

    return registration.factory(this) as T;
  }

  /**
   * Проверяет, зарегистрирована ли зависимость
   */
  has(token: string): boolean {
    return this.registrations.has(token);
  }

  /**
   * Очищает все зарегистрированные зависимости
   */
  clear(): void {
    this.registrations.clear();
  }
}
