import {FileMeta} from "./FileMeta.js";
import {AppError} from "@/shared/lib/error/AppError";
import {FileDto} from "@/shared/api/fileManager/dto";

export class FileEntity {
  name: string = ''; // TODO - там есть какие-то ситуации когда имя пустое, кажется... обработать эти ситуации
  path: string = '';
  extension: string = '';
  type: string | null = null;
  fileType: string = '';
  url: string | null = null;
  meta: FileMeta | null = null;

  /** @see https://habr.com/ru/articles/803823/ */
  protected imgExtensions = new Map([
    ['image/jpeg', ['jpg', 'jpeg', 'jpe', 'jif', 'jfif', 'jfi']],
    ['image/png', ['png']],
    ['image/apng', ['png', 'apng']],
    ['image/gif', ['gif']],
    ['image/webp', ['webp']],
    ['image/avif', ['avif']],
    ['image/heif', ['heif']],
    // ['image/heic', ['heic']], // Браузер не отображает
    ['image/svg+xml', ['svg']],
  ]);

  constructor(file: FileDto) {
    this.fill(file);
  }

  fill(file: FileDto) {
    this.setName(file.name);
    this.setPath(file.path);
    this.setExtension(file.extension);
    this.setType(file.type);
    this.setFileType(file.fileType);
    this.setUrl(file.url);
    this.meta = new FileMeta(file.meta);

  }

  private setName(name: string | null | undefined) {
    if (typeof name !== 'string' || name == '') {
      throw new AppError('Некорректное название файла: ' + String(name));
    }
    this.name = name;
  }

  private setPath(path: string | null | undefined) {
    // Пустая строка — валидный путь (виртуальный/публичный корень: сервер намеренно скрывает
    // реальный корень). Невалидно лишь не-строковое значение.
    if (typeof path !== 'string') {
      throw new AppError('Некорректный путь к файлу: ' + String(path));
    }
    this.path = path;
  }

  private setExtension(extension: string | null | undefined) {
    if (typeof extension !== 'string') {
      throw new AppError('Некорректное расширение файла');
    }
    this.extension = extension;
  }

  private setType(type: string | null | undefined) {
    if (typeof type !== 'string' || type !== 'file') {
      throw new AppError('Некорректный тип файла');
    }
    this.type = 'file';
  }

  private setFileType(fileType: string | null | undefined) {
    // Непонятно какую можно сделать проверку. Здесь будет человекопонятный тип файла. Например, 'PNG image'.
    if (typeof fileType !== 'string') {
      throw new AppError('Не указан тип файла');
    }
    this.fileType = fileType;
  }

  private setUrl(url: string | null | undefined) {
    // null — валидное значение по контракту FileDto.url (string | null): у точки монтирования
    // нет публичной отдачи файлов (например, ZIP-mount без download-эндпоинта).
    // Пустую строку нормализуем в null; невалиден лишь иной не-строковый тип.
    if (url !== null && typeof url !== 'string') {
      throw new AppError('Некорректный URL к файлу');
    }
    this.url = url === '' ? null : url;
  }

  get key(): string {
    return this.path + '/' + this.name;
  }

  isImage() {

    const unique = new Set();
    this.imgExtensions.forEach((mime: string[]) => {
      mime.forEach((item: string) => {
        unique.add(item);
      });
    })

    return unique.has(this.extension);
  }

}


