import {FileEntity} from '@/entities/file/model/FileEntity';
import {FolderMeta} from "./FolderMeta.js";
import {AppError} from "@/shared/lib/error/AppError";
import {DirDto, FileDto, FolderMetaDto} from "@/shared/api/fileManager/dto";

export class FolderEntity {
  /**
   *  Имя текущей директории.
   * TODO - там есть какие-то ситуации когда имя пустое, кажется... обработать эти ситуации
   */
  name: string = '';
  /** Путь к текущей директории, включая публичный корень, без имени самой директории */
  path: string = '';
  /** Сервер может вернуть: file, link, dir, block, fifo, char, socket, unknown */
  type: string | null = null;
  /** Количество дочерних директорий */
  countChildDirs: number | null = null;
  /** Количество дочерних файлов */
  countChildFiles: number | null = null;
  /** Метаинформация */
  meta: FolderMeta | null = null;
  /** Сущности файлов в текущей директории */
  files: Map<string, FileEntity> | null = null;
  /** Вложенные директории */
  folders: Map<string, FolderEntity> | null = null;
  /** Счётчик изменений объекта директории. Увеличивается, например, при добавлении данных с сервера. */
  updateCounter = 0;

  constructor(data: DirDto) {
    this.setName(data.name);
    this.setPath(data.path);
    this.setType(data.type);
    this.setCountChildDirs(data.countChildDirs);
    this.setCountChildFiles(data.countChildFiles);
    this.setMeta(data.meta);
    this.fillFolders(data.folders);
    this.fillFiles(data.files);
  }

  /** Устанавливает название директории с предварительной валидацией */
  private setName(name: string | null | undefined): void {
    if (typeof name !== 'string' || name === '') {
      throw new AppError('Некорректное название директории: ' + String(name));
    }
    this.name = name;
  }

  /** Устанавливает путь к директории с предварительной валидацией */
  private setPath(path: string | null | undefined): void {
    // Пустая строка — валидный путь: это родитель корня точки монтирования (виртуальный корень).
    // Сервер намеренно скрывает реальный корень, поэтому '' — штатное значение, а не ошибка.
    if (typeof path !== 'string') {
      throw new AppError('Некорректный путь к директории: ' + String(path));
    }
    this.path = path;
  }

  /** Устанавливает тип директории с предварительной валидацией */
  private setType(type: string | null | undefined) {
    if (typeof type !== 'string' || type !== 'dir') {
      throw new AppError('Некорректный тип директории: ' + String(type));
    }
    // 'dir' - тип у директорий на сервере (в PHP по умолчанию). В приложении FM по умолчанию - 'folder'.
    this.type = 'folder';
  }

  /** Устанавливает количество вложенных директорий с предварительной валидацией */
  private setCountChildDirs(countChildDirs: number | null | undefined) {
    if (typeof countChildDirs !== 'number' || countChildDirs < 0) {
      throw new AppError('Некорректное количество дочерних директорий: ' + String(countChildDirs));
    }
    this.countChildDirs = Number(countChildDirs);
  }

  /** Устанавливает количество вложенных файлов с предварительной валидацией */
  private setCountChildFiles(countChildFiles: number | null | undefined) {
    if (typeof countChildFiles !== 'number' || countChildFiles < 0) {
      throw new AppError('Некорректное количество дочерних файлов: ' + String(countChildFiles));
    }
    this.countChildFiles = Number(countChildFiles);
  }

  /** Устанавливает метаданные директории */
  private setMeta(meta?: FolderMetaDto | null) {
    if (!meta) { // либо просто игнорируем отсутствие меты, либо ставим дефолты
      return;
    }
    this.meta = new FolderMeta(meta);
  }

  /** Устанавливает вложенные директории с предварительной валидацией */
  private setFolders(folders: Map<string, FolderEntity>) {
    // TODO - if (!(typeof response.meta === 'object' && response.meta !== null && !Array.isArray(response.meta))) {
    if (typeof folders !== 'object') {
      throw new AppError('Некорректный тип переменной: ' + String(folders));
    }
    this.folders = folders;
  }

  /** Устанавливает вложенные файлы с предварительной валидацией */
  private setFiles(files: Map<string, FileEntity>) {
    // TODO - if (!(typeof response.meta === 'object' && response.meta !== null && !Array.isArray(response.meta))) {
    if (typeof files !== 'object') {
      throw new AppError('Некорректный тип переменной: ' + String(files));
    }
    this.files = files;
  }

  /** Заполняем данными с сервера, когда файлы и директории представляют собой еще обычные объекты, а не структуры Map() */
  fillFolders(folders: DirDto[] | null | undefined): void {
    if (Array.isArray(folders) && folders.length) {
      const foldersMap = new Map();
      folders.forEach((item: DirDto) => {
        if (typeof item.name !== 'string' || item.name === '') {
          throw new AppError('Некорректное название директории: ' + String(item.name));
        }
        // Пустой path допустим (виртуальный корень) — проверяем только тип.
        if (typeof item.path !== 'string') {
          throw new AppError('Некорректный путь к директории: ' + String(item.path));
        }
        const folder = new FolderEntity(item);
        foldersMap.set(folder.key, folder);
      });
      this.folders = foldersMap;
    }
  }

  /** Заполняем данными с сервера, когда файлы и директории представляют собой еще обычные объекты, а не структуры Map() */
  fillFiles(files: FileDto[] | null | undefined): void {
    if (Array.isArray(files) && files.length) {
      const filesMap = new Map();
      files.forEach((item: FileDto) => {
        if (typeof item.name !== 'string' || item.name === '') {
          throw new AppError('Некорректное название файла: ' + String(item.name));
        }
        // Пустой path допустим (виртуальный/публичный корень) — проверяем только тип.
        if (typeof item.path !== 'string') {
          throw new AppError('Некорректный путь к файлу: ' + String(item.path));
        }
        const file = new FileEntity(item);
        filesMap.set(file.key, file);
      });
      this.files = filesMap;
    }
  }

  /**
   * Корневая директория в состоянии так же должна быть экземпляром Map().
   * Оборачивает текущий объект в Map()
   * @return {Map<String, FolderEntity>}
   */
  asRoot(): Map<string, FolderEntity> {
    const map: Map<string, FolderEntity> = new Map();
    map.set(this.path + '/' + this.name, this);
    return map;
  }

  /**
   * Заполняет директорию новыми данными, полученными с сервера.
   * Увеличивает счётчик модификации объекта директории.
   */
  merge(newFolder: FolderEntity): void {
    Object.assign(this, newFolder);
    this.updateCounter++;
  }

  get key(): string {
    return this.path + '/' + this.name;
  }

}
