// src/shared/ui/resizable-modal/lib/ResizeStrategy.ts

export type ResizeDirection =
  | 'top-left' | 'top-middle' | 'top-right'
  | 'right-middle'
  | 'bottom-right' | 'bottom-middle' | 'bottom-left'
  | 'left-middle';

interface Rect {
  top: number;
  left: number;
  width: number;
  height: number;
}

interface Limits {
  minWidth: number;
  minHeight: number;
  maxWidth: number;
  maxHeight: number;
}

/**
 * Класс, отвечающий только за математику вычисления новых размеров.
 * Чистая логика, без DOM манипуляций.
 */
export class ResizeStrategy {

  static calculate(
    direction: ResizeDirection,
    startRect: Rect,
    deltaX: number,
    deltaY: number,
    limits: Limits
  ): Rect {
    let { top, left, width, height } = startRect;

    // Флаги направления для упрощения логики
    const isTop = direction.includes('top');
    const isBottom = direction.includes('bottom');
    const isLeft = direction.includes('left');
    const isRight = direction.includes('right');

    // 1. Изменение высоты и Top
    if (isTop) {
      const newHeight = Math.max(limits.minHeight, Math.min(startRect.height - deltaY, limits.maxHeight));
      // Корректируем top только если высота реально изменилась
      if (newHeight !== startRect.height) {
        top = startRect.top + (startRect.height - newHeight);
        height = newHeight;
      }
    } else if (isBottom) {
      height = Math.max(limits.minHeight, Math.min(startRect.height + deltaY, limits.maxHeight));
    }

    // 2. Изменение ширины и Left
    if (isLeft) {
      const newWidth = Math.max(limits.minWidth, Math.min(startRect.width - deltaX, limits.maxWidth));
      if (newWidth !== startRect.width) {
        left = startRect.left + (startRect.width - newWidth);
        width = newWidth;
      }
    } else if (isRight) {
      width = Math.max(limits.minWidth, Math.min(startRect.width + deltaX, limits.maxWidth));
    }

    return { top, left, width, height };
  }
}
