import { Observable } from "@/shared/lib/Observable";

export type LogVisibilityState = {
  visible: boolean;
};

export class LogVisibilityStore extends Observable<LogVisibilityState> {
  constructor() {
    super({ visible: false });
  }

  show() {
    this.setState({ visible: true });
  }

  hide() {
    this.setState({ visible: false });
  }

  toggle() {
    this.setState({ visible: !this.getValue().visible });
  }
}
