// src/widgets/file-manager/ui/FileManagerRootWC.ts

// Импорты для сборщика, иначе он веб-компоненты выкидывает на этапе компиляции как используемые только для типизации, а в JS типов нет.
// Если используем декларативный подход с разметкой вместо прямого создания веб-компонентов с помощью конструкции `this.wc = new DummyWC();`
import "@/shared/ui/directory-content-desktop/DirectoryContentWC";
import "@/shared/ui/tree/TreeWC";
import "@/shared/ui/modal/ResizableModalWC";
import "@/shared/ui/openable/DialogWC";
import "@/shared/ui/openable/AlertWC";
import "@/shared/ui/split-panel/SplitPanelWC";
import "@/shared/ui/upload-progress/UploadProgressPanel";
import "@/shared/ui/dropzone/DropzoneWC";
import "@/shared/ui/menu/MenuBarWC";
import "@/shared/ui/context-menu/ContextMenuWC";
import "@/shared/ui/spinner/SpinnerWC";
import "@/shared/ui/toast/ToastWC";
import "@/shared/ui/log/LogWC";
import "@/shared/ui/footer/FooterWC";
import "@/shared/ui/upload-minibar/UploadMinibarWC";

import {ResizableModalWC} from "@/shared/ui/modal/ResizableModalWC";
import {TreeWC} from "@/shared/ui/tree/TreeWC";
import {DirectoryContentWC} from "@/shared/ui/directory-content-desktop/DirectoryContentWC";
import {DialogWC} from "@/shared/ui/openable/DialogWC";
import {AlertWC} from "@/shared/ui/openable/AlertWC";
import {SplitPanelWC} from "@/shared/ui/split-panel/SplitPanelWC";
import {DropzoneWC} from "@/shared/ui/dropzone/DropzoneWC";
import {MenuBarWC} from "@/shared/ui/menu/MenuBarWC";
import {ContextMenuWC} from "@/shared/ui/context-menu/ContextMenuWC";
import {SpinnerWC} from "@/shared/ui/spinner/SpinnerWC";
import {UploadProgressWC} from "@/shared/ui/upload-progress/UploadProgressPanel";
import {ToastWC} from "@/shared/ui/toast/ToastWC";
import {LogWC} from "@/shared/ui/log/LogWC";
import {FooterWC} from "@/shared/ui/footer/FooterWC";
import { UploadMinibarWC } from "@/shared/ui/upload-minibar/UploadMinibarWC";


export class FileManagerRootWC extends HTMLElement {
  // Публичные ссылки на элементы, чтобы Widget мог с ними работать
  public modal!: ResizableModalWC;
  public tree!: TreeWC;
  public content!: DirectoryContentWC;
  public loader!: SpinnerWC;
  public dialog!: DialogWC;
  public alert!: AlertWC;
  public split!: SplitPanelWC;
  public dropZone!: DropzoneWC;
  public menu!: MenuBarWC;
  public contextMenu!: ContextMenuWC;
  public uploadProgress!: UploadProgressWC;
  public toast!: ToastWC;
  public log!: LogWC;
  public footer!: FooterWC;
  public uploadMiniBar!: UploadMinibarWC;

  connectedCallback() {
    if (this.shadowRoot) return;
    const shadow = this.attachShadow({mode: 'open'});

    // Вся структура определяется ЗДЕСЬ, в HTML
    shadow.innerHTML = `
      <style>:host { display: block; }</style>

      <resizable-modal id="modal">
        <div slot="menu-bar">
            <fm-menu-bar id="menu"></fm-menu-bar>
        </div>

        <split-wc id="split">
            <div slot="left" style="height:100%"><tree-wc id="tree"></tree-wc></div>
            <div slot="right" style="height:100%"><dir-content-panel-wc id="content"></dir-content-panel-wc></div>
        </split-wc>

        <div slot="overlays">
            <spinner-wc id="spinner"></spinner-wc>
            <upload-progress-wc id="upload-progress-bar"></upload-progress-wc>
            <dialog-wc id="dialog"></dialog-wc>
            <alert-wc id="alert"></alert-wc>
            <fm-dropzone id="dropzone"></fm-dropzone>
            <fm-toast id="toast"></fm-toast>
            <fm-log id="log"></fm-log>
        </div>
        <div slot="footer"><footer-wc id="footer"></footer-wc></div>
      </resizable-modal>

      <context-menu-wc id="context-menu"></context-menu-wc>
      <upload-minibar id="upload-minibar"></upload-minibar>
    `;

    // Находим элементы и сохраняем ссылки для доступа извне
    this.modal = shadow.getElementById('modal') as ResizableModalWC;
    this.tree = shadow.getElementById('tree') as TreeWC;
    this.content = shadow.getElementById('content') as DirectoryContentWC;
    this.loader = shadow.getElementById('spinner') as SpinnerWC;
    this.dialog = shadow.getElementById('dialog') as DialogWC;
    this.alert = shadow.getElementById('alert') as AlertWC;
    this.split = shadow.getElementById('split') as SplitPanelWC;
    this.dropZone = shadow.getElementById('dropzone') as DropzoneWC;
    this.menu = shadow.getElementById('menu') as MenuBarWC;
    this.contextMenu = shadow.getElementById('context-menu') as ContextMenuWC;
    this.uploadProgress = shadow.getElementById('upload-progress-bar') as UploadProgressWC;
    this.toast = shadow.getElementById('toast') as ToastWC;
    this.log = shadow.getElementById('log') as LogWC;
    this.footer = shadow.getElementById('footer') as FooterWC;
    this.uploadMiniBar = shadow.getElementById('upload-minibar') as UploadMinibarWC;

  }
}

customElements.define('fm-root', FileManagerRootWC);
