/**
 * Контракт на данные, передаваемые для создания пункта меню.
 */
export interface MenuItemData {
  action?: string; // Обязателен, если не separator
  label?: string;  // Обязателен, если не separator
  enabled?: boolean;
  separator?: boolean;
}

/**
 * Полноценная сущность пункта контекстного меню.
 * Инкапсулирует валидацию данных и логику рендеринга.
 */
export class ContextMenuItem {

  // Внутреннее, проверенное состояние
  private readonly data: MenuItemData;

  /**
   * Приватный конструктор. Создание экземпляра должно происходить
   * через статический фабричный метод ContextMenuItem.create().
   * @param data - Валидные данные пункта меню.
   */
  private constructor(data: MenuItemData) {
    this.data = data;
  }

  /**
   * Статический фабричный метод. Выполняет валидацию и создает новый экземпляр.
   * @param data - Данные, полученные извне (например, из JSON).
   */
  public static create(data: unknown): ContextMenuItem {
    if (typeof data !== 'object' || data === null) {
      throw new Error('ContextMenuItem: Item data must be an object.');
    }

    const item = data as MenuItemData;

    // 1. Валидация для разделителя
    if (item.separator) {
      if (item.separator !== true) {
        throw new Error(`ContextMenuItem: Invalid separator value.`);
      }
      return new ContextMenuItem(item);
    }

    // 2. Валидация для обычного пункта меню
    const hasAction = typeof item.action === 'string' && item.action.length > 0;
    const hasLabel = typeof item.label === 'string';

    if (!hasAction || !hasLabel) {
      throw new Error(`ContextMenuItem: Menu item must have 'action' (string) and 'label' (string). Received: ${JSON.stringify(item)}`);
    }

    return new ContextMenuItem(item);
  }

  /**
   * Создает и возвращает готовый к вставке HTMLLIElement.
   */
  public render(): HTMLLIElement {
    const el = document.createElement('li');
    const item = this.data;

    // 1) Разделитель
    if (item.separator) {
      el.classList.add('separator');
      el.setAttribute('role', 'separator');
      return el;
    }

    // 2) Обычный пункт меню.
    // Используем явное приведение (!), так как валидация в create гарантирует их наличие
    el.dataset.action = item.action!;
    el.textContent = item.label!;

    // 3) Поддержка disabled
    if (item.enabled === false) {
      el.classList.add('disabled');
      el.setAttribute('aria-disabled', 'true');
    }

    return el;
  }
}
