// src/shared/lib/Observable.ts

export type Unsubscriber = () => void;
export type Listener<T> = (state: T) => void;

/**
 * Интерфейс, описывающий минимальный реактивный объект (Store).
 * T - тип данных, которые хранит и уведомляет Store.
 */
export interface IObservable<T> {
  /**
   * Подписаться на изменения.
   * @param listener - функция, вызываемая при изменении состояния.
   * @returns функция для отписки.
   */
  subscribe(listener: (state: T) => void): Unsubscriber;

  /**
   * Получить текущее значение (синхронно).
   */
  getValue(): T;
}

/**
 * Базовая реализация Store, которую могут расширять другие фичи.
 */
export class Observable<T> implements IObservable<T> {
  protected listeners = new Set<Listener<T>>();

  constructor(protected state: T) {}

  public getValue(): T {
    return this.state;
  }

  protected setState(newState: T): void {
    this.state = newState;
    this.notify();
  }

  public subscribe(listener: (state: T) => void): Unsubscriber {
    this.listeners.add(listener);
    // Инициализация UI: вызываем слушателя с текущим состоянием
    listener(this.state);
    return () => this.listeners.delete(listener);
  }

  protected notify() {
    this.listeners.forEach(listener => listener(this.state));
  }
}


/**
 * Класс, который автоматически обновляется при изменении исходного Observable.
 * Аналог computed в Vue или selector в Redux.
 */
export class MappedObservable<T, R> extends Observable<R> {
  private sourceUnsub: Unsubscriber;

  constructor(source: IObservable<T>, mapper: (val: T) => R) {
    // Инициализируем начальным значением
    super(mapper(source.getValue()));

    // Подписываемся на источник
    this.sourceUnsub = source.subscribe((newVal) => {
      const mappedVal = mapper(newVal);
      // Если значение изменилось — уведомляем подписчиков
      if (mappedVal !== this.getValue()) {
        this.setState(mappedVal);
      }
    });
  }

  // Метод для очистки, если потребуется уничтожать сторы
  destroy() {
    this.sourceUnsub();
  }
}
