import {HttpClient} from '@/api/HttpClient';
import type {SnippetTreeDto} from '@/api/dto';

/**
 * Порт источника сниппетов. Единая точка выбора реализации (по аналогии с
 * `IFileManagerBackend` в filemanager-core): интеграция может подменить бэкенд, не трогая пикер.
 */
export interface ISnippetBackend {
  /** Загрузить дерево сниппетов. */
  fetchTree(): Promise<SnippetTreeDto>;
}

/** HTTP-реализация порта по умолчанию: тянет дерево одним GET-запросом. */
export class HttpSnippetBackend implements ISnippetBackend {
  constructor(private readonly http: HttpClient) {
  }

  fetchTree(): Promise<SnippetTreeDto> {
    return this.http.get<SnippetTreeDto>();
  }
}
