// src/app/createApp.ts
import {HttpClient} from '@/shared/api/httpClient';
import {HttpFileManagerBackend} from '@/shared/api/fileManager/httpBackend';
import {AppRuntime} from '@/app/AppRuntime';
import type {AppConfig} from '@/app/AppConfig';
import type {IFileManagerBackend} from '@/shared/api/fileManager/ports';

/**
 * Публичный API для создания рантайма файлового менеджера.
 *
 * НИЧЕГО не знает про CKEditor5.
 * На вход принимает чистый конфиг, на выход — чистый рантайм.
 * Теперь у тебя есть единая точка входа, которую можно использовать где угодно — в плагине, standalone-странице, тестах и т.д.
 */
export function createApp(config: AppConfig & { backend?: IFileManagerBackend }): AppRuntime {

  const backend: IFileManagerBackend =
    config.backend ??
    new HttpFileManagerBackend(
      // Дефолтный REST API HTTP-бекенд
      new HttpClient({
        baseUrl: config.fmConnector,  // например: '/api/file-manager'
        headers: config.fmHeaders,
      }),
    );

  return new AppRuntime(config, {backend});
}

// При желании можно также реэкспортнуть типы:
export type {AppConfig} from '@/app/AppConfig';
export {AppRuntime} from '@/app/AppRuntime';
