// src/shared/ui/dropzone/DropzoneWC.ts

import { DndArea } from '../dnd/DndArea';

import styles from './scss/dropzone.scss';

const sheet = new CSSStyleSheet();
sheet.replaceSync(styles);

export class DropzoneWC extends HTMLElement {
  private fileInput!: HTMLInputElement;
  private dndArea?: DndArea;
  private wrapper!: HTMLElement;

  connectedCallback() {
    if (this.shadowRoot) return;

    const shadow = this.attachShadow({ mode: 'open' });
    shadow.adoptedStyleSheets = [sheet];

    // --
    // Layout-критичные стили хоста дублируем инлайном.
    // В контексте CKEditor/страницы внешние CSS-правила перебивают :host для
    // display/position (нормальные объявления внешнего дерева приоритетнее :host),
    // из-за чего дропзона рендерится в потоке и видна при старте. Инлайн-стиль
    // имеет высший приоритет и гарантирует оверлей и скрытие по умолчанию.
    // Остальное оформление (фон, blur, центрирование, .dropzone-card) — в scss.
    // --
    // Это замечание и исправление ИИ, работает, но все равно криво: раньше дропзона располагалась по-другому. 
    // TODO В общем, временно закостылено, позже разобраться
    this.style.cssText = 'position: absolute; inset: 0; z-index: 1500; display: none;';

    // Обертка самой карточки дропзоны
    this.wrapper = document.createElement('div');
    this.wrapper.className = 'dropzone-card';

    // Кнопка закрытия (крестик)
    const closeBtn = document.createElement('button');
    closeBtn.className = 'close-btn';
    closeBtn.title = 'Закрыть (Esc)';

    const message = document.createElement('div');
    message.className = 'drop-message';
    message.innerHTML = !window.FileReader
      ? 'File API не поддерживается'
      : '<b>Перетащите файлы сюда</b><br><small>или нажмите для выбора</small>';

    this.fileInput = document.createElement('input');
    this.fileInput.type = 'file';
    this.fileInput.multiple = true;
    this.fileInput.style.display = 'none';

    this.wrapper.appendChild(closeBtn);
    this.wrapper.appendChild(message);
    shadow.appendChild(this.wrapper);
    shadow.appendChild(this.fileInput);

    // --- ОБРАБОТЧИКИ СОБЫТИЙ ---

    // 1. Клик по карточке → выбор файла
    this.wrapper.addEventListener('click', (e) => {
      // Если нажали именно на крестик, не открываем диалог выбора файла
      if ((e.target as HTMLElement).classList.contains('close-btn')) return;
      this.fileInput.click();
    });

    // 2. Клик по фону (вне карточки) → закрыть
    this.addEventListener('click', (e) => {
      if (e.composedPath()[0] === this) {
        this.hide();
      }
    });

    // 3. Нажатие Esc
    this._onKeyDown = this._onKeyDown.bind(this);

    // 4. Кнопка закрытия
    closeBtn.addEventListener('click', (e) => {
      e.stopPropagation(); // Обязательно! Чтобы клик не ушел на wrapper (выбор файла)
      this.hide();
    });

    this.fileInput.addEventListener('change', (e) => this.handleFileInput(e));

    this.dndArea = new DndArea({
      host: this,
      onDragStateChange: (isOver) => {
        if (isOver) this.setAttribute('dragover', '');
        else this.removeAttribute('dragover');
      },
      onDropFiles: (files) => {
        this.emitFiles(files);
        this.hide(); // Закрываем после дропа
      },
    });
  }

  private _onKeyDown(e: KeyboardEvent) {
    if (e.key === 'Escape') this.hide();
  }

  // Публичные методы управления
  public show() {
    // this.classList.add('active');
    this.style.display = 'flex'
    window.addEventListener('keydown', this._onKeyDown);
  }

  public hide() {
    // this.classList.remove('active');
    this.style.display = 'none';
    window.removeEventListener('keydown', this._onKeyDown);
    this.fileInput.value = '';
  }

  disconnectedCallback() {
    this.dndArea?.destroy();
    window.removeEventListener('keydown', this._onKeyDown);
  }

  private handleFileInput(e: Event) {
    const input = e.target as HTMLInputElement;
    if (input.files?.length) {
      try {
        this.emitFiles(input.files);
      } catch (err) {
        console.error("Ошибка при отправке файлов:", err);
      } finally {
        this.hide(); // Гарантированно скрываем дропзону
      }
      input.value = '';
    }
  }

  private emitFiles(files: FileList) {
    this.dispatchEvent(
      new CustomEvent<FileList>('dropzone:files', {
        detail: files,
        bubbles: true,
        composed: true,
      }),
    );
  }
}

customElements.define('fm-dropzone', DropzoneWC);
