import type {IFileManagerBackend} from '@/shared/api/fileManager/ports';
import {DiagnosticService} from "@/shared/lib/diagnostics/DiagnosticService";
import {AppError} from "@/shared/lib/error/AppError";
import {mapDeleteResponse} from "@/features/delete/model/delete.mapper";
import {DeleteResult} from "@/features/delete/model/DeleteResult";

export class DeleteService {
  constructor(
    private readonly backend: IFileManagerBackend,
    private diagnostics: DiagnosticService,
  ) {
  }

  async deleteFiles(paths: string[]): Promise<DeleteResult> {
    try {
      const dto =  await this.backend.delete({paths});
      const result = mapDeleteResponse(dto);
      if (result.failed.length > 0) {
        this.diagnostics.warning(
          `Удалено ${result.deleted.length} из ${paths.length}`,
          { source: 'delete', details: result.failed }
        );
      }
      return result;
    } catch (e) {
      this.handleError(e);
      throw e;
    }
  }

  private handleError(e: unknown) {
    if (e instanceof AppError) {
      this.diagnostics.emit(
        e.level,
        e.message,
        {source: e.source, details: e}
      );
    } else {
      this.diagnostics.error(
        'Неизвестная ошибка при удалении файлов',
        {source: 'delete', details: e}
      );
    }
  }
}
