import type {FileManagerEventBus} from '@/shared/lib/EventBus';
import type {DirClickDetail, DirContextMenuDetail, TreeWC} from '@/shared/ui/tree/TreeWC';
import {DndArea} from '@/shared/ui/dnd/DndArea';
import {FolderRegistry} from "@/entities/folder/model/FolderRegistry";
import {IObservable} from "@/shared/lib/Observable";
import {FolderEntity} from "@/entities/folder/model/FolderEntity";
import {IFeature} from "@/shared/lib/Feature";

export class FileTreeFeature implements IFeature {
  private unsubs: (() => void)[] = [];
  private dndArea?: DndArea;

  constructor(
    private readonly bus: FileManagerEventBus,
    private tree: TreeWC,
    private registry: FolderRegistry,
    private navState: IObservable<string>,
  ) {
  }

  init() {

    // GEMINI ///////////////////
    // 1. Подписка на изменение данных в кэше (Registry)
    this.unsubs.push(
      this.registry.subscribe((rootFoldersMap) => {
        const rootFolder = this.combineRootFolders(rootFoldersMap);
        if (rootFolder) {
          this.tree.setTreeData(rootFolder);
        }
      })
    );

    // 2. Подписка на изменение пути
    this.unsubs.push(
      this.navState.subscribe((currentPath) => {
        this.tree.highlightPath(currentPath); // Обновляем подсветку
      })
    );

    /////////////////////

    // 1. Мост: клик по папке в дереве → nav:openDir + закрыть контекстное меню дерева
    const onDirClick = (e: Event) => {
      const ev = e as CustomEvent<DirClickDetail>;
      if (!ev.detail?.key) return;

      this.bus.emit('nav:openDir', ev.detail.key);
      this.bus.emit('tree:folder:rmc',);
    };

    // 2. Мост: контекстное меню по папке → например, открыть меню
    const onDirContextMenu = (e: Event) => {
      const ev = e as CustomEvent<DirContextMenuDetail>;
      const {key, path, event} = ev.detail;

      if (!path) {
        return;
      }

      const set = new Set<{ type: 'folder' | 'file'; key: string }>();
      set.add({type: 'folder', key: path});
      this.bus.emit('selection:change', set);


      this.bus.emit('contextmenu:open', {
        event,
        target: {type: 'folder', key, path: path ?? undefined,},
        scope: 'tree',
      });
    };

    // 3. Клик по “фону” дерева → просто закрыть контекстное меню дерева
    const onTreeClick = () => {
      this.bus.emit('tree:rmc',);
    };

    this.tree.addEventListener('dir-click', onDirClick as EventListener);
    this.tree.addEventListener('dir-contextmenu', onDirContextMenu as EventListener);
    this.tree.addEventListener('tree-click', onTreeClick as EventListener);

    this.unsubs.push(() => {
      this.tree.removeEventListener('dir-click', onDirClick as EventListener);
      this.tree.removeEventListener('dir-contextmenu', onDirContextMenu as EventListener);
      this.tree.removeEventListener('tree-click', onTreeClick as EventListener);
    });

    this.dndArea = new DndArea({
      host: this.tree,
      onDropFiles: (files, e) => {
        const folderPath = this.resolveFolderUnderCursor(e);
        this.bus.emit('upload:drop', {path: folderPath, files});
      },
    });
  }

  // Допустим, это логика для сбора корней в один объект
  private combineRootFolders(map: Map<string, FolderEntity>): FolderEntity | undefined {
    // Логика собирающая все загруженные корневые папки
    // в один "виртуальный" рут, который TreeWC умеет рисовать.
    // ...
    return map.values().next().value; // заглушка для первого корня
  }

  private resolveFolderUnderCursor(e: DragEvent): string | undefined {
    // здесь можно по event.target / координатам понять,
    // на какой узел дерева бросили файлы
    return undefined;
  }


  /** TODO - Очистить всё содержимое дерева */
  clean() {
  }

  /** TODO - Выделить элемент дерева у которого путь равен переданному */
  select(path: string) {
  }

  /** TODO - Снять выделение со всех элементов дерева */
  unselect() {
  }


  destroy() {
    this.dndArea?.destroy();
    this.unsubs.forEach(unsub => unsub());
  }

}
