import type {IObservable} from "@/shared/lib/Observable";

import styles from './scss/menu-bar.scss';

const sheet = new CSSStyleSheet();
sheet.replaceSync(styles);

export interface MenuBarItem {
  id: string;
  label?: string | IObservable<string>;
  icon?: string | IObservable<string>; // SVG string or url
  action: () => void;
  isActive?: IObservable<boolean>;// Опционально: Observable, чтобы кнопка знала, активна ли она (для подсветки текущего режима)
  isDisabled?: IObservable<boolean>;// Опционально: Observable, чтобы дизейблить кнопку (например, "Вставить", если буфер пуст)
}

export class MenuBarWC extends HTMLElement {
  private items: MenuBarItem[] = [];
  private _unsubs: Array<() => void> = [];
  private container: HTMLDivElement | null = null;

  constructor() {
    super();
    // Инициализируем Shadow DOM сразу в конструкторе
    const shadow = this.attachShadow({mode: 'open'});
    shadow.adoptedStyleSheets = [sheet];
  }

  public setItems(items: MenuBarItem[]) {
    // Отписываемся от старых данных перед перерисовкой
    this.cleanup();
    this.items = items;
    this.render();
  }

  private cleanup() {
    this._unsubs.forEach(unsub => unsub());
    this._unsubs = [];
  }

  connectedCallback() {
    // Если setItems был вызван до добавления в DOM, render уже случился
    if (!this.shadowRoot?.querySelector('.fm-menu-bar-container')) {
      this.render();
    }
  }

  disconnectedCallback() {
    this.cleanup();
  }

  private render() {
    if (!this.shadowRoot) return;

    // Очищаем Shadow DOM
    this.shadowRoot.innerHTML = '';

    this.container = document.createElement('div');
    this.container.className = 'fm-menu-bar-container'; // Стилизуйте flex/gap

    this.items.forEach(item => {

      if (!item.icon && !item.label) {
        return
      }

      const btn = document.createElement('button');
      btn.className = 'fm-menu-btn';

      // --- ЛОГИКА ИКОНКИ ---
      if (item.icon) {

        // Создаем контейнер для иконки внутри кнопки
        const iconSpan = document.createElement('span');
        iconSpan.className = 'fm-menu-btn-icon';
        btn.appendChild(iconSpan);

        if (typeof item.icon === 'string') {
          iconSpan.innerHTML = item.icon; // Если строка — вставляем сразу
        } else {
          // Если Observable — подписываемся на изменения
          const unsub = item.icon.subscribe(svg => iconSpan.innerHTML = svg);
          this._unsubs.push(unsub);
        }
      }

      // --- ЛОГИКА ТЕКСТА ---
      if (item.label) {

        // Создаем контейнер для текста
        const labelSpan = document.createElement('span');
        labelSpan.className = 'fm-menu-btn-label';
        btn.appendChild(labelSpan);

        if (typeof item.label === 'string') {
          labelSpan.textContent = item.label;
        } else {
          const unsub = item.label.subscribe(text => labelSpan.textContent = text);
          this._unsubs.push(unsub);
        }
      }

      // Реактивность: Активное состояние (например, подсветить "Плитка")
      if (item.isActive) {
        const unsub = item.isActive.subscribe(active => {
          // Теперь ESLint доволен, так как это явный блок условий
          if (active) {
            btn.classList.add('active');
          } else {
            btn.classList.remove('active');
          }
        });
        this._unsubs.push(unsub);
      }

      // Реактивность: Disabled (например, кнопка "Удалить")
      if (item.isDisabled) {
        const unsub = item.isDisabled.subscribe(disabled => {
          btn.disabled = disabled;
        });
        this._unsubs.push(unsub);
      }

      // Клик -> вызываем action из конфига
      btn.onclick = (e) => {
        e.preventDefault();
        item.action();
      };

      this.container?.appendChild(btn);
    });

    this.shadowRoot.appendChild(this.container);
  }
}

customElements.define('fm-menu-bar', MenuBarWC);
