// src/shared/ui/dnd/DndArea.ts

export type DndAreaOptions = {
  host: HTMLElement;
  onlyFiles?: boolean; // принимать только файлы (по умолчанию true)
  onDragStateChange?: (isOver: boolean, e: DragEvent) => void;// true/false, когда ховер внутри/снаружи (для подсветки)
  onDropFiles: (files: FileList, e: DragEvent) => void;// собственно drop файлов
};

export class DndArea {
  private overCounter = 0;
  private readonly host: HTMLElement;
  private readonly opts: {
    onlyFiles: boolean;
    onDropFiles: (files: FileList, e: DragEvent) => void;
    onDragStateChange?: (isOver: boolean, e: DragEvent) => void;
  };


  constructor(options: DndAreaOptions) {
    this.host = options.host;
    this.opts = {
      onlyFiles: options.onlyFiles ?? true,
      onDropFiles: options.onDropFiles,
      onDragStateChange: options.onDragStateChange,
    };
    this.attach();
  }

  private attach() {
    this.host.addEventListener('dragenter', this.handleDragEnter);
    this.host.addEventListener('dragover', this.handleDragOver);
    this.host.addEventListener('dragleave', this.handleDragLeave);
    this.host.addEventListener('drop', this.handleDrop);
  }

  destroy() {
    this.host.removeEventListener('dragenter', this.handleDragEnter);
    this.host.removeEventListener('dragover', this.handleDragOver);
    this.host.removeEventListener('dragleave', this.handleDragLeave);
    this.host.removeEventListener('drop', this.handleDrop);
  }

  private isFileDrag(e: DragEvent): boolean {
    const dt = e.dataTransfer;
    if (!dt) return false;
    if (dt.files && dt.files.length > 0) return true;
    return Array.from(dt.types).includes('Files');
  }

  private handleDragEnter = (e: DragEvent) => {
    if (this.opts.onlyFiles && !this.isFileDrag(e)) return;
    e.preventDefault();
    this.overCounter++;
    if (this.overCounter === 1 && this.opts.onDragStateChange) {
      this.opts.onDragStateChange(true, e);
    }
  };

  private handleDragOver = (e: DragEvent) => {
    if (this.opts.onlyFiles && !this.isFileDrag(e)) return;
    e.preventDefault();
    if (e.dataTransfer) {
      // @see https://developer.mozilla.org/en-US/docs/Web/API/DataTransfer/dropEffect
      e.dataTransfer.dropEffect = 'copy';
    }
  };

  private handleDragLeave = (e: DragEvent) => {
    if (this.opts.onlyFiles && !this.isFileDrag(e)) return;
    e.preventDefault();
    this.overCounter = Math.max(0, this.overCounter - 1);
    if (this.overCounter === 0 && this.opts.onDragStateChange) {
      this.opts.onDragStateChange(false, e);
    }
  };

  private handleDrop = (e: DragEvent) => {
    if (this.opts.onlyFiles && !this.isFileDrag(e)) return;
    e.preventDefault();
    const files = e.dataTransfer?.files;
    this.overCounter = 0;
    if (this.opts.onDragStateChange) {
      this.opts.onDragStateChange(false, e);
    }
    if (files && files.length) {
      this.opts.onDropFiles(files, e);
    }
  };
}
