// src/entities/file/lib/FileAnalysisService.ts

import {FILE_SIGNATURES} from './file-signatures';
import {DiagnosticService} from "@/shared/lib/diagnostics/DiagnosticService";

export type AnalysisResult = {
  isValid: boolean;
  detectedMime: string | 'unknown';
  originalMime: string;
  fileName: string;
};

export class FileAnalysisService {

  constructor(private diagnostics: DiagnosticService,) {}

  /**
   * Проверяет, соответствует ли расширение (MIME от браузера) реальному содержимому.
   * Проверяет только известные сигнатуры. Если сигнатура неизвестна — считает файл валидным.
   */
  public async validateFile(file: File): Promise<AnalysisResult> {
    const browserMime = file.type;
    // Читаем первые 4 байта (или больше, если расширите сигнатуры)
    const magicNumber = await this.getMagicNumber(file, 0, 4);
    const detectedMime = FILE_SIGNATURES[magicNumber.toLowerCase()];

    // Если мы не знаем такую сигнатуру, пропускаем файл (считаем валидным,
    // так как не можем доказать обратное без полной базы сигнатур)
    if (!detectedMime) {
      return {isValid: true, detectedMime: 'unknown', originalMime: browserMime, fileName: file.name};
    }

    // Особый случай для ZIP-контейнеров (docx, xlsx, apk и т.д. имеют одну сигнатуру)
    if (detectedMime === 'application/zip') {
      // Здесь можно добавить углубленную проверку, но пока считаем,
      // что если это zip и браузер говорит zip/docx/xlsx — это ок.
      // Для простоты: если определили как zip, а файл не картинка — пропускаем.
      return {isValid: true, detectedMime, originalMime: browserMime, fileName: file.name};
    }

    // Если сигнатура найдена, она должна совпадать с типом файла
    // Упрощенная проверка: совпадает ли основная часть (image/png === image/png)
    // В продакшене лучше проверять массив допустимых mime для этой сигнатуры.
    const isValid = browserMime === detectedMime;

    if (!isValid) {
      this.diagnostics.warning(
        `Файл "${file.name}" имеет несовпадающий MIME-тип`,
        {
          source: 'upload:analysis',
          details: {detectedMime, browserMime}
        }
      );
    }

    return {
      isValid,
      detectedMime,
      originalMime: browserMime,
      fileName: file.name
    };
  }

  /**
   * Получает "магическое число" в виде HEX-строки
   */
  public async getMagicNumber(file: File, offset: number = 0, length: number = 4): Promise<string> {
    const chunk = file.slice(offset, offset + length);
    const buffer = await chunk.arrayBuffer();
    const uint8 = new Uint8Array(buffer);

    return Array.from(uint8)
      .map(byte => byte.toString(16).padStart(2, '0'))
      .join('');
  }

  /**
   * Генерирует HEX-дамп для превью (для фичи Properties)
   * Возвращает первые N байт в формате: Offset | Hex | ASCII
   */
  public async getHexDump(file: File, length: number = 64): Promise<string> {
    const chunk = file.slice(0, length);
    const buffer = await chunk.arrayBuffer();
    const view = new DataView(buffer);
    let output = '';

    for (let i = 0; i < view.byteLength; i += 16) {
      // Offset
      output += i.toString(16).padStart(8, '0') + '  ';

      // Hex part
      let hexPart = '';
      let asciiPart = '';

      for (let j = 0; j < 16; j++) {
        if (i + j < view.byteLength) {
          const byte = view.getUint8(i + j);
          hexPart += byte.toString(16).padStart(2, '0') + ' ';
          // ASCII (только печатные символы)
          asciiPart += (byte >= 32 && byte <= 126) ? String.fromCharCode(byte) : '.';
        } else {
          hexPart += '   ';
        }
        if (j === 7) hexPart += ' '; // Разделитель посередине
      }

      output += hexPart + ' |' + asciiPart + '|\n';
    }

    return output;
  }
}
