import type {FileManagerEventBus} from '@/shared/lib/EventBus';
import {RenameService} from "./RenameService";
import type {IFileManagerBackend} from "@/shared/api/fileManager/ports";
import {ModalService} from "@/features/modal/model/ModalService";
import {AppError} from "@/shared/lib/error/AppError";
import {SelectionState} from "@/features/selection/model/SelectionStore";
import {IObservable} from "@/shared/lib/Observable";
import {FolderRegistry} from "@/entities/folder/model/FolderRegistry";
import {IFeature} from "@/shared/lib/Feature";

export class RenameFeature  implements IFeature{
  private service: RenameService;
  private unsubs: (() => void)[] = [];

  constructor(
    private readonly bus: FileManagerEventBus,
    private modalService: ModalService,
    backend: IFileManagerBackend,
    private selectionState: IObservable<SelectionState>,
    private registry: FolderRegistry,
    private navState: IObservable<string>,
  ) {
    this.service = new RenameService(backend);
  }

  init() {
    this.unsubs.push(
      this.bus.on('rename:start', async () => {
        const selection: SelectionState = this.selectionState.getValue();

        if (!['single-folder', 'multiple-folders', 'single-file', 'multiple-files', 'mixed'].includes(selection.type)) {
          throw new AppError('Данное действие недоступно');
        }

        if (selection.type === 'single-file') {
          const file = this.registry.getFileEntity([...selection.files][0]);
          if(!file){
            throw new AppError('Файл не найден');
          }
          const newName = await this.modalService.openRenameDialog('Новое имя файла', file.name);
          if (newName && newName !== file.name) {
            const res = await this.service.rename(this.navState.getValue(), file.name, newName);
            // TODO - В ответе сервера должен быть статус операции, а не содержимое текущей директории
            // Говорим всем: "данные изменились, обновитесь кто хочет"
            this.bus.emit('nav:refresh', res.path);
            this.bus.emit('rename:complete', this.navState.getValue());
          } else {
          // alert('Новое имя должно отличаться от старого');
          }
        } else if (selection.type === 'multiple-files') {
          //
        } else if (selection.type === 'single-folder') {
          const folder = this.registry.getFolderByPath([...selection.folders][0]);
          if(!folder){
            throw new AppError('Директория не найдена ');
          }
          const newName = await this.modalService.openRenameDialog('Новое имя папки', folder.name);
          if (newName && newName !== folder.name) {
            const res = await this.service.rename(this.navState.getValue(), folder.name, newName);
            // TODO - В ответе сервера должен быть статус операции, а не содержимое текущей директории
            // Говорим всем: "данные изменились, обновитесь кто хочет"
            this.bus.emit('nav:refresh', res.path);
            this.bus.emit('rename:complete', this.navState.getValue());
          } else {
            // alert('Новое имя должно отличаться от старого');
          }
        } else if (selection.type === 'multiple-folders') {
          //
        } else if (selection.type === 'mixed') {
          // Переименование смешанного выделения пока недоступно (есть ли вообще в этом смысл?)
        } else if (selection.type === 'empty') {
          // Если выделение пустое, то переименовываем текущую директорию
        }
      }),
    );
  }

  destroy() {
    this.unsubs.forEach(unsub => unsub());
  }

}
