// src/entities/folder/model/FolderRegistry.ts
import {Observable} from "@/shared/lib/Observable";
import {FolderEntity} from "./FolderEntity";
import {FileEntity} from "@/entities/file/model/FileEntity";

// Простая реализация Observable (чтобы не тянуть RxJS)
type Listener = (root: Map<string, FolderEntity>) => void;

// Map<string, FolderEntity> — это наш тип T
export class FolderRegistry extends Observable<Map<string, FolderEntity>> {

  // Храним корни, как и раньше
  private roots: Map<string, FolderEntity> = new Map();

  constructor() {
    // Инициализируем родительский класс с начальным состоянием
    super(new Map<string, FolderEntity>());

    // Инициализируем локальную переменную roots (для удобства работы в методах)
    this.roots = this.getValue(); // В Observable состояние protected state
  }

  // 1. Получить данные (синхронно)
  public getRoots(): Map<string, FolderEntity> {
    // Получаем текущее состояние из родительского класса
    return this.getValue();
  }

  /** === ПОИСК ДИРЕКТОРИЙ === */

  // 2. Найти папку по пути (Ваша логика рекурсивного поиска)
  public getFolderByPath(path: string): FolderEntity | null {
    // Теперь мы используем getRoots() для получения текущего состояния
    const roots = this.getRoots();
    if (roots.has(path)) return roots.get(path)!;

    // Рекурсивный поиск
    for (const [, rootFolder] of roots) {
      const found = this.findRecursive(path, rootFolder);
      if (found) return found;
    }
    return null;
  }

  private findRecursive(path: string, parent: FolderEntity): FolderEntity | null {
    if (parent.folders?.has(path)) return parent.folders.get(path)!;

    if (parent.folders) {
      for (const [, child] of parent.folders) {
        const found = this.findRecursive(path, child);
        if (found) return found;
      }
    }
    return null;
  }

  /**
   * === ПОИСК ФАЙЛОВ ===
   * Чтобы не делать полный перебор всего дерева (что медленно), мы используем хитрость:
   * файл всегда лежит в папке. Если у нас есть `key` файла (например, `/var/www/image.png`),
   * мы можем найти папку, содержащую файл, и забрать файл оттуда.
   */

  /**
   * Ищет файл во всем загруженном дереве директорий.
   * Использует рекурсивный поиск, аналогичный поиску папок.
   */
  public getFileEntity(key: string): FileEntity | null {
    const roots = this.getRoots();

    // 1. Сначала ищем в файлах корневых директорий (если они там есть)
    for (const rootFolder of roots.values()) {
      if (rootFolder.files?.has(key)) {
        return rootFolder.files.get(key)!;
      }

      // 2. Если нет, запускаем рекурсию
      const found = this.findFileRecursive(key, rootFolder);
      if (found) return found;
    }
    return null;
  }

  // Приватный рекурсивный метод
  private findFileRecursive(key: string, parent: FolderEntity): FileEntity | null {
    // Проверяем файлы в текущей папке
    if (parent.files?.has(key)) {
      return parent.files.get(key)!;
    }

    // Если нет, спускаемся в подпапки
    if (parent.folders) {
      for (const child of parent.folders.values()) {
        const found = this.findFileRecursive(key, child);
        if (found) return found;
      }
    }
    return null;
  }

  // 3. Обновить данные (Merge или Init)
  public upsertFolder(path: string, newFolder: FolderEntity) {
    // В этом методе мы должны оперировать состоянием, полученным через getValue()
    const roots = this.getValue();
    const existing = this.getFolderByPath(path);

    if (existing) {
      // Если папка уже есть — мержим (обновляем содержимое)
      existing.merge(newFolder);
    } else {
      // Если это корень или новая папка
      if (this.roots.size === 0 || !path.includes('/')) {
        // Заменяем текущий Map на новый или добавляем корень
        roots.set(newFolder.key, newFolder);
      } else {
        // Тут логика вставки, если родитель найден, но самой папки еще нет
        // Для упрощения, допустим, мы всегда мержим в существующую структуру
        // Если родителя нет — это ошибка логики загрузки
      }
    }
    // ВАЖНО: Уведомляем всех подписчиков, передавая текущий Map (roots).
    // Используем setState() родительского класса, который вызовет notify().
    this.setState(roots);
  }

}
