// src/features/toast/ToastFeature.ts

import type { FileManagerEventBus } from '@/shared/lib/EventBus';
import type { DiagnosticEvent } from '@/shared/lib/diagnostics/DiagnosticEvent';
import type { ToastWC } from '@/shared/ui/toast/ToastWC';
import { IFeature } from '@/shared/lib/Feature';

export class ToastFeature implements IFeature {
  constructor(
    private readonly bus: FileManagerEventBus,
    private readonly toast: ToastWC
  ) {}

  init() {
    this.bus.on('diagnostic:notify', this.onNotify);
  }

  destroy() {
    this.bus.off('diagnostic:notify', this.onNotify);
  }

  private onNotify = (event: DiagnosticEvent) => {
    this.toast.showToast(
      {
        id: event.id,
        message: event.message,
        level: event.level,
      },
      this.getDuration(event.level)
    );
  };

  private getDuration(level: DiagnosticEvent['level']) {
    switch (level) {
      case 'error': return 5000;
      case 'warning': return 4000;
      case 'notice': return 2500;
    }
  }
}
