// shared/lib/diagnostics/DiagnosticService.ts
import {DiagnosticEvent, DiagnosticLevel} from './DiagnosticEvent';
import {FileManagerEventBus} from "@/shared/lib/EventBus";
import {DiagnosticStore} from "@/shared/lib/diagnostics/DiagnosticStore";

/**
 * DiagnosticService — единая точка входа
 * Это главное. Именно сюда “выбрасываются” события откуда угодно.
 * 📌 Важно:
 *    - никакого UI внутри
 *    - только сбор и маршрутизация
 *
 * Как выбрасывать события “откуда угодно”?
 * В сервисах:
 *```
 * constructor(
 *   private diagnostics: DiagnosticService
 * ) {}
 *
 * async createFolder(...) {
 *   try {
 *     ...
 *   } catch (e) {
 *     this.diagnostics.error(
 *       'Не удалось создать папку',
 *       { source: 'create:folder', details: e }
 *     );
 *     throw e;
 *   }
 * }
 *```
 */
export class DiagnosticService {
  constructor(
    private readonly store: DiagnosticStore,
    private readonly bus?: FileManagerEventBus
  ) {
  }

  emit(
    level: DiagnosticLevel,
    message: string,
    options?: Partial<Omit<DiagnosticEvent, 'id' | 'level' | 'message' | 'timestamp'>>
  ) {
    const event: DiagnosticEvent = {
      id: this.generateId(),
      level,
      message,
      timestamp: Date.now(),
      userVisible: true,
      persist: true,
      ...options,
    };

    this.store.add(event);

    if (event.userVisible) {
      this.bus?.emit('diagnostic:notify', event);
    }
  }

  /**
   * Критерий: пользователь ожидал результат, но он не получен
   * ❌ error
   *    - не удалось создать файл / папку
   *    - ошибка backend (500, timeout)
   *    - некорректные DTO с сервера
   *    - падение при маппинге Entity
   *    - delete / move / upload не завершились
   */
  error(message: string, options?: Partial<DiagnosticEvent>) {
    this.emit('error', message, options);
  }

  /**
   * Критерий: действие выполнено частично или с ограничениями
   * ⚠️ warning
   *    - файл пропущен при загрузке (неподдерживаемый тип)
   *    - MIME не совпал, но загрузка разрешена
   *    - часть файлов не удалилась
   *    - файл открыт, но без превью
   *    - архив распакован не полностью
   * ⚠️ пользователь должен узнать, но без блокировки интерфейса
   */
  warning(message: string, options?: Partial<DiagnosticEvent>) {
    this.emit('warning', message, options);
  }

  /**
   * Критерий: полезно знать, но не проблема
   * ℹ️ notice
   *    - загрузка завершена
   *    - удалено N файлов
   *    - операция отменена пользователем
   *    - файл уже существует (и пропущен)
   *    - нет превью для этого типа
   * 💡 notice:
   *    - часто показывается toast’ом
   *    - всегда пишется в журнал
   */
  notice(message: string, options?: Partial<DiagnosticEvent>) {
    this.emit('notice', message, options);
  }

  private  generateId(): string {
    // Современные браузеры
    if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
      return crypto.randomUUID();
    }

    // Fallback (достаточно для UI-идентификаторов)
    return (
      Date.now().toString(36) +
      Math.random().toString(36).slice(2)
    );
  }


}
