// BaseOpenableWC.ts
export abstract class BaseOpenableWC extends HTMLElement {
  static get observedAttributes(): string[] {
    return ['open'];
  }

  get open(): boolean {
    return this.hasAttribute('open');
  }

  set open(value: boolean) {
    if (value) {
      this.setAttribute('open', '');
    } else {
      this.removeAttribute('open');
    }
  }

  attributeChangedCallback(name: string, _oldValue: string | null, newValue: string | null): void {
    if (name === 'open') {
      // тут можно сделать кастомизацию через CSS-класс, но для простоты — как было:
      this.style.display = newValue !== null ? 'flex' : 'none';
    }
  }
}
