import type {FileManagerEventBus} from '@/shared/lib/EventBus';
import {CreateService} from "./CreateService";
import type {IFileManagerBackend} from "@/shared/api/fileManager/ports";
import {ModalService} from "@/features/modal/model/ModalService";
import {IFeature} from "@/shared/lib/Feature";
import {IObservable} from "@/shared/lib/Observable";
import {DiagnosticService} from "@/shared/lib/diagnostics/DiagnosticService";

export class CreateFeature  implements IFeature{
  protected service: CreateService;
  private unsubs: (() => void)[] = [];

  constructor(
    private readonly bus: FileManagerEventBus,
    private modalService: ModalService,
    backend: IFileManagerBackend,
    private navState: IObservable<string>,
    diagnostics: DiagnosticService,
  ) {
    this.service = new CreateService(backend, diagnostics);
  }

  init() {
    this.unsubs.push(
      this.bus.on('create:folder:start', async () => {
        const name = await this.modalService.openInputDialog('Название папки');
        if (name.length > 0) {
          await this.service.createFolder(this.navState.getValue(), name);
          // Говорим всем: "данные изменились, обновитесь кто хочет"
          this.bus.emit('nav:refresh', this.navState.getValue());
        }
      }),
      this.bus.on('create:file:start', async () => {
        const name = await this.modalService.openInputDialog('Название файла');
        if (name.length > 0) {
          await this.service.createFile(this.navState.getValue(), name);
          // Говорим всем: "данные изменились, обновитесь кто хочет"
          this.bus.emit('nav:refresh', this.navState.getValue());
        }
      }),
    );
  }

  destroy() {
    this.unsubs.forEach(unsub => unsub());
  }

}
