type EventCallback = (event: PointerEvent | MouseEvent) => void;

/**
 * Обрабатывает событие `contextmenu` (ПКМ) или симуляцию `long-tap` (долгое нажатие) для сенсорных устройств.
 * Использует Pointer Events для универсальной поддержки ввода.
 *
 * @param {HTMLElement} element - Целевой элемент.
 * @param {EventCallback} callback - Функция, вызываемая при срабатывании.
 * @returns {() => void} - Функция отписки.
 */
export function detectContextMenuAndLongPress(element: HTMLElement, callback: EventCallback): () => void {
  let timer: number | null = null;
  const longPressDuration = 500;
  const moveThreshold = 10; // Допустимое смещение пальца в пикселях
  let startX = 0;
  let startY = 0;

  // 1. Стандартный ПКМ (для мыши)
  const handleContextMenu = (event: MouseEvent) => {
    event.preventDefault();
    callback(event);
  };

  // 2. Начало нажатия (для Touch/Pen)
  const handlePointerDown = (event: PointerEvent) => {
    // Если это мышь, игнорируем (пусть работает событие contextmenu)
    if (event.pointerType === 'mouse') return;

    startX = event.clientX;
    startY = event.clientY;

    // Сбрасываем старый таймер, если есть
    if (timer) clearTimeout(timer);

    timer = window.setTimeout(() => {
      // Если таймер сработал - это Long Press
      callback(event);
      timer = null;
    }, longPressDuration);
  };

  // 3. Движение указателя
  const handlePointerMove = (event: PointerEvent) => {
    if (timer) {
      // Если палец сдвинулся слишком сильно — отменяем таймер (это скролл или жест)
      const diffX = Math.abs(event.clientX - startX);
      const diffY = Math.abs(event.clientY - startY);

      if (diffX > moveThreshold || diffY > moveThreshold) {
        clearTimeout(timer);
        timer = null;
      }
    }
  };

  // 4. Отпускание или отмена (например, уход пальца за пределы экрана или системный жест)
  const handlePointerUpOrCancel = () => {
    if (timer) {
      clearTimeout(timer);
      timer = null;
    }
  };

  // Подписки
  element.addEventListener('contextmenu', handleContextMenu);
  element.addEventListener('pointerdown', handlePointerDown);
  element.addEventListener('pointermove', handlePointerMove);
  element.addEventListener('pointerup', handlePointerUpOrCancel);
  element.addEventListener('pointercancel', handlePointerUpOrCancel);

  // Отписка
  return () => {
    element.removeEventListener('contextmenu', handleContextMenu);
    element.removeEventListener('pointerdown', handlePointerDown);
    element.removeEventListener('pointermove', handlePointerMove);
    element.removeEventListener('pointerup', handlePointerUpOrCancel);
    element.removeEventListener('pointercancel', handlePointerUpOrCancel);
    if (timer) clearTimeout(timer);
  };
}

/**
 * Обнаруживает двойное нажатие (Tap/Click) через Pointer Events.
 * Работает и для мыши, и для тача.
 *
 * @param {HTMLElement} element - Элемент для отслеживания.
 * @param {() => void} callback - Действие при двойном клике.
 * @param {number} maxInterval - Интервал в мс (по умолчанию 300).
 */
export function detectDoubleTap(element: HTMLElement, callback: () => void, maxInterval: number = 300): () => void {
  let lastTapTime: number | null = null;

  const handlePointerDown = (event: PointerEvent) => {
    // Опционально: можно проверять event.isPrimary, чтобы реагировать только на основной палец/кнопку
    if (!event.isPrimary) return;

    const currentTime = Date.now();

    if (lastTapTime !== null && currentTime - lastTapTime <= maxInterval) {
      // Двойной тап обнаружен
      callback();
      lastTapTime = null;
    } else {
      // Первый тап
      lastTapTime = currentTime;
    }
  };

  // Используем pointerdown вместо mousedown/touchstart
  element.addEventListener('pointerdown', handlePointerDown);

  return () => {
    element.removeEventListener('pointerdown', handlePointerDown);
  };
}

/**
 * Обработка клика вне элемента.
 * Использует `pointerdown` на document, что покрывает и мышь, и тач.
 *
 * @param {HTMLElement} el - Элемент, клики вне которого отслеживаем.
 * @param {() => void} callback - Функция обратного вызова.
 */
export function handleOutsideClick(el: HTMLElement, callback: () => void): () => void {
  const handleDocPointerDown = (event: PointerEvent) => {
    // Использует event.composedPath(). Это важно для Web Components (Shadow DOM), чтобы правильно определять, был ли клик внутри компонента или нет.
    // event.composedPath() помогает, если элемент внутри Shadow DOM
    const path = event.composedPath();
    if (el && !path.includes(el)) {
      callback();
    }
  };

  // `pointerdown` срабатывает раньше `click`, что делает интерфейс отзывчивее
  document.addEventListener('pointerdown', handleDocPointerDown);

  return () => {
    document.removeEventListener('pointerdown', handleDocPointerDown);
  };
}

/**
 * Получает нормализованную позицию (x, y) из события.
 * Благодаря PointerEvent логика упрощается, так как .pageX/.pageY есть всегда.
 *
 * @param {PointerEvent | MouseEvent | TouchEvent} event
 */
export function getPointerPosition(event: Event): { x: number; y: number } {
  // Если это современный PointerEvent или MouseEvent
  if (event instanceof MouseEvent || (typeof PointerEvent !== 'undefined' && event instanceof PointerEvent)) {
    return {
      x: event.pageX,
      y: event.pageY
    };
  }

  // Fallback для старых TouchEvent (на всякий случай, хотя в PointerEvents среде это редко нужно)
  if (typeof TouchEvent !== 'undefined' && event instanceof TouchEvent) {
    const touch = event.touches[0] || event.changedTouches[0];
    if (touch) {
      return {
        x: touch.pageX,
        y: touch.pageY
      };
    }
  }

  return { x: 0, y: 0 };
}

type KeyEventHandler = (event: KeyboardEvent) => void;

/**
 * Обнаружение нажатия клавиш.
 * (Эта функция не зависит от типа указующего устройства, оставляем как есть, только типизация).
 */
export function detectKeyPress(target: EventTarget = document, callback: KeyEventHandler, keyFilter?: string | string[]): () => void {
  const handleKeyDown = (event: Event) => {
    const kbEvent = event as KeyboardEvent;
    if (keyFilter) {
      const keys = Array.isArray(keyFilter) ? keyFilter : [keyFilter];
      if (!keys.includes(kbEvent.key)) {
        return;
      }
    }
    callback(kbEvent);
  };

  target.addEventListener('keydown', handleKeyDown);

  return () => {
    target.removeEventListener('keydown', handleKeyDown);
  };
}
