import styles from './scss/split-panel.scss';

const sheet = new CSSStyleSheet();
sheet.replaceSync(styles);

// Константы ограничений
const MIN_LEFT_WIDTH = 200; // Минимальная ширина дерева
const MIN_RIGHT_WIDTH = 100; // Минимальная ширина контента

export class SplitPanelWC extends HTMLElement {
  #isResizing = false;
  #isMobileMode = false;
  // Координата X левого края всего компонента SplitPanel относительно viewport
  hostLeftX: number = 0;
  private median: HTMLElement | null = null;

  /**
   * Флаг-предохранитель от срабатывания pointerup на чужом элементе, если тащить разделитель и бросить на содержимое слотов
   * Почему это работает?
   *  - Фаза захвата (true в addEventListener): Когда вы отпускаете мышь, событие click начинает спускаться от window вниз к элементу дерева. Поставив перехватчик на window с флагом true, мы ловим этот клик самыми первыми.
   *  - stopPropagation(): Мы говорим браузеру: «Дальше это событие передавать не нужно». В итоге дерево (TreeWC) даже не узнает, что над ним что-то кликнули.
   *  - Автоудаление: Обработчик blockClick удаляет сам себя сразу после выполнения, так что обычные клики (когда вы просто хотите выбрать папку) продолжат работать.
   */
  private wasResizing = false;


  connectedCallback() {
    // Однократная инициализация shadow DOM и bind'ов (повторное подключение к DOM её не повторяет)
    if (!this.shadowRoot) {
      const shadow = this.attachShadow({mode: 'open'});
      shadow.adoptedStyleSheets = [sheet];
      shadow.innerHTML = this.getTemplate();
      this.median = shadow.querySelector("#median");

      this.resizeDrag = this.resizeDrag.bind(this);
      this.pointerUp = this.pointerUp.bind(this); // Биндим для удаления слушателя
      this.pointerDown = this.pointerDown.bind(this); // Биндим ОДИН раз: removeEventListener получает ту же ссылку
    }

    // Слушатели — при каждом подключении (disconnectedCallback их симметрично снимает).
    // handleResize — поле-стрелка, bind не нужен: при снятии используется та же ссылка.
    this.median!.addEventListener("pointerdown", this.pointerDown);
    window.addEventListener('resize', this.handleResize); // TODO EventDebouncer

    this.handleResize();
  }

  disconnectedCallback() {
    if (this.median) this.median.removeEventListener("pointerdown", this.pointerDown);
    window.removeEventListener('resize', this.handleResize);
  }

  getTemplate() {
    return `
<div id="panelLeft"><slot name="left"></slot></div>
<div id="median"></div>
<div id="panelRight"><slot name="right"></slot></div>
`;
  }

  pointerDown(e: PointerEvent) {
    this.isResizing = true;
    this.wasResizing = false; // Сбрасываем при каждом нажатии

    const clientRect = this.getBoundingClientRect();
    this.hostLeftX = clientRect.left;

    // Захват указателя, чтобы драг не срывался при быстром движении
    this.median!.setPointerCapture(e.pointerId);

    this.median!.addEventListener("pointermove", this.resizeDrag as EventListener);
    this.median!.addEventListener("pointerup", this.pointerUp);
    this.median!.addEventListener("pointercancel", this.pointerUp);
  }

  pointerUp(e: PointerEvent) {
    this.isResizing = false;
    this.median!.releasePointerCapture(e.pointerId);
    this.median!.removeEventListener("pointermove", this.resizeDrag as EventListener);
    this.median!.removeEventListener("pointerup", this.pointerUp);
    this.median!.removeEventListener("pointercancel", this.pointerUp);

    // ЕСЛИ был ресайз — блокируем следующий клик
    if (this.wasResizing) {
      const blockClick = (event: MouseEvent) => {
        event.stopPropagation(); // Не даем событию дойти до дерева
        event.preventDefault();
        window.removeEventListener('click', blockClick, true);
      };
      // true — используем фазу захвата, чтобы перехватить событие раньше дерева
      window.addEventListener('click', blockClick, true);
    }

    this.dispatchEvent(new CustomEvent('sizechanged'));
  }

  resizeDrag(e: PointerEvent) { // Используем PointerEvent, так как слушаем pointermove
    if (!this.isResizing) return;
    this.wasResizing = true; // Если мышь сдвинулась хоть на пиксель — это ресайз, а не клик
    e.preventDefault(); // Важно для предотвращения выделения текста

    const containerWidth = this.getBoundingClientRect().width;

    // 1. Вычисляем желаемую ширину левой панели
    // e.clientX - абсолютная координата мыши
    // this.hostLeftX - абсолютная координата левого края компонента
    let newLeftWidth = e.clientX - this.hostLeftX;

    // 2. Применяем жесткий минимум для левой панели (Дерево)
    if (newLeftWidth < MIN_LEFT_WIDTH) {
      newLeftWidth = MIN_LEFT_WIDTH;
    }

    // 3. Вычисляем максимум, который можно занять, оставив место для правой панели
    // Учитываем ширину самого разделителя (обычно около 5px)
    const medianWidth = this.median!.offsetWidth || 5;
    let maxAvailableLeft = containerWidth - MIN_RIGHT_WIDTH - medianWidth;

    // 4. Корректировка для узких экранов (Conflict resolution)
    // Если контейнер настолько мал (например, 250px), что (200 + 100) не влезает:
    // maxAvailableLeft (145px) будет МЕНЬШЕ, чем minLeftWidth (200px).
    // В этом случае мы отдаем приоритет левой панели (пусть правая схлопывается, но дерево работает).
    if (maxAvailableLeft < MIN_LEFT_WIDTH) {
      maxAvailableLeft = MIN_LEFT_WIDTH;
      // В этот момент правая панель уйдет за пределы или сожмется до 0, но JS не сломается.
    }

    // Применяем ограничение справа
    if (newLeftWidth > maxAvailableLeft) {
      newLeftWidth = maxAvailableLeft;
    }

    // 5. Применяем стиль
    // max-content для медианы, 1fr для правой части
    this.style.gridTemplateColumns = `${newLeftWidth}px max-content 1fr`;
  }

  set isResizing(value) {
    this.#isResizing = value;
    if (value) {
      this.setAttribute("resizing", "");

      // Запрещаем взаимодействие с контентом (деревом и файлами) во время драга
      this.style.pointerEvents = "none";
      // Но самому разделителю (median) возвращаем pointer-events, чтобы драг работал
      if (this.median) this.median.style.pointerEvents = "auto";

      // Добавляем стиль body, чтобы курсор не моргал при выходе за пределы median
      document.body.style.cursor = "col-resize";
      document.body.style.userSelect = "none";
    } else {
      this.removeAttribute("resizing");

      this.style.pointerEvents = "";

      document.body.style.cursor = "";
      document.body.style.userSelect = "";
    }
  }

  get isResizing() {
    return this.#isResizing;
  }

  handleResize = () => {
    if (this.checkMobileDevice()) {
      this.switchToMobile();
    } else {
      this.switchToDesktop();
    }
  };

  switchToDesktop = () => {
    this.#isMobileMode = false;
    this.removeAttribute('mobile-mode');
    this.removeAttribute('show-right');
  };

  switchToMobile = () => {
    this.#isMobileMode = true;
    this.setAttribute('mobile-mode', '');
    this.setAttribute('show-right', '');
  };

  showLeftPanel = () => {
    if (this.#isMobileMode) {
      this.removeAttribute('show-right');
    }
  };

  showRightPanel = () => {
    if (this.#isMobileMode) {
      this.setAttribute('show-right', '');
    }
  };

  togglePanels = () => {
    if (this.#isMobileMode) {
      if (this.hasAttribute('show-right')) {
        this.removeAttribute('show-right');
      } else {
        this.setAttribute('show-right', '');
      }
    }
  };

  // ===================================================================================
  // Чтобы не забыть, позже вынести всю логику определения мобильного браузера нга уровень всего приложения
  // ===================================================================================

  private checkMobileDevice(): boolean {
    return window.innerWidth <= 768 || /Mobi|Android/i.test(navigator.userAgent);
  }

}

customElements.define("split-wc", SplitPanelWC);
