import type {FileManagerEventBus} from '@/shared/lib/EventBus';
import type {IFileManagerBackend} from "@/shared/api/fileManager/ports";
import {MoveService} from "@/features/move/model/MoveService";
import {ModalService} from "@/features/modal/model/ModalService";
import {IObservable} from "@/shared/lib/Observable";
import {SelectionState} from "@/features/selection/model/SelectionStore";
import {IFeature} from "@/shared/lib/Feature";

export class MoveFeature  implements IFeature{
  private service: MoveService;
  private unsubs: (() => void)[] = [];

  constructor(
    private readonly bus: FileManagerEventBus,
    private modalService: ModalService,
    backend: IFileManagerBackend,
    private selectionState: IObservable<SelectionState>,
  ) {
    this.service = new MoveService(backend);
  }

  init() {
    this.unsubs.push(
      this.bus.on('move:start', async () => {
        const selection: SelectionState = this.selectionState.getValue();
        if (['single-folder', 'multiple-folders', 'single-file', 'multiple-files', 'mixed'].includes(selection.type)) {

          // TODO - разная логика перемещения? Что проверять?
          const paths: string[] = [];
          selection.files.forEach((item) => {
            paths.push(item)
          })
          selection.folders.forEach((item) => {
            paths.push(item)
          })

          const targetPath = ''; // TODO
          // TODO - await Promise.all(movePromises.map());
          for (const path of paths) {
            const sourcePath = path;
            if (sourcePath && targetPath && sourcePath !== targetPath) {
              const res = await this.service.move(sourcePath, targetPath);
            }
          }

          // TODO - Проверить успешность результата как-нибудь
          // разумно обновить целевую директорию (или обе, если нужно)
          // bus.emit('nav:refresh', sourcePath);
          this.bus.emit('nav:refresh', targetPath);
          this.bus.emit('move:complete', targetPath);

        }
      }),
    );
  }

  destroy() {
    this.unsubs.forEach(unsub => unsub());
  }

}
