import { PropertiesService } from "./PropertiesService";
import type { FileManagerEventBus } from "@/shared/lib/EventBus";
import { ModalService } from "@/features/modal/model/ModalService";
import { IObservable } from "@/shared/lib/Observable";
import { SelectionState } from "@/features/selection/model/SelectionStore";
import { FolderRegistry } from "@/entities/folder/model/FolderRegistry";
import { IFeature } from "@/shared/lib/Feature";
import { FileEntity } from "@/entities/file/model/FileEntity";
import { FolderEntity } from "@/entities/folder/model/FolderEntity";
import { IconHelper } from "@/shared/ui/directory-content-desktop/helpers/IconHelper";
import { PropertiesWC, PropertiesData } from "../ui/PropertiesWC"; // Импорт компонента
import {FormatHelper} from "../lib/FormatHelper";

import { IFileManagerBackend } from '@/shared/api/fileManager/ports';
// ...

// Импорт нужен, чтобы custom element зарегистрировался, если он еще не в бандле
import "@/features/properties/ui/PropertiesWC";

export class PropertiesFeature implements IFeature {
  private service: PropertiesService;
  private unsubs: (() => void)[] = [];

  private iconHelper = new IconHelper();

  // Создаем экземпляр компонента один раз (или можно создавать каждый раз новый)
  private propertiesWC = new PropertiesWC();

  // Нужно хранить текущий путь файла, чтобы знать, что анализировать
  private currentFilePath: string | null = null;

  constructor(
    private readonly bus: FileManagerEventBus,
    private modalService: ModalService,
    private selectionState: IObservable<SelectionState>,
    private registry: FolderRegistry,
    private navState: IObservable<string>,
    private backend: IFileManagerBackend,
  ) {
    this.service = new PropertiesService();
    this.initListeners(); // Вынесем подписку на DOM-события
  }

  // Подписка на события от WebComponent (так как он живет внутри фичи)
  private initListeners() {
    this.propertiesWC.addEventListener('request-analysis', async () => {
      if (!this.currentFilePath) return;

      try {
        // 1. Делаем запрос к API
        const result = await this.backend.analyze({ path: this.currentFilePath });

        // 2. Отдаем данные в UI
        this.propertiesWC.setAnalysisData(result);
      } catch (e: any) {
        // В случае ошибки показываем алерт (или можно добавить состояние ошибки в сам компонент)
        alert('Ошибка анализа файла: ' + e.message);
        // Сбрасываем UI (можно добавить метод resetAnalysisState, но переключение табов тоже сбросит кнопку)
      }
    });
  }
  init() {
    this.unsubs.push(
      this.bus.on('properties', async () => {
        const selection: SelectionState = this.selectionState.getValue();
        let data: PropertiesData | null = null;
        this.currentFilePath = null; // Сброс

        // 1. ОДИН ФАЙЛ
        if (selection.type === 'single-file') {
          const fileKey = [...selection.files][0];
          const file = this.registry.getFileEntity(fileKey);
          if (file) {
            this.currentFilePath = file.key; // <-- Запоминаем путь для анализа
            data = this.prepareFileData(file);
          }

          // 2. ОДНА ПАПКА (или пустой selection -> текущая папка)
        } else if (selection.type === 'single-folder' || selection.type === 'empty') {
          let folder: FolderEntity | null = null;

          if (selection.type === 'single-folder') {
            folder = this.registry.getFolderByPath([...selection.folders][0]);
          } else {
            // Текущая директория
            folder = this.registry.getFolderByPath(this.navState.getValue());
          }

          if (folder) {
            data = this.prepareFolderData(folder);
          }
        }
        // 3. МНОЖЕСТВЕННЫЙ ВЫБОР
        else if (selection.type === 'multiple-files' || selection.type === 'multiple-folders' || selection.type === 'mixed') {
          data = this.prepareMultiSelectionData(selection);
        }

        if (data) {
          // Устанавливаем данные в компонент
          this.propertiesWC.setData(data);
          // Открываем модальное окно с компонентом
          await this.modalService.openInfoDialog(this.propertiesWC);
        }
      }),
    );
  }

  destroy() {
    this.unsubs.forEach(unsub => unsub());
  }

  // --- Helpers для подготовки данных (ViewModel) ---

  private prepareFileData(file: FileEntity): PropertiesData {
    const general = new Map<string, string>();
    general.set('Тип', file.fileType || 'Файл');
    general.set('Путь', file.path);
    general.set('Размер', FormatHelper.formatBytes(file.meta?.size));
    general.set('Изменен', FormatHelper.dateTimeFromTimestamp(file.meta?.mTime));
    general.set('URL', file.url || '-');
    if (file.meta?.dimensions) {
      general.set('Размеры', `${file.meta.dimensions.width} x ${file.meta.dimensions.height} px`);
    }

    const permissions = new Map<string, string>();
    permissions.set('Права (chmod)', FormatHelper.formatPermissions(file.meta?.permissions));
    permissions.set('Запись', file.meta?.isWritable ? 'Да' : 'Нет');
    permissions.set('Чтение', file.meta?.isReadable ? 'Да' : 'Нет');
    permissions.set('Исполнение', file.meta?.isExecutable ? 'Да' : 'Нет');

    return {
      title: file.name,
      typeLabel: file.extension.toUpperCase() + ' Файл',
      iconUrl: this.iconHelper.getUrl(file),
      general,
      permissions
    };
  }

  private prepareFolderData(folder: FolderEntity): PropertiesData {
    const general = new Map<string, string>();
    general.set('Тип', 'Папка с файлами');
    general.set('Путь', folder.path);
    general.set('Содержит', `${folder.countChildFiles} файлов, ${folder.countChildDirs} папок`);
    general.set('Изменен', FormatHelper.dateTimeFromTimestamp(folder.meta?.mTime));

    const permissions = new Map<string, string>();
    permissions.set('Права (chmod)', FormatHelper.formatPermissions(folder.meta?.permissions));

    return {
      title: folder.name,
      typeLabel: 'Директория',
      iconUrl: this.iconHelper.getUrl(folder),
      general,
      permissions
    };
  }

  private prepareMultiSelectionData(selection: SelectionState): PropertiesData {
    const totalFiles = selection.files.size;
    const totalFolders = selection.folders.size;

    // Тут можно добавить подсчет общего размера, пробежавшись по Entities через Registry
    // let totalSize = 0; ...

    const general = new Map<string, string>();
    general.set('Выбрано объектов', String(totalFiles + totalFolders));
    general.set('Файлов', String(totalFiles));
    general.set('Папок', String(totalFolders));

    return {
      title: 'Выбрано несколько объектов',
      typeLabel: 'Группа',
      general,
      // Иконку для группы можно взять специальную или оставить пустой
      iconUrl: undefined
    };
  }
}
