export class FormatHelper {

  static dateTimeFromTimestamp(timestamp: number | null | unknown | undefined): string {
    if (typeof timestamp === 'number') {
      return new Date(timestamp * 1000).toLocaleString('ru-RU');
    }
    return '-';
  }

  /**
   * Вспомогательная функция, которая преобразует права доступа,
   * возвращаемые `SplFileInfo::getPerms` в восьмеричном представлении,
   * в человекопонятный вид.
   */
  static formatPermissions(permissions: number | null | unknown | undefined) {
    if (typeof permissions === 'number') {

      // Преобразуем число в восьмеричное представление и убираем лишний символ '0'
      const octal = permissions.toString(8).slice(-3);

      // Массив символов для прав доступа
      const symbols = ['---', '--x', '-w-', '-wx', 'r--', 'r-x', 'rw-', 'rwx'];

      // Получаем права доступа для владельца, группы и остальных пользователей
      const owner = symbols[parseInt(octal.charAt(0), 8)];
      const group = symbols[parseInt(octal.charAt(1), 8)];
      const others = symbols[parseInt(octal.charAt(2), 8)];

      // Объединяем права доступа в одну строку
      return `${owner}-${group}-${others}`;
    }
    return '-';
  }

  /**
   * Конвертирует байты в кратные единицы
   * @see https://stackoverflow.com/a/18650828/24489536
   * Minified version (by StackOverflow's community, minified by (JSCompress)[https://jscompress.com/]) - // function formatBytes(a,b=2){if(!+a)return"0 Bytes";const c=0>b?0:b,d=Math.floor(Math.log(a)/Math.log(1024));return`${parseFloat((a/Math.pow(1024,d)).toFixed(c))} ${["Bytes","KiB","MiB","GiB","TiB","PiB","EiB","ZiB","YiB"][d]}`}
   */
  static formatBytes(bytes: number | null | unknown | undefined, decimals = 2): string {
    if (typeof bytes === 'number') {
      if (!+bytes) return '0 Bytes';
      const k = 1024;
      const dm = decimals < 0 ? 0 : decimals;
      const sizes = ['Bytes', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB', 'EiB', 'ZiB', 'YiB'];
      const i = Math.floor(Math.log(bytes) / Math.log(k));
      return `${parseFloat((bytes / Math.pow(k, i)).toFixed(dm))} ${sizes[i]}`;
    }
    return '-';
  }

}
