import type {FileAnalysisDto} from "@/shared/api/fileManager/dto";

import styles from './scss/properties.scss';

const sheet = new CSSStyleSheet();
sheet.replaceSync(styles);

export type PropertiesData = {
  title: string;
  iconUrl?: string; // URL иконки
  typeLabel: string; // Например "Папка" или "JPEG Image"

  // Общие свойства
  general: Map<string, string>;

  // Свойства для вкладки "Доступ" (Permissions)
  permissions?: Map<string, string>;

  // Поле для хранения уже загруженного анализа (кеширование на уровне UI, пока окно открыто)
  analysis?: FileAnalysisDto;
};

export class PropertiesWC extends HTMLElement {
  private tabsContainer: HTMLElement | null = null;
  private contentContainer: HTMLElement | null = null;
  private data: PropertiesData | null = null;

  private isInitialized = false;

  // Элементы вкладки анализа
  private analyzeBtn: HTMLButtonElement | null = null;
  private analysisContent: HTMLElement | null = null;

  connectedCallback() {
    if (this.isInitialized) return;
    if (this.shadowRoot) return;
    const shadow = this.attachShadow({mode: 'open'});
    shadow.adoptedStyleSheets = [sheet];

    // Базовая разметка
    shadow.innerHTML = `
      <div class="header" id="header">
        <div class="header-icon" id="header-icon"></div>
        <div class="header-info">
           <div class="header-name" id="header-name">-</div>
           <div class="header-type" id="header-type">-</div>
        </div>
      </div>

      <div class="tabs" id="tabs">
        <button class="tab-btn active" data-tab="general">Общие</button>
        <button class="tab-btn" data-tab="permissions">Доступ</button>
        <button class="tab-btn" data-tab="analysis">Анализ</button>
      </div>

      <div id="content-container"></div>
    `;

    this.tabsContainer = shadow.getElementById('tabs');
    this.contentContainer = shadow.getElementById('content-container');

    // Логика переключения табов
    this.tabsContainer?.addEventListener('click', (e) => {
      const target = e.target as HTMLElement;
      if (target.classList.contains('tab-btn')) {
        this.switchTab(target.dataset.tab || 'general');
      }
    });

    this.isInitialized = true;

    // Если данные уже были переданы до того как компонент попал в DOM
    if (this.data) {
      this.renderHeader();
      this.switchTab('general');
    }
  }

  /**
   * Основной метод для передачи данных в компонент
   */
  public setData(data: PropertiesData) {
    this.data = data;
    if (this.isInitialized) {
      this.renderHeader();
      this.switchTab('general');
    }
  }

  /** * Публичный метод для обновления UI после получения данных с сервера
   */
  public setAnalysisData(analysis: FileAnalysisDto) {
    if (this.data) {
      this.data.analysis = analysis;
      // Если мы всё еще на вкладке анализа - перерисуем её
      const activeTab = this.shadowRoot?.querySelector('.tab-btn.active') as HTMLElement;
      if (activeTab?.dataset.tab === 'analysis') {
        this.renderAnalysisTab(this.contentContainer!.firstElementChild as HTMLElement);
      }
    }
  }

  private renderHeader() {
    if (!this.shadowRoot || !this.data) return;

    const nameEl = this.shadowRoot.getElementById('header-name');
    const typeEl = this.shadowRoot.getElementById('header-type');
    const iconEl = this.shadowRoot.getElementById('header-icon');

    if (nameEl) nameEl.textContent = this.data.title;
    if (typeEl) typeEl.textContent = this.data.typeLabel;

    if (iconEl && this.data.iconUrl) {
      // Если это SVG DataURI или путь
      // iconEl.style.backgroundImage = `url('${this.data.iconUrl}')`;

      // Очищаем URL от лишних кавычек, если они пришли из данных
      const cleanUrl = this.data.iconUrl.replace(/^["']|["']$/g, '');

      // Используем шаблонную строку без добавления лишних кавычек внутри url()
      iconEl.style.backgroundImage = `url(${cleanUrl})`;

      // Добавим стили для нормального отображения превью картинок
      iconEl.style.backgroundSize = 'contain';
      iconEl.style.backgroundRepeat = 'no-repeat';
      iconEl.style.backgroundPosition = 'center';
    }
  }

  private switchTab(tabName: string) {
    if (!this.shadowRoot || !this.contentContainer) return;

    // 1. Обновляем активный класс кнопок
    const buttons = this.shadowRoot.querySelectorAll('.tab-btn');
    buttons.forEach(btn => {
      if ((btn as HTMLElement).dataset.tab === tabName) {
        btn.classList.add('active');
      } else {
        btn.classList.remove('active');
      }
    });

    // 2. Рендерим содержимое
    this.contentContainer.innerHTML = '';

    const wrapper = document.createElement('div');
    wrapper.className = 'tab-content active';

    if (tabName === 'general') {
      wrapper.appendChild(this.createGrid(this.data?.general));
    } else if (tabName === 'permissions') {
      wrapper.appendChild(this.createGrid(this.data?.permissions));
    } else if (tabName === 'analysis') {
      this.renderAnalysisTab(wrapper);
    }

    this.contentContainer.appendChild(wrapper);
  }

  /** Создает Grid Key-Value */
  private createGrid(map?: Map<string, string>): HTMLElement {
    const grid = document.createElement('div');
    grid.className = 'prop-grid';

    if (!map) {
      grid.textContent = 'Нет данных';
      return grid;
    }

    map.forEach((value, key) => {
      const label = document.createElement('div');
      label.className = 'prop-label';
      label.textContent = key + ':';

      const valDiv = document.createElement('div');
      valDiv.className = 'prop-value';

      // Текст значения помещаем в span для лучшего контроля
      const textSpan = document.createElement('span');
      textSpan.textContent = value;

      // Если это путь или URL, добавим кнопку копирования
      if (key === 'Путь' || key === 'URL' || key === 'Расположение') {
        const copyBtn = document.createElement('button');
        copyBtn.className = 'copy-btn';
        copyBtn.textContent = '📋';
        copyBtn.title = 'Копировать';

        copyBtn.onclick = async () => {
          const textToCopy = value;

          try {
            if (navigator.clipboard && window.isSecureContext) {
              await navigator.clipboard.writeText(textToCopy);
            } else {
              // Fallback для небезопасных сред (http)
              const textArea = document.createElement("textarea");
              textArea.value = textToCopy;
              textArea.style.position = "fixed";
              document.body.appendChild(textArea);
              textArea.focus();
              textArea.select();
              document.execCommand('copy');
              document.body.removeChild(textArea);
            }

            copyBtn.textContent = '✅';
            setTimeout(() => copyBtn.textContent = '📋', 1000);
          } catch (err) {
            console.error('Ошибка копирования:', err);
          }
        };

        valDiv.appendChild(copyBtn); // Кнопка будет первой
      }

      valDiv.appendChild(textSpan);

      grid.appendChild(label);
      grid.appendChild(valDiv);
    });

    return grid;
  }

  // --- Логика вкладки "Анализ" ---

  private renderAnalysisTab(container: HTMLElement) {
    container.innerHTML = ''; // Очистка

    // 1. Данные уже есть -> показываем результат
    if (this.data?.analysis) {
      const { mime, hexDump } = this.data.analysis;

      const infoDiv = document.createElement('div');
      infoDiv.innerHTML = `
            <div class="prop-grid" style="margin-bottom: 10px;">
                <div class="prop-label">Detected MIME:</div>
                <div class="prop-value"><b>${mime}</b></div>
            </div>
            <div class="hex-label" style="color:#666; font-size:0.9em; margin-bottom:5px;">HEX Preview (First bytes):</div>
        `;

      const pre = document.createElement('pre');
      pre.className = 'hex-preview';
      pre.textContent = hexDump;

      container.appendChild(infoDiv);
      container.appendChild(pre);
      return;
    }

    // 2. Данных нет -> кнопка запроса
    const description = document.createElement('p');
    description.style.color = '#666';
    description.style.fontSize = '0.9em';
    description.textContent = 'Нажмите кнопку ниже, чтобы запросить глубокий анализ файла с сервера (HEX, сигнатуры, метаданные).';

    this.analyzeBtn = document.createElement('button');
    this.analyzeBtn.className = 'action-btn'; // Добавить стиль в CSS
    this.analyzeBtn.textContent = '⚡ Выполнить анализ';

    this.analyzeBtn.onclick = () => {
      // Меняем состояние кнопки на загрузку
      if (this.analyzeBtn) {
        this.analyzeBtn.disabled = true;
        this.analyzeBtn.textContent = '⏳ Загрузка данных...';
      }
      // Отправляем событие наружу (в PropertiesFeature)
      this.dispatchEvent(new CustomEvent('request-analysis', {
        bubbles: true,
        composed: true
      }));
    };

    container.appendChild(description);
    container.appendChild(this.analyzeBtn);
  }

  /** Заглушка для будущего HEX-анализатора */
  private createDetailsPlaceholder(): HTMLElement {
    const div = document.createElement('div');
    div.innerHTML = `
      <p style="margin-top:0; color:#666; font-size:0.9em;">
        Здесь будет отображаться глубокий анализ содержимого файла (Magic numbers, EXIF, ID3 теги и HEX-просмотр).
      </p>
      <div class="hex-preview">
        00000000  89 50 4E 47 0D 0A 1A 0A  00 00 00 0D 49 48 44 52  |.PNG........IHDR|<br>
        00000010  00 00 04 B0 00 00 02 D0  08 06 00 00 00 C4 26 9C  |..............&.|<br>
        00000020  C7 00 00 00 01 73 52 47  42 00 AE CE 1C E9 00 00  |.....sRGB.......|<br>
        ...
      </div>
    `;
    return div;
  }
}

customElements.define('properties-wc', PropertiesWC);
