// src/shared/ui/resizable-modal/DirectoryContentWC.ts

import {FolderEntity} from "@/entities/folder/model/FolderEntity";
import {FileEntity} from "@/entities/file/model/FileEntity";
import {AppError} from "@/shared/lib/error/AppError";
import {detectContextMenuAndLongPress} from "@/shared/lib/dom/GestureHelper";
import {ViewMode} from "@/features/directory-content/model/directory-content.events";

import styles from './scss/directory-content.scss';
import {IconHelper} from "./helpers/IconHelper";

import {detectContextMenuAndLongTap} from "@/shared/lib/dom/pointer-events";

const sheet = new CSSStyleSheet();
sheet.replaceSync(styles);

// --- Типы DOM-событий, которые будет выбрасывать компонент ---
export type DirectoryItemType = 'file' | 'folder' | 'empty';

export type DirectoryItemDetail = {
  type: DirectoryItemType;
  key: string;
};

export type DirectorySelectionDetail = Set<DirectoryItemDetail>;

export type DirectoryContextMenuDetail = {
  type: DirectoryItemType;
  key: string;
  event: PointerEvent;
};

export class DirectoryContentWC extends HTMLElement {
  private iconHelper: IconHelper;
  private content: HTMLElement | null = null;

  // Переменные для отслеживания выделенных элементов
  private selectedItems: Set<HTMLElement> = new Set();
  private lastSelectedItem: HTMLElement | null = null;

  // Переменные для рисования рамки выделения
  private selectionBox: HTMLElement | null = null;
  private isSelecting: boolean = false;           // активная рамка
  private isSelectionCandidate: boolean = false;  // кнопка зажата, но порог ещё не пройден
  private startX: number = 0;
  private startY: number = 0;
  private dragStartClientX: number = 0;
  private dragStartClientY: number = 0;

  private static readonly DRAG_THRESHOLD = 4; // px

  constructor() {
    super();
    // TODO Веб-компонент должен иметь пустой конструктор. Все данные форматируем снаружи и сюда передаём в готовом виде.
    this.iconHelper = new IconHelper();
  }

  static get observedAttributes() {
    return ['view-mode'];
  }

  connectedCallback(): void {
    if (this.shadowRoot) return;

    const shadow = this.attachShadow({mode: 'open'});
    shadow.adoptedStyleSheets = [sheet];
    shadow.innerHTML = this.getTemplate();

    this.content = shadow.getElementById('content');
    this.selectionBox = shadow.getElementById('selection-box');
    if (!this.content || !this.selectionBox) {
      throw new AppError('Required elements not found.');
    }

    // Контекстное меню по пустому месту
    detectContextMenuAndLongTap(this, (event: Event) => {
      const pe = event as PointerEvent;

      this.dispatchEvent(
        new CustomEvent<DirectoryContextMenuDetail>('content-contextmenu',
          {
            detail: {
              type: 'empty',
              key: '',
              event: pe,
            },
            bubbles: true,
            composed: true,
          }
        ),
      );
    });

    // ВАЖНО: методы уже объявлены как стрелочные поля класса, поэтому .bind(this) НЕ нужен – это только мешает нормальному removeEventListener.
    // Порядок на pointerdown важен:
    //    - hostPointerDown — проверяет, был ли клик по item; если нет → сразу очищает выделение.
    //    - clickLeftPointerDown — если клик по .fm-item, работает Ctrl/Shift/одиночное выделение.
    //    - selectionBoxPointerDown — включает isSelecting и показывает рамку для drag’а.
    // При простом клике по пустому месту:
    //    - hostPointerDown → снимает выделение;
    //    - clickLeftPointerDown → не находит item, ничего не делает;
    //    - selectionBoxPointerDown → может включить рамку (если хочешь, можно оставить как есть — рамка будет просто нулевого размера и исчезнет при pointerup, это ок).
    // 1) Сначала — клик по хосту (снять выделение по пустому месту)
    this.addEventListener('pointerdown', this.hostPointerDown);
    // 2) Выделение кликом по элементу
    this.addEventListener('pointerdown', this.clickLeftPointerDown as EventListener);
    // 3) Рамка выделения
    this.addEventListener('pointerdown', this.selectionBoxPointerDown as EventListener);
    this.addEventListener('pointermove', this.selectionBoxPointerMove as EventListener);
    this.addEventListener('pointerup', this.selectionBoxPointerUp as EventListener);
    // Двойной клик
    this.addEventListener('dblclick', this.clickDblClick as EventListener);

    // Установим дефолтный режим, если не задан
    if (!this.hasAttribute('view-mode')) {
      this.setAttribute('view-mode', 'grid');
    }
  }

  disconnectedCallback(): void {
    this.removeEventListener('pointerdown', this.hostPointerDown);
    this.removeEventListener('pointerdown', this.clickLeftPointerDown as EventListener);
    this.removeEventListener('pointerdown', this.selectionBoxPointerDown as EventListener);
    this.removeEventListener('pointermove', this.selectionBoxPointerMove as EventListener);
    this.removeEventListener('pointerup', this.selectionBoxPointerUp as EventListener);
    this.removeEventListener('dblclick', this.clickDblClick as EventListener);
  }

  attributeChangedCallback(name: string, oldValue: string, newValue: string) {
    if (name === 'view-mode') {
      // Здесь можно вызвать перерасчет скролла или виртуализации, если она будет
      // Но для CSS-подхода делать ничего не нужно, стили применятся сами.
    }
  }

  /**
   * Публичный метод для смены режима извне
   */
  public setViewMode(mode: ViewMode): void {
    this.setAttribute('view-mode', mode);
  }

  private getTemplate(): string {
    return `
<ul id="content"></ul>
<div id="selection-box"></div>
    `;
  }

  /**
   * Обновление содержимого панели — как и раньше.
   */
  public setContent(folder: FolderEntity): void {
    const liArray = this.createHtml(folder);
    this.content!.replaceChildren(...liArray);
    // При смене директории логично сбрасывать выделение
    this.unselect();
    this.dispatchSelectionChange();
  }

  /**
   * Двойной клик — ничего не знает про bus/state.
   * Только выбрасывает DOM-событие item-dblclick.
   */
  private clickDblClick = (e: MouseEvent) => {
    const fmItem = e
      .composedPath()
      .find(
        (node) =>
          node instanceof HTMLElement && node.classList.contains('fm-item'),
      ) as HTMLElement | undefined;


    if (!fmItem) return;

    const type = fmItem.dataset.type;
    const key = fmItem.dataset.key;

    if (typeof type !== 'string' || typeof key !== 'string') return;
    if (type !== 'folder' && type !== 'file') return;

    this.dispatchEvent(
      new CustomEvent<DirectoryItemDetail>('item-dblclick', {
        detail: {type, key},
        bubbles: true,
        composed: true,
      }),
    );
  };

  /**
   * Клик для выделения (Ctrl/Shift/одиночный)
   * Теперь «снять выделение, если клик не по item» делает hostPointerDown.
   * В clickLeftPointerDown оставляем только работу с .fm-item и фильтруем по левой кнопке.
   */
  private clickLeftPointerDown = (e: MouseEvent) => {
    // Только левая кнопка
    if (e.button !== 0) return;

    if (this.isSelecting) {
      return; // Если сейчас происходит выделение рамкой, игнорируем клик
    }

    const fmItem = e
      .composedPath()
      .find(
        (node) =>
          node instanceof HTMLElement && node.classList.contains('fm-item'),
      ) as HTMLElement | undefined;

    if (fmItem instanceof HTMLElement) {
      const isCtrl = e.ctrlKey;
      const isShift = e.shiftKey;

      if (isCtrl) {
        if (this.selectedItems.has(fmItem)) {
          this.selectedItems.delete(fmItem);
          fmItem.classList.remove('selected');
        } else {
          this.selectedItems.add(fmItem);
          fmItem.classList.add('selected');
        }
      } else if (isShift && this.lastSelectedItem) {
        const items = Array.from(this.content!.querySelectorAll('.fm-item'));
        const startIndex = items.indexOf(this.lastSelectedItem);
        const endIndex = items.indexOf(fmItem);

        if (startIndex !== -1 && endIndex !== -1) {
          const from = Math.min(startIndex, endIndex);
          const to = Math.max(startIndex, endIndex);

          for (let i = from; i <= to; i++) {
            const item = items[i] as HTMLElement;
            if (!this.selectedItems.has(item)) {
              this.selectedItems.add(item);
              item.classList.add('selected');
            }
          }
        }
      } else {
        if (!fmItem.classList.contains('selected')) {
          this.unselect();
        }
        this.selectedItems.add(fmItem);
        fmItem.classList.add('selected');
      }

      this.lastSelectedItem = fmItem;
      this.updateSelection();
    }
  };

  /** Клик по хосту: снимаем выделение, если клик не по .fm-item */
  private hostPointerDown = (e: PointerEvent) => {
    // Только левая кнопка
    if (e.button !== 0) return;

    // Ищем в пути события элемент .fm-item
    const path = e.composedPath();
    const hasFmItem = path.some(
      (node) => node instanceof HTMLElement && node.classList.contains('fm-item'),
    );

    // Если кликнули не по item — снимаем выделение
    if (!hasFmItem) {
      this.unselect();
      this.dispatchSelectionChange(); // чтобы наружу ушло событие с пустым выделением
    }
  };

  /** Только помечаем «кандидата» */
  private selectionBoxPointerDown = (e: PointerEvent) => {
    if (e.pointerType === 'touch') {
      // Если 'touch', игнорируем рамку (на мобильных это конфликтует со скроллом и нативной навигацией).
      // Для тача выделение обычно работает через Long Press (режим выделения) -> Tap (выбор элементов).
      // На таче рамка не нужна, там другая UX-модель
      return;
    }

    // Только левая кнопка
    if (e.button !== 0) return;

    // При Ctrl/Shift оставляем только логика по клику (range/мультивыбор)
    if (e.shiftKey || e.ctrlKey) return;

    this.isSelectionCandidate = true;
    this.isSelecting = false;

    const hostRect = this.getBoundingClientRect();

    this.dragStartClientX = e.clientX;
    this.dragStartClientY = e.clientY;
    this.startX = e.clientX - hostRect.left;
    this.startY = e.clientY - hostRect.top;

    const box = this.selectionBox!;
    box.style.display = 'none';   // пока не показываем, ждём порог
    box.style.left = `${this.startX}px`;
    box.style.top = `${this.startY}px`;
    box.style.width = '0';
    box.style.height = '0';
  };

  /** Включаем рамку после порога */
  private selectionBoxPointerMove = (e: PointerEvent) => {
    if (!this.isSelectionCandidate && !this.isSelecting) return;

    const hostRect = this.getBoundingClientRect();

    const currentX = e.clientX - hostRect.left;
    const currentY = e.clientY - hostRect.top;

    // Если рамка ещё не активна — проверяем порог
    if (!this.isSelecting) {
      const dx = e.clientX - this.dragStartClientX;
      const dy = e.clientY - this.dragStartClientY;
      const distSq = dx * dx + dy * dy;
      const thresholdSq = DirectoryContentWC.DRAG_THRESHOLD * DirectoryContentWC.DRAG_THRESHOLD;

      if (distSq < thresholdSq) {
        // мышь почти не сдвинулась → ещё не считаем это drag-select
        return;
      }

      // Порог пройден — активируем рамку
      this.isSelecting = true;
      this.selectionBox!.style.display = 'block';

      // Как в классических проводниках: начинаем новую "рамочную" выборку
      this.unselect();
      this.dispatchSelectionChange();
    }

    const width = Math.abs(currentX - this.startX);
    const height = Math.abs(currentY - this.startY);
    const left = Math.min(this.startX, currentX);
    const top = Math.min(this.startY, currentY);

    const box = this.selectionBox!;
    box.style.left = `${left}px`;
    box.style.top = `${top}px`;
    box.style.width = `${width}px`;
    box.style.height = `${height}px`;

    this.selectItemsInSelectionBox(left, top, width, height);
  };

  /** Только если рамка реально была */
  private selectionBoxPointerUp = () => {
    if (this.isSelecting) {
      this.isSelecting = false;
      this.selectionBox!.style.display = 'none';// Если нужно скрывать прямоугольник после завершения выделения
      this.updateSelection();
    }

    this.isSelectionCandidate = false;
  };


  private unselect() {
    this.selectedItems.forEach(item => item.classList.remove('selected'));
    this.selectedItems.clear();
    this.lastSelectedItem = null;
  }

  private createHtml(folder: FolderEntity): HTMLElement[] {
    const liArray: HTMLElement[] = [];

    if (folder.folders instanceof Map) {
      folder.folders.forEach((folder: FolderEntity) => {
        const li = this.createFmItem(folder);
        liArray.push(li);
      });
    }

    if (folder.files instanceof Map) {
      folder.files.forEach((file: FileEntity) => {
        const li = this.createFmItem(file);
        liArray.push(li);
      });
    }

    return liArray;
  }

  private createFmItem(item: FileEntity | FolderEntity): HTMLLIElement {
    const li = document.createElement('li');
    li.classList.add('fm-item');

    const backgroundDiv = document.createElement('div');
    backgroundDiv.classList.add('fm-item-background');

    backgroundDiv.style.backgroundImage = `url(${this.iconHelper.getUrl(item)})`;
    // backgroundDiv.style.backgroundImage =  this.iconHelper.getUrl(item);
    li.appendChild(backgroundDiv);

    const descriptionDiv = document.createElement('div');
    descriptionDiv.classList.add('fm-item-description');
    descriptionDiv.textContent = item.name;

    li.dataset.type = item.type!;
    li.dataset.key = item.key;
    li.appendChild(descriptionDiv);

    // Контекстное меню / лонгтап → вместо bus.emit делаем CustomEvent
    detectContextMenuAndLongPress(li, (e: PointerEvent | MouseEvent) => {
      const pe = e as PointerEvent;

      // если при правом клике элемент ещё не выделен — выделяем его
      if (!li.classList.contains('selected')) {
        this.unselect();
        this.selectedItems.add(li);
        li.classList.add('selected');
        this.updateSelection();
      }

      this.dispatchEvent(
        new CustomEvent<DirectoryContextMenuDetail>('content-contextmenu', {
          detail: {
            type: (li.dataset.type as DirectoryItemType) ?? 'file',
            key: li.dataset.key ?? '',
            event: pe,
          },
          bubbles: true,
          composed: true,
        }),
      );
    });

    return li;
  }

  private selectItemsInSelectionBox(left: number, top: number, width: number, height: number) {
    const hostRect = this.getBoundingClientRect();
    const items = this.content!.querySelectorAll('.fm-item');

    const selectionRight = left + width;
    const selectionBottom = top + height;

    items.forEach(item => {
      const rect = item.getBoundingClientRect();
      const itemLeft = rect.left - hostRect.left;
      const itemTop = rect.top - hostRect.top;
      const itemRight = rect.right - hostRect.left;
      const itemBottom = rect.bottom - hostRect.top;

      const isInSelection =
        itemLeft < selectionRight &&
        itemRight > left &&
        itemTop < selectionBottom &&
        itemBottom > top;

      if (isInSelection) {
        this.selectedItems.add(item as HTMLElement);
        item.classList.add('selected');
      } else {
        this.selectedItems.delete(item as HTMLElement);
        item.classList.remove('selected');
      }
    });
  }

  private updateSelection() {
    const selectedItemsData: DirectorySelectionDetail = new Set();

    this.selectedItems.forEach((item: HTMLElement) => {
      const type = item.dataset.type;
      const key = item.dataset.key;

      if (typeof type !== "string" || typeof key !== "string") {
        throw new AppError('Нет обязательных аттрибутов у элемента');
      }
      if (type !== 'folder' && type !== 'file') {
        throw new AppError('Invalid type. Only "file" and "dir" allowed', {type: type});
      }

      selectedItemsData.add({type, key});
    });

    this.dispatchSelectionChange(selectedItemsData);
  }

  private dispatchSelectionChange(selection?: DirectorySelectionDetail) {
    const detail = selection ?? new Set<DirectoryItemDetail>();
    this.dispatchEvent(
      new CustomEvent<DirectorySelectionDetail>('selection-change', {
        detail,
        bubbles: true,
        composed: true,
      }),
    );
  }

}

customElements.define('dir-content-panel-wc', DirectoryContentWC);
