// src/features/directory-content/ui/helpers/IconHelper.ts

import {FolderEntity} from "@/entities/folder/model/FolderEntity";
import {FileEntity} from "@/entities/file/model/FileEntity";

import aiIcon from '@/shared/ui/icons/ai.svg';
import apkIcon from '@/shared/ui/icons/apk.svg';
import cssIcon from '@/shared/ui/icons/css.svg';
import dmgIcon from '@/shared/ui/icons/dmg.svg';
import docIcon from '@/shared/ui/icons/doc.svg';
import docxIcon from '@/shared/ui/icons/docx.svg';
import folderIcon from '@/shared/ui/icons/folder.svg';
import folderEmptyIcon from '@/shared/ui/icons/folder-empty.svg';
import gifIcon from '@/shared/ui/icons/gif.svg';
import htmlIcon from '@/shared/ui/icons/html.svg';
import jpgIcon from '@/shared/ui/icons/jpg.svg';
import mp3Icon from '@/shared/ui/icons/mp3.svg';
import mp4Icon from '@/shared/ui/icons/mp4.svg';
import nanIcon from '@/shared/ui/icons/nan.svg';
import odtIcon from '@/shared/ui/icons/odt.svg';
import pdfIcon from '@/shared/ui/icons/pdf.svg';
import pngIcon from '@/shared/ui/icons/png.svg';
import pptIcon from '@/shared/ui/icons/ppt.svg';
import pptxIcon from '@/shared/ui/icons/pptx.svg';
import psdIcon from '@/shared/ui/icons/psd.svg';
import rarIcon from '@/shared/ui/icons/rar.svg';
import svgIcon from '@/shared/ui/icons/svg.svg';
import txtIcon from '@/shared/ui/icons/txt.svg';
import xlsIcon from '@/shared/ui/icons/xls.svg';
import xlsxIcon from '@/shared/ui/icons/xlsx.svg';
import zipIcon from '@/shared/ui/icons/zip.svg';

export class IconHelper {
  /** Известные типы файлов */
  private iconMap: Map<string, string>;

  constructor() {
    // this.baseUrl = this.stateDispatcher.fmBaseUrl + '/assets/file-icons/';
    this.iconMap = new Map([
      ['ai', this.createDataURI(aiIcon)],
      ['apk', this.createDataURI(apkIcon)],
      ['css', this.createDataURI(cssIcon)],
      ['dmg', this.createDataURI(dmgIcon)],
      ['doc', this.createDataURI(docIcon)],
      ['docx', this.createDataURI(docxIcon)],
      ['folder', this.createDataURI(folderIcon)],
      ['folder-empty', this.createDataURI(folderEmptyIcon)],
      ['gif', this.createDataURI(gifIcon)],
      ['html', this.createDataURI(htmlIcon)],
      ['jpg', this.createDataURI(jpgIcon)],
      ['jpeg', this.createDataURI(jpgIcon)],
      ['mp3', this.createDataURI(mp3Icon)],
      ['mp4', this.createDataURI(mp4Icon)],
      ['nan', this.createDataURI(nanIcon)],
      ['odt', this.createDataURI(odtIcon)],
      ['pdf', this.createDataURI(pdfIcon)],
      ['png', this.createDataURI(pngIcon)],
      ['ppt', this.createDataURI(pptIcon)],
      ['pptx', this.createDataURI(pptxIcon)],
      ['psd', this.createDataURI(psdIcon)],
      ['rar', this.createDataURI(rarIcon)],
      ['svg', this.createDataURI(svgIcon)],
      ['txt', this.createDataURI(txtIcon)],
      ['xls', this.createDataURI(xlsIcon)],
      ['xlsx', this.createDataURI(xlsxIcon)],
      ['zip', this.createDataURI(zipIcon)],
    ]);
  }

  getUrl(item: FileEntity | FolderEntity): string {
    if (item instanceof FileEntity) {
      return String(this.getIconUrl(item.type, item.url, item.extension));
    } else {
      return String(this.getDirIconUrl(item.type, item.countChildDirs, item.countChildFiles));
    }
  }

  /**
   Возвращает строку Data URI, содержащую в себе иконку SVG (Base64).
   * @param type - Тип (передано с сервера). // file, link, dir, block, fifo, char, socket, unknown
   * @param url - Ссылка для скачивания файла с сервера (передаётся с сервера). // TODO Переделать на превью для изображений
   * @param extension - Расширение файла (передаётся с сервера).
   */
  getIconUrl(type: string | null, url: string | null, extension: string | null) {
    const defaultIcon = this.iconMap.get('nan');

    // 1. Для файлов без расширения
    if (extension == null) {
      return defaultIcon;
    }

    // 2. Если изображение, показываем само изображение
    // Внимание: Если вы хотите показывать *превью* изображения, а не иконку, то этот код должен остаться и возвращать URL.
    // Если вы хотите, чтобы для PNG/JPG тоже использовалась иконка, удалите этот блок.
    if (['png', 'jpg', 'jpeg', 'gif', 'webp'].includes(extension)) {
      // !!! Если вы хотите встроить превью, то нужен другой механизм! Если просто вернуть URL, то будет лишний HTTP-запрос.
      return '"' + url + '"'; // Пока оставляем URL для внешних изображений
    }

    // 3. Для всех остальных известных типов файлов
    const icon = this.iconMap.get(extension);
    if (icon) {
      return icon; // Возвращает Data URI строку
    }

    // 4. Иконка для неизвестного типа файлов
    return defaultIcon; // Возвращает Data URI строку
  }

  getDirIconUrl(type: string | null, countChildDirs: number | null, countChildFiles: number | null) {
    if (type === 'folder') {
      if ((countChildDirs && countChildDirs > 0) || (countChildFiles && countChildFiles > 0)) {
        return this.iconMap.get('folder'); // Возвращает Data URI строку
      } else {
        return this.iconMap.get('folder-empty'); // Возвращает Data URI строку
      }
    }
  }

  private createDataURI(svgString: any): string {
    // Очищаем SVG от лишних пробелов и переносов
    const cleaned = svgString.replace(/\s+/g, ' ').trim();
    // Кодируем для URL
    const encoded = encodeURIComponent(cleaned);
    return `data:image/svg+xml;utf8,${encoded}`;
  }

}
