// src/features/upload/model/UploadProgressFeature.ts

import { IFeature } from "@/shared/lib/Feature";
import type { FileManagerEventBus } from '@/shared/lib/EventBus';
import type { UploadProgressWC } from "@/shared/ui/upload-progress/UploadProgressPanel";
import type { UploadMinibarWC } from "@/shared/ui/upload-minibar/UploadMinibarWC";
import type { UploadStatus } from "@/features/upload/model/UploadStatus";

/**
 * Feature для управления UI прогресса загрузки.
 *
 * Управляет двумя компонентами:
 * 1. UploadProgressWC — панель со списком файлов (внизу справа)
 * 2. UploadMinibarWC — тонкая полоска прогресса вверху экрана
 *
 * Оба компонента работают синхронно и дублируют информацию о прогрессе
 * для улучшения UX (панель можно свернуть, но мини-бар всегда виден).
 */
export class UploadProgressFeature implements IFeature {
  private unsubs: Array<() => void> = [];

  constructor(
    private readonly bus: FileManagerEventBus,
    private readonly panel: UploadProgressWC,
    private readonly minibar?: UploadMinibarWC // Опционально для обратной совместимости
  ) {}

  init(): void {
    // === Начало загрузки ===
    this.unsubs.push(
      this.bus.on('upload:start', (files: FileList) => {
        this.panel.start(files);
        this.minibar?.start();
      })
    );

    // === Обновление прогресса ===
    this.unsubs.push(
      this.bus.on('upload:progress-full', (statuses: UploadStatus[]) => {
        this.panel.update(statuses);

        // Считаем общий прогресс для мини-бара
        if (this.minibar && statuses.length > 0) {
          const totalProgress = statuses.reduce((acc, s) => acc + s.progress, 0) / statuses.length;
          this.minibar.setProgress(totalProgress);

          // Устанавливаем состояние ошибки
          const hasError = statuses.some(s => s.status === 'failed');
          this.minibar.setError(hasError);
        }
      })
    );

    // === Завершение загрузки ===
    this.unsubs.push(
      this.bus.on('upload:complete-full', () => {
        this.panel.finish();
        this.minibar?.finish();
      })
    );

    // === События от UI ===

    // Отмена всех загрузок
    this.panel.addEventListener('cancel-all', () => {
      this.bus.emit('upload:cancel-all');
    });

    // Повтор загрузки файла
    this.panel.addEventListener('retry-file', ((e: CustomEvent<{ fileName: string }>) => {
      this.bus.emit('upload:retry', { fileName: e.detail.fileName });
    }) as EventListener);

    // При retry — снова показываем панель
    this.unsubs.push(
      this.bus.on('upload:retry', () => {
        this.panel.show();
        this.minibar?.start();
      })
    );

    // При ошибке загрузки — показываем панель
    this.unsubs.push(
      this.bus.on('upload:error', () => {
        this.panel.show();
        this.panel.expand();
      })
    );
  }

  destroy(): void {
    this.unsubs.forEach(fn => fn());
    this.unsubs = [];
  }
}
