// src/widgets/file-manager/ui/FileManagerLayout.ts
import { FileManagerRootWC } from "./FileManagerRootWC";

export class FileManagerLayout {
  public readonly root: FileManagerRootWC;

  constructor() {
    // TODO где-то здесь проверяем тип устройства (desktop - mobile) и рендерим разные компоненты (мышь - сенсор)
    // if (this.isMobile) {
    //   this.contentPanel = new DirectoryContentMobileWC(...);
    // } else {
    //   this.contentPanel = new DirectoryContentWC(...);
    // }
    this.root = new FileManagerRootWC();
    // Монтируем его в DOM (или это делает AppRuntime)
    document.body.appendChild(this.root);

    this.modal.openModal();
  }

  // Геттеры проксируют доступ к элементам внутри Root
  get tree() { return this.root.tree; }
  get content() { return this.root.content; }
  get modal() { return this.root.modal; }
  get loader() { return this.root.loader; }
  get alert() { return this.root.alert; }
  get dialog() { return this.root.dialog; }
  get split() { return this.root.split; }
  get dropZone() { return this.root.dropZone; }
  get menu() { return this.root.menu; }
  get contextMenu() { return this.root.contextMenu; }
  get uploadProgress() { return this.root.uploadProgress; }
  get toast() { return this.root.toast; }
  get log() { return this.root.log; }
  get footer() { return this.root.footer; }
  get uploadMiniBar() { return this.root.uploadMiniBar; }

  destroy() {
    this.root.remove();
  }
}
